/* ===== host-http-feedback.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.hostHttpFeedbackMounted) return;
  boot.hostHttpFeedbackMounted = true;

  const ROOT_ID = "mei-host-http-feedback-root";
  const DEDUPE_MS = 4000;
  const recent = new Map();

  function ensureRoot() {
    let root = document.getElementById(ROOT_ID);
    if (!root) {
      root = document.createElement("div");
      root.id = ROOT_ID;
      root.setAttribute("aria-live", "polite");
      root.setAttribute("aria-relevant", "additions");
      document.body.appendChild(root);
    }
    return root;
  }

  function statusTitle(status) {
    if (status === 401) return "需要登录";
    if (status === 403) return "访问被拒绝";
    if (status === 404) return "资源不存在";
    if (status >= 500) return "服务器错误";
    if (status >= 400) return "请求失败";
    return "HTTP 异常";
  }

  function requestUrlFromInput(input) {
    if (typeof input === "string") return input;
    if (input && typeof input.url === "string") return input.url;
    return "";
  }

  function isSameOriginApiRequest(url) {
    if (!url) return false;
    if (url.startsWith("/")) return url.includes("/api/");
    try {
      const parsed = new URL(url, window.location.origin);
      return (
        parsed.origin === window.location.origin && parsed.pathname.includes("/api/")
      );
    } catch (_) {
      return false;
    }
  }

  function isAuthFlowRequest(url) {
    const value = String(url || "");
    return (
      value.includes("/api/auth/login") ||
      value.includes("/api/auth/public-key") ||
      value.includes("/api/auth/session")
    );
  }

  function redirectToLogin(reason) {
    const auth = window.MeiHostAuthSession;
    if (auth && typeof auth.redirectToLogin === "function") {
      return auth.redirectToLogin(reason);
    }
    const path = window.location.pathname || "";
    if (path === "/login" || path.startsWith("/login/")) return false;
    const next = path + window.location.search + window.location.hash;
    window.location.assign(
      "/login?next=" + encodeURIComponent(next && next !== "/login" ? next : "/"),
    );
    return true;
  }

  async function recoverUnauthorizedRequest(input, init, nativeFetch) {
    const requestUrl = requestUrlFromInput(input);
    if (!isSameOriginApiRequest(requestUrl)) return null;
    if (isAuthFlowRequest(requestUrl) || requestUrl.includes("/api/auth/refresh")) {
      return null;
    }
    const auth = window.MeiHostAuthSession;
    if (!auth || typeof auth.recoverSessionForRequest !== "function") {
      redirectToLogin("session_expired");
      return null;
    }
    const recovered = await auth.recoverSessionForRequest();
    if (!recovered) return null;
    return nativeFetch(input, init);
  }

  function shouldSkipNotify(url, status) {
    if (Number(status) === 401) return true;
    if (!url || !String(url).includes("/api/")) return true;
    if (String(url).includes("/api/host/heartbeat")) return true;
    if (String(url).includes("/api/auth/refresh")) return true;
    if (String(url).includes("/api/agent/")) return true;
    if (String(url).includes("/api/auth/session") && Number(status) === 404) return true;
    if (
      Number(status) === 410 &&
      /\/api\/agent\/session\/[^/?]+\/(diff|revert|unrevert)(?:\?|$)/.test(String(url))
    ) {
      return true;
    }
    const key = String(status) + " " + String(url);
    const now = Date.now();
    const last = recent.get(key) || 0;
    if (now - last < DEDUPE_MS) return true;
    recent.set(key, now);
    return false;
  }

  function parseErrorDetail(text) {
    const raw = String(text || "").trim();
    if (!raw) return "";
    try {
      const payload = JSON.parse(raw);
      if (payload && typeof payload === "object") {
        return String(payload.error || payload.message || "").trim();
      }
    } catch (_) {}
    return raw.length > 240 ? raw.slice(0, 240) + "…" : raw;
  }

  function notify(payload) {
    const status = Number(payload && payload.status) || 0;
    if (!status) return;
    const url = String((payload && payload.url) || "");
    if (shouldSkipNotify(url, status)) return;

    const title = String((payload && payload.title) || statusTitle(status));
    const message = String((payload && payload.message) || "").trim() || "宿主拒绝了本次请求。";
    const tone = status >= 500 || status === 403 || status === 401 ? "error" : "warn";
    const root = ensureRoot();
    const banner = document.createElement("div");
    banner.className =
      "mei-host-http-banner" + (tone === "warn" ? " mei-host-http-banner--warn" : "");
    banner.innerHTML =
      '<div class="mei-host-http-banner__code">HTTP ' +
      String(status) +
      '</div><div class="mei-host-http-banner__body"><div class="mei-host-http-banner__title"></div><div class="mei-host-http-banner__message"></div><div class="mei-host-http-banner__hint"></div></div><button type="button" class="mei-host-http-banner__close" aria-label="关闭">×</button>';
    banner.querySelector(".mei-host-http-banner__title").textContent = title;
    banner.querySelector(".mei-host-http-banner__message").textContent = message;
    banner.querySelector(".mei-host-http-banner__hint").textContent =
      "请向管理员反馈错误代码 HTTP " + String(status) + "。";
    banner.querySelector(".mei-host-http-banner__close").addEventListener("click", () => {
      banner.remove();
    });
    root.prepend(banner);
    window.setTimeout(() => {
      if (banner.isConnected) banner.remove();
    }, 12000);
  }

  const nativeFetch = window.fetch.bind(window);
  window.fetch = async function meiHostFetch(input, init) {
    let response = await nativeFetch(input, init);
    const requestUrl = requestUrlFromInput(input);
    if (
      response.status === 401 &&
      isSameOriginApiRequest(requestUrl) &&
      !isAuthFlowRequest(requestUrl)
    ) {
      const retried = await recoverUnauthorizedRequest(
        input,
        init,
        nativeFetch,
      );
      if (retried) {
        response = retried;
      } else {
        redirectToLogin("session_expired");
      }
    }
    try {
      if (
        requestUrl &&
        (requestUrl.startsWith("/") || requestUrl.startsWith(window.location.origin)) &&
        requestUrl.includes("/api/")
      ) {
        if (!response.ok) {
          let detail = "";
          try {
            detail = parseErrorDetail(await response.clone().text());
          } catch (_) {}
          notify({
            status: response.status,
            url: requestUrl,
            message: detail || response.statusText || "请求失败",
          });
        }
      }
    } catch (_) {}
    return response;
  };

  window.MeiHostHttpFeedback = { notify, statusTitle };
  boot.notifyHostHttpError = notify;
})();


/* ===== host-auth-session.js ===== */
/**
 * 宿主登录态滑动续期：在 JWT 到期前静默调用 POST /api/auth/refresh。
 * 挂载 `window.MeiHostAuthSession`，在所有 --auth 已登录页面 bundle 中紧随 host-http-feedback.js 加载。
 */
(function () {
  if (window.MeiHostAuthSession) return;

  const DEFAULT_REFRESH_LEAD_MS = 30 * 60 * 1000;
  const MIN_REFRESH_DELAY_MS = 5000;

  let refreshTimerId = 0;
  let refreshInFlight = false;
  let redirectInFlight = false;
  let lastSessionPayload = null;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function readHostCapabilities() {
    const raw =
      document.body?.dataset?.meiAuthCapabilities ||
      readMeta("mei-auth-capabilities") ||
      "{}";
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === "object" ? parsed : {};
    } catch (_) {
      return {};
    }
  }

  function isAuthDisabledProfile(caps) {
    return Boolean(
      caps &&
        caps.access_view &&
        caps.config_upload &&
        caps.build_view &&
        caps.access_agent &&
        caps.agent_control &&
        caps.authoring_agent,
    );
  }

  function isLoggedIn() {
    const fromBody = String(document.body?.dataset?.meiAuthLoggedIn || "").trim();
    if (fromBody) return fromBody === "1";
    return readMeta("mei-auth-logged-in") === "1";
  }

  function shouldStart() {
    if (!isLoggedIn()) return false;
    return !isAuthDisabledProfile(readHostCapabilities());
  }

  function isLoginPath(pathname) {
    const path = String(pathname || window.location.pathname || "");
    return path === "/login" || path.startsWith("/login/");
  }

  function redirectToLogin(reason) {
    if (redirectInFlight || isLoginPath()) return false;
    redirectInFlight = true;
    clearRefreshTimer();
    const next =
      window.location.pathname + window.location.search + window.location.hash;
    const target =
      "/login?next=" +
      encodeURIComponent(next && next !== "/login" ? next : "/");
    if (reason) {
      try {
        sessionStorage.setItem("mei_auth_redirect_reason", String(reason));
      } catch (_) {}
    }
    window.location.assign(target);
    return true;
  }

  function clearRefreshTimer() {
    if (refreshTimerId) {
      clearTimeout(refreshTimerId);
      refreshTimerId = 0;
    }
  }

  function refreshLeadMs(payload) {
    const fromPayload = Number(payload && payload.refreshLeadSeconds);
    if (Number.isFinite(fromPayload) && fromPayload > 0) {
      return fromPayload * 1000;
    }
    return DEFAULT_REFRESH_LEAD_MS;
  }

  function dispatchSessionRefreshed(payload) {
    try {
      document.dispatchEvent(
        new CustomEvent("mei:auth-session-refreshed", {
          detail: payload && typeof payload === "object" ? payload : {},
        }),
      );
    } catch (_) {}
  }

  function dispatchSessionExpired(reason) {
    try {
      document.dispatchEvent(
        new CustomEvent("mei:auth-session-expired", {
          detail: { reason: String(reason || "session_expired") },
        }),
      );
    } catch (_) {}
  }

  function handleSessionLost(reason) {
    dispatchSessionExpired(reason);
    redirectToLogin(reason);
  }

  function scheduleRefreshFromPayload(payload) {
    clearRefreshTimer();
    if (!payload || !payload.authenticated || !payload.expiresAt) {
      return;
    }
    const expMs = Number(payload.expiresAt) * 1000;
    if (!Number.isFinite(expMs) || expMs <= 0) return;
    const leadMs = refreshLeadMs(payload);
    const delayMs = expMs - Date.now() - leadMs;
    if (delayMs <= 0) {
      refreshSession("lead_elapsed").catch(function () {});
      return;
    }
    refreshTimerId = setTimeout(function () {
      refreshTimerId = 0;
      refreshSession("scheduled").catch(function () {});
    }, Math.max(MIN_REFRESH_DELAY_MS, delayMs));
  }

  async function fetchSession() {
    const response = await fetch("/api/auth/session", { credentials: "same-origin" });
    if (!response.ok) {
      throw new Error("session check failed: " + response.status);
    }
    return response.json();
  }

  async function refreshSession(_reason) {
    if (refreshInFlight) return lastSessionPayload;
    refreshInFlight = true;
    try {
      const response = await fetch("/api/auth/refresh", {
        method: "POST",
        credentials: "same-origin",
        headers: { "content-type": "application/json" },
      });
      if (response.status === 401) {
        handleSessionLost("session_expired");
        throw new Error("session refresh unauthorized");
      }
      if (!response.ok) {
        throw new Error("session refresh failed: " + response.status);
      }
      const payload = await response.json();
      const sessionPayload = {
        enabled: true,
        authenticated: true,
        expiresAt: payload.expiresAt,
        jwtTtlSeconds: payload.jwtTtlSeconds,
        refreshLeadSeconds: payload.refreshLeadSeconds,
        user: payload.user || null,
      };
      lastSessionPayload = sessionPayload;
      scheduleRefreshFromPayload(sessionPayload);
      dispatchSessionRefreshed(sessionPayload);
      return sessionPayload;
    } finally {
      refreshInFlight = false;
    }
  }

  async function recoverSessionForRequest() {
    if (!shouldStart()) return false;
    try {
      const payload = await refreshSession("fetch_recovery");
      return !!(payload && payload.authenticated);
    } catch (_) {
      return false;
    }
  }

  async function bootstrap() {
    if (!shouldStart()) return;
    try {
      const payload = await fetchSession();
      lastSessionPayload = payload;
      if (!(payload && payload.authenticated)) {
        handleSessionLost("session_expired");
        return;
      }
      scheduleRefreshFromPayload(payload);
    } catch (_) {}
  }

  function onVisibilityChange() {
    if (document.visibilityState !== "visible") return;
    if (!shouldStart()) return;
    const payload = lastSessionPayload;
    if (!payload || !payload.authenticated || !payload.expiresAt) {
      bootstrap().catch(function () {});
      return;
    }
    const expMs = Number(payload.expiresAt) * 1000;
    if (Number.isFinite(expMs) && expMs > 0 && Date.now() >= expMs) {
      handleSessionLost("session_expired");
      return;
    }
    const leadMs = refreshLeadMs(payload);
    const refreshAtMs = expMs - leadMs;
    if (Date.now() >= refreshAtMs) {
      refreshSession("visibility").catch(function () {});
    }
  }

  document.addEventListener("visibilitychange", onVisibilityChange);

  window.MeiHostAuthSession = {
    bootstrap: bootstrap,
    refreshSession: refreshSession,
    recoverSessionForRequest: recoverSessionForRequest,
    redirectToLogin: redirectToLogin,
    scheduleRefreshFromPayload: scheduleRefreshFromPayload,
    getLastSessionPayload: function () {
      return lastSessionPayload;
    },
    dispose: function () {
      clearRefreshTimer();
      document.removeEventListener("visibilitychange", onVisibilityChange);
    },
  };

  bootstrap().catch(function () {});
})();


/* ===== host-heartbeat.js ===== */
/**
 * 宿主心跳：轮询 /api/host/heartbeat，在服务端失联或版本变更时提示用户刷新。
 */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.hostHeartbeatMounted) return;
  boot.hostHeartbeatMounted = true;

  const ROOT_ID = "mei-host-heartbeat-root";
  const HEARTBEAT_URL = "/api/host/heartbeat";
  const POLL_MS = 30000;
  const POLL_FAST_MS = 8000;
  const DISCONNECT_AFTER_STREAK = 2;
  const SUCCESS_VISIBLE_MS = 5000;

  let timerId = 0;
  let failureStreak = 0;
  let alertKind = "";
  let remoteVersion = "";
  let probeInFlight = false;
  let lastHeartbeat = null;
  let successTimerId = 0;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function pageBuildVersion() {
    return readMeta("mei-host-version");
  }

  function formatDurationMs(value) {
    if (value == null || value === "") return "";
    const ms = Number(value);
    if (!Number.isFinite(ms) || ms < 0) return "";
    if (ms < 1000) return Math.round(ms) + "ms";
    if (ms < 60000) return (ms / 1000).toFixed(1) + "s";
    const minutes = Math.floor(ms / 60000);
    const seconds = ((ms % 60000) / 1000).toFixed(1);
    return `${minutes}m ${seconds}s`;
  }

  function heartbeatPhaseLabel(phase) {
    const normalized = String(phase || "").trim().toLowerCase();
    const map = {
      starting: "启动中",
      bound: "已绑定，等待后台构建",
      building: "后台构建中",
      verifying: "校验中",
      degraded: "部分产物未就绪",
      failed: "后台构建失败",
      ready: "已就绪",
      skipped: "已跳过",
    };
    return map[normalized] || normalized || "未知状态";
  }

  function buildAlertCopy(payload) {
    const phase = String(payload?.phase || "").trim().toLowerCase();
    const activeJob = String(payload?.activeJob || "").trim();
    const activeElapsed = formatDurationMs(payload?.activeJobElapsedMs);
    const lastTotal = formatDurationMs(payload?.lastBuildTotalMs);
    const lastCompile = formatDurationMs(payload?.lastBuildCompileMs);
    const lastWarmup = formatDurationMs(payload?.lastBuildWarmupMs);
    const warningCount = Number(payload?.lastWarningCount || 0);
    const title =
      phase === "failed"
        ? "访问态构建失败"
        : phase === "degraded"
          ? "部分访问能力降级"
          : "访问态构建中";
    const lines = [
      `当前状态：${heartbeatPhaseLabel(phase)}`,
      activeJob ? `后台任务：${activeJob}` : "",
      activeElapsed ? `已耗时：${activeElapsed}` : "",
      lastTotal
        ? `最近一次构建：总计 ${lastTotal}${
            lastCompile ? `，编译 ${lastCompile}` : ""
          }${lastWarmup ? `，warmup ${lastWarmup}` : ""}`
        : "",
      warningCount > 0 ? `最近一次构建含 ${warningCount} 条 warning / 降级项。` : "",
      phase === "failed"
        ? "宿主已启动，但部分访问态产物构建失败；请到构建视图检查失败项。"
        : phase === "degraded"
          ? "宿主服务可用；部分页面或指标可能局部降级，未命中缺失产物的功能仍可正常访问。"
          : "宿主已启动，后台正在生成访问态产物；完成前部分页面或指标可能暂时不可用。",
    ].filter(Boolean);
    return { title, message: lines.join(" ") };
  }

  function buildSuccessCopy(payload) {
    const lastTotal = formatDurationMs(payload?.lastBuildTotalMs);
    const lastCompile = formatDurationMs(payload?.lastBuildCompileMs);
    const lastWarmup = formatDurationMs(payload?.lastBuildWarmupMs);
    const fullWarmupReady = payload?.fullWarmupReady === true;
    const message = [
      fullWarmupReady
        ? "OK! 全量访问态产物已就绪，现在可以正常访问页面。"
        : "OK! 关键访问态产物已就绪，后台仍在生成 deferred 产物。",
      lastTotal
        ? `最近一次构建：总计 ${lastTotal}${
            lastCompile ? `，编译 ${lastCompile}` : ""
          }${lastWarmup ? `，warmup ${lastWarmup}` : ""}`
        : "",
    ]
      .filter(Boolean)
      .join(" ");
    return {
      title: fullWarmupReady ? "FULL READY! 全量预热完成" : "ACCESS READY! 访问态已就绪",
      message,
    };
  }

  function shouldRun() {
    if (document.body && document.body.dataset.meiCompileShell === "true") {
      return false;
    }
    if (pageBuildVersion()) return true;
    const path = window.location.pathname || "";
    return (
      path === "/host" ||
      path === "/login" ||
      path.startsWith("/account/") ||
      path.startsWith("/logout")
    );
  }

  function currentPageAppId() {
    const fromRuntime = String(window.__meiRuntimeAppId || "").trim();
    if (fromRuntime) return fromRuntime;
    const match = String(window.location.pathname || "").match(
      /^\/apps\/[^/]+\/([^/]+)/,
    );
    return match ? String(match[1] || "").trim() : "";
  }

  function isShellSurface() {
    const path = window.location.pathname || "";
    return (
      path === "/host" ||
      path === "/login" ||
      path.startsWith("/account/") ||
      path.startsWith("/logout")
    );
  }

  function appAccessReadyFromPayload(payload, appId) {
    if (!payload || !appId) return false;
    const apps = Array.isArray(payload.apps) ? payload.apps : [];
    const entry = apps.find((app) => String(app?.appId || "").trim() === appId);
    if (entry) return entry.accessReady === true;
    return false;
  }

  function ensureRoot() {
    let root = document.getElementById(ROOT_ID);
    if (!root) {
      root = document.createElement("div");
      root.id = ROOT_ID;
      root.setAttribute("aria-live", "assertive");
      root.setAttribute("aria-relevant", "additions");
      document.body.appendChild(root);
    }
    return root;
  }

  function clearBanner() {
    const root = document.getElementById(ROOT_ID);
    if (root) root.innerHTML = "";
  }

  function cancelSuccessTimer() {
    if (successTimerId) {
      clearTimeout(successTimerId);
      successTimerId = 0;
    }
  }

  function renderBanner(kind, payload) {
    const root = ensureRoot();
    const pageVersion = pageBuildVersion();
    const isVersion = kind === "version";
    const isBuild = kind === "build";
    const isSuccess = kind === "success";
    const title = isVersion
      ? "服务端已更新"
      : isSuccess
        ? buildSuccessCopy(payload).title
      : isBuild
        ? buildAlertCopy(payload).title
        : "服务端失联";
    const message = isVersion
      ? "当前页面版本为 " +
        (pageVersion || "未知") +
        "，服务端版本为 " +
        (remoteVersion || "未知") +
        "。请刷新页面以加载新版本。"
      : isSuccess
        ? buildSuccessCopy(payload).message
      : isBuild
        ? buildAlertCopy(payload).message
        : "无法连接宿主服务，请检查网络或联系管理员后刷新页面。";
    const toneClass = isVersion
      ? " mei-host-heartbeat-banner--version"
      : isSuccess
        ? " mei-host-heartbeat-banner--success"
      : " mei-host-heartbeat-banner--offline";

    root.innerHTML =
      '<div class="mei-host-heartbeat-banner' +
      toneClass +
      '" role="alert">' +
      '<div class="mei-host-heartbeat-banner__icon" aria-hidden="true">' +
      (isVersion ? "↑" : isSuccess ? "OK" : "!") +
      '</div><div class="mei-host-heartbeat-banner__body">' +
      '<div class="mei-host-heartbeat-banner__title"></div>' +
      '<div class="mei-host-heartbeat-banner__message"></div>' +
      '<div class="mei-host-heartbeat-banner__actions">' +
      '<button type="button" class="mei-host-heartbeat-banner__btn mei-host-heartbeat-banner__btn--primary" data-action="reload">刷新页面</button>' +
      (isVersion || isSuccess
        ? ""
        : '<button type="button" class="mei-host-heartbeat-banner__btn" data-action="retry">重试连接</button>') +
      "</div></div></div>";

    const banner = root.querySelector(".mei-host-heartbeat-banner");
    banner.querySelector(".mei-host-heartbeat-banner__title").textContent = title;
    banner.querySelector(".mei-host-heartbeat-banner__message").textContent = message;
    banner.querySelector('[data-action="reload"]').addEventListener("click", () => {
      window.location.reload();
    });
    const retry = banner.querySelector('[data-action="retry"]');
    if (retry) {
      retry.addEventListener("click", () => {
        tick();
      });
    }
  }

  function setAlert(kind) {
    if (alertKind === kind) return;
    cancelSuccessTimer();
    alertKind = kind;
    if (!kind) {
      clearBanner();
      return;
    }
    renderBanner(kind, lastHeartbeat);
    if (kind === "success") {
      successTimerId = window.setTimeout(() => {
        successTimerId = 0;
        if (alertKind === "success") {
          setAlert("");
        }
      }, SUCCESS_VISIBLE_MS);
    }
    try {
      document.dispatchEvent(
        new CustomEvent("mei:host-heartbeat-alert", {
          detail: { kind, remoteVersion, pageVersion: pageBuildVersion(), payload: lastHeartbeat },
        }),
      );
    } catch (_) {}
  }

  function scheduleNext() {
    if (timerId) clearTimeout(timerId);
    const delay = alertKind === "offline" || alertKind === "build" ? POLL_FAST_MS : POLL_MS;
    timerId = window.setTimeout(tick, delay);
  }

  function isActivelyBuilding(payload) {
    const phase = String(payload?.phase || "").trim().toLowerCase();
    const activeJob = String(payload?.activeJob || "").trim();
    return (
      activeJob &&
      (phase === "building" || phase === "verifying" || phase === "starting")
    );
  }

  function isHostServiceable(payload) {
    return payload?.hostReady === true || payload?.ready === true;
  }

  function isAccessFullyReady(payload) {
    if (isShellSurface()) {
      return isHostServiceable(payload);
    }
    const appId = currentPageAppId();
    if (appId) {
      return appAccessReadyFromPayload(payload, appId);
    }
    return payload?.accessReady === true || payload?.anyAppAccessReady === true;
  }

  async function tick() {
    if (!shouldRun() || probeInFlight) return;
    probeInFlight = true;
    try {
      const response = await fetch(HEARTBEAT_URL, {
        method: "GET",
        cache: "no-store",
        credentials: "same-origin",
        headers: { accept: "application/json" },
      });
      if (!response.ok) {
        throw new Error("heartbeat status " + String(response.status));
      }
      const payload = await response.json();
      lastHeartbeat = payload && typeof payload === "object" ? payload : null;
      const nextVersion = String((payload && payload.buildVersion) || "").trim();
      remoteVersion = nextVersion;
      failureStreak = 0;

      const pageVersion = pageBuildVersion();
      if (pageVersion && nextVersion && pageVersion !== nextVersion) {
        setAlert("version");
        return;
      }
      if (!isHostServiceable(payload)) {
        if (alertKind === "build") {
          renderBanner("build", lastHeartbeat);
        } else {
          setAlert("build");
        }
        return;
      }
      if (
        !isShellSurface() &&
        !isAccessFullyReady(payload) &&
        isActivelyBuilding(payload)
      ) {
        if (alertKind === "build") {
          renderBanner("build", lastHeartbeat);
        } else {
          setAlert("build");
        }
        return;
      }
      if (isAccessFullyReady(payload) && alertKind === "build") {
        setAlert("success");
        return;
      }
      if (alertKind === "build") {
        setAlert("");
        return;
      }
      if (alertKind === "offline") {
        setAlert("");
      }
    } catch (_) {
      failureStreak += 1;
      if (failureStreak >= DISCONNECT_AFTER_STREAK) {
        setAlert("offline");
      }
    } finally {
      probeInFlight = false;
      if (shouldRun()) scheduleNext();
    }
  }

  function stop() {
    if (timerId) {
      clearTimeout(timerId);
      timerId = 0;
    }
    boot.hostHeartbeatMounted = false;
  }

  function start() {
    if (!shouldRun()) return;
    tick();
    document.addEventListener("visibilitychange", onVisibilityChange);
  }

  function onVisibilityChange() {
    if (document.visibilityState === "visible" && shouldRun()) {
      tick();
    }
  }

  boot.disposeHostHeartbeat = function () {
    document.removeEventListener("visibilitychange", onVisibilityChange);
    stop();
    clearBanner();
  };

  window.MeiHostHeartbeat = {
    tick,
    getAlertKind: () => alertKind,
  };

  start();
})();


/* ===== host-shell-ops.js ===== */
/**
 * mei-host-shell ops helpers (used by host-runtime-console.js).
 */
(function (global) {
  "use strict";

  global.MeiHostShellOps = {
    refreshPanel: () =>
      global.MeiHostRuntimeConsole && global.MeiHostRuntimeConsole.refreshConsole
        ? global.MeiHostRuntimeConsole.refreshConsole()
        : Promise.resolve(false),
    initHostShellOps: () => {},
  };
})(typeof window !== "undefined" ? window : globalThis);


/* ===== host-runtime-console.js ===== */
/**
 * host-shell runtime checkbench:
 * - grouped nav: Host / Navigation / Scope Gate / Warmup / MRG / Cache / Diagnostics
 * - contextual detail panel
 * - current-node JSON vs full-snapshot JSON
 */
(function (global) {
  "use strict";

  const STATUS_URL = "/api/host/ops/status";
  const RELOAD_URL = "/api/host/ops/reload";
  const PREBUILD_URL = "/api/host/ops/prebuild";
  const ACTIVATE_SCOPE_URL = "/api/host/mrg/activate";
  const SNAPSHOT_URL = "/api/runtime/snapshot";

  let pollTimer = null;
  let snapshotCache = null;
  let opsCache = null;

  function appIdFromShell() {
    const shell = document.querySelector("[data-runtime-node][data-app-path], .shell[data-app-path]");
    return shell ? String(shell.getAttribute("data-app-path") || "").trim() : "";
  }

  function activeNodeFromUrl() {
    try {
      return new URL(global.location.href).searchParams.get("node") || "";
    } catch (_error) {
      return "";
    }
  }

  function activeNodeFromShell() {
    const shell = document.querySelector("[data-runtime-node]");
    return shell ? String(shell.getAttribute("data-runtime-node") || "").trim() : "";
  }

  function defaultNodeId(snapshot) {
    const scopeId = snapshot?.scopes?.[0]?.nodeId;
    return scopeId || "ops:overview";
  }

  function resolveActiveNode(snapshot) {
    const fromUrl = activeNodeFromUrl();
    if (fromUrl) return fromUrl;
    const fromShell = activeNodeFromShell();
    if (fromShell && fromShell !== "overview-host") return fromShell;
    return defaultNodeId(snapshot);
  }

  function syncShellNodeFromUrl() {
    const nodeId = activeNodeFromUrl();
    if (!nodeId) return;
    const shell = document.querySelector("[data-runtime-node]");
    if (shell) shell.setAttribute("data-runtime-node", nodeId);
  }

  function runtimeHref(appId, nodeId) {
    const base = `/apps/runtime/${encodeURIComponent(appId)}`;
    if (!nodeId) return base;
    return `${base}?node=${encodeURIComponent(nodeId)}`;
  }

  function navigateToNode(nodeId, options) {
    const appId = appIdFromShell();
    if (!appId || !nodeId) return;
    const url = runtimeHref(appId, nodeId);
    const shell = document.querySelector("[data-runtime-node]");
    if (shell) shell.setAttribute("data-runtime-node", nodeId);
    if (options && options.replace) {
      global.history.replaceState({ hostRuntimeNode: nodeId }, "", url);
    } else {
      global.history.pushState({ hostRuntimeNode: nodeId }, "", url);
    }
    if (opsCache && snapshotCache) {
      paintConsole(appId, opsCache, snapshotCache);
    }
  }

  function phaseLabel(phase) {
    return (
      {
        starting: "启动中",
        bound: "已绑定（compile/import 完成，warmup 未就绪）",
        ready: "就绪（MRG / warmup 可观测）",
      }[phase] || phase || "-"
    );
  }

  function boolText(value) {
    return value ? "是" : "否";
  }

  function escapeHtml(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function prettyJson(value) {
    try {
      return JSON.stringify(value == null ? {} : value, null, 2);
    } catch (_error) {
      return String(value);
    }
  }

  function formatMaybe(value) {
    if (value == null || value === "") return "-";
    if (typeof value === "boolean") return boolText(value);
    if (typeof value === "number") return String(value);
    if (Array.isArray(value)) return value.length ? value.join(", ") : "-";
    if (typeof value === "object") return prettyJson(value);
    return String(value);
  }

  function formatBytes(bytes) {
    if (typeof bytes !== "number" || !Number.isFinite(bytes)) return "-";
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KiB`;
    if (bytes < 1024 * 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MiB`;
    return `${(bytes / 1024 / 1024 / 1024).toFixed(2)} GiB`;
  }

  function formatMs(ms) {
    return typeof ms === "number" && Number.isFinite(ms) ? `${ms}ms` : "-";
  }

  function statusBadge(label, ok) {
    return `<span class="host-shell-ops-badge ${ok ? "is-ready" : ""}">${escapeHtml(label)}</span>`;
  }

  function hintBlock(lines) {
    const items = (lines || [])
      .filter(Boolean)
      .map((line) => `<li>${escapeHtml(line)}</li>`)
      .join("");
    if (!items) return "";
    return `
<section class="rounded-lg border border-white/10 bg-black/10 p-3">
  <h3 class="mb-2 mei-font-2 mei-text-primary">排障提示</h3>
  <ul class="grid gap-1 mei-font-1 mei-text-muted">${items}</ul>
</section>`;
  }

  function kvTable(rows) {
    return `<dl class="host-runtime-kv">${rows
      .map(([label, value]) => `<div><dt>${escapeHtml(label)}</dt><dd>${value}</dd></div>`)
      .join("")}</dl>`;
  }

  function shellLink(nodeId, label, meta, activeNode, extraClass) {
    const appId = appIdFromShell();
    const cls = [extraClass || "host-runtime-nav-link", activeNode === nodeId ? "is-active" : ""]
      .filter(Boolean)
      .join(" ");
    const metaHtml = meta ? `<span class="host-runtime-nav-meta">${escapeHtml(meta)}</span>` : "";
    return `<a class="${cls}" href="${runtimeHref(appId, nodeId)}" data-runtime-node="${escapeHtml(
      nodeId,
    )}" data-runtime-node-link="1"><span>${escapeHtml(label)}</span>${metaHtml}</a>`;
  }

  function allScopes(snapshot) {
    return Array.isArray(snapshot?.scopes) ? snapshot.scopes : [];
  }

  function allRoutes(snapshot) {
    return Array.isArray(snapshot?.navigation?.routes) ? snapshot.navigation.routes : [];
  }

  function allSlots(snapshot) {
    return Array.isArray(snapshot?.mrg?.slots) ? snapshot.mrg.slots : Array.isArray(snapshot?.slots) ? snapshot.slots : [];
  }

  function findScope(snapshot, scopeKey) {
    return allScopes(snapshot).find((scope) => scope.scopeKey === scopeKey) || null;
  }

  function findRoute(snapshot, nodeId) {
    return allRoutes(snapshot).find((route) => route.nodeId === nodeId) || null;
  }

  function findSlot(snapshot, nodeId) {
    return allSlots(snapshot).find((slot) => slot.nodeId === nodeId) || null;
  }

  function routesOfScope(snapshot, scopeKey) {
    return allRoutes(snapshot).filter((route) => route.scopeKey === scopeKey);
  }

  function slotsOfScope(snapshot, scopeKey) {
    return allSlots(snapshot).filter((slot) => slot.scopeKey === scopeKey);
  }

  function scopeStatus(scope) {
    const blockers = Array.isArray(scope?.blockers) ? scope.blockers : [];
    if (!scope) return "unknown";
    if (blockers.length === 0) return "ready";
    if ((scope.failedSlots || 0) > 0 || (scope.staleSlots || 0) > 0) return "degraded";
    if ((scope.routeCount || 0) === 0) return "missing";
    return "warming";
  }

  function detailSection(title, bodyHtml, subtext) {
    return `
<section class="host-runtime-detail-panel">
  <header class="host-runtime-detail-head">
    <div>
      <h2 class="host-runtime-detail-title">${escapeHtml(title)}</h2>
      ${subtext ? `<p class="host-runtime-detail-sub">${escapeHtml(subtext)}</p>` : ""}
    </div>
  </header>
  ${bodyHtml}
</section>`;
  }

  function renderNav(appId, snapshot, activeNode) {
    const scopes = allScopes(snapshot);
    const warmupScopes = scopes
      .filter((scope) => (scope.dirtySlots || 0) > 0)
      .map((scope) =>
        shellLink(
          `warmup:scope:${scope.scopeKey}`,
          `scope · ${scope.scopeKey}`,
          `${scope.dirtySlots || 0} dirty`,
          activeNode,
        ),
      )
      .join("");
    const scopeLinks = scopes
      .map((scope) =>
        shellLink(
          `scope:${scope.scopeKey}`,
          `scope · ${scope.scopeKey}`,
          `${scope.routeCount || 0} routes · ${scope.slotCount || 0} slots`,
          activeNode,
        ),
      )
      .join("");
    return `
<nav class="host-runtime-nav" aria-label="Host 运行检查台导航">
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">Host / Ops</div>
    ${shellLink("ops:overview", "运行状态", null, activeNode)}
    ${shellLink("ops:versions", "运行版本", null, activeNode)}
  </div>
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">Navigation</div>
    ${shellLink("nav:summary", "入口总览", `${snapshot?.navigation?.routeCount || 0} routes`, activeNode)}
    ${scopeLinks}
  </div>
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">Scope Gate</div>
    ${shellLink("gate:summary", "就绪判定", `${snapshot?.scopeGate?.degradedScopes?.length || 0} degraded`, activeNode)}
  </div>
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">Warmup</div>
    ${shellLink("warmup:summary", "预热计划", `${snapshot?.warmup?.dirtySlotCount || 0} dirty`, activeNode)}
    ${warmupScopes}
  </div>
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">MRG</div>
    ${shellLink("mrg:summary", "MRG 总览", `${snapshot?.mrg?.slotCount || 0} slots`, activeNode)}
    ${shellLink("mrg:failed", "失败 slots", `${snapshot?.mrg?.failedSlots?.length || 0}`, activeNode)}
    ${shellLink("mrg:slots", "全部 slots", null, activeNode)}
  </div>
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">Cache / Artifact</div>
    ${shellLink("cache:summary", "缓存与产物", null, activeNode)}
  </div>
  <div class="host-runtime-nav-section">
    <div class="host-runtime-nav-heading">Diagnostics</div>
    ${shellLink("diag:summary", "诊断与告警", `${snapshot?.diagnostics?.alerts?.length || 0} alerts`, activeNode)}
  </div>
</nav>`;
  }

  function renderVersionDetail(ops, snapshot) {
    const binary = ops?.binary || {};
    const build = snapshot?.diagnostics?.build || {};
    const meilang =
      ops?.version?.meilangVersion ||
      ops?.version?.workspace?.meilangVersion ||
      binary.meilangVersion ||
      binary.cargo_package_version ||
      "-";
    const buildGeneration =
      ops?.version?.buildGeneration ||
      ops?.version?.workspace?.buildGeneration ||
      build.buildGeneration ||
      "-";
    const buildDisplayTag =
      ops?.version?.buildDisplayTag ||
      ops?.version?.workspace?.buildDisplayTag ||
      (buildGeneration !== "-" ? `Build ${buildGeneration}` : "-");
    return detailSection(
      "运行版本",
      kvTable([
        ["MeiLang", escapeHtml(meilang)],
        ["Build generation", escapeHtml(buildGeneration)],
        ["Shell build", escapeHtml(binary.build_version || "-")],
        ["Build tag", escapeHtml(buildDisplayTag)],
        ["Workspace date", escapeHtml(ops?.workspaceVersion || build.workspaceVersion || "-")],
        ["Env active (ops)", escapeHtml(ops?.env?.active || build.envActive || "-")],
        ["Env candidate", escapeHtml(ops?.env?.candidate || "-")],
        ["Env previous", escapeHtml(ops?.env?.previous || "-")],
        ["Git", escapeHtml(`${binary.git?.commit_short || "-"} @ ${binary.git?.branch || "-"}`)],
      ]) +
        hintBlock([
          "MeiLang 版本表示工具链；Build generation 表示当前工作区构建代。",
          "Env active 为内部目录指针，供运维诊断使用。",
        ]),
      ops?.version?.displayLabel || ops?.displayLabel || "",
    );
  }

  function jobLine(ops) {
    const job = ops?.job;
    const lastJob = ops?.lastJob;
    if (job) {
      return `<p class="host-shell-ops-job">进行中：${escapeHtml(job.kind)} · ${escapeHtml(
        job.status || "running",
      )}</p>`;
    }
    if (!lastJob) return "";
    const details = [lastJob.message, lastJob.error].filter(Boolean).join(" · ");
    return `<p class="host-shell-ops-job">最近：${escapeHtml(lastJob.kind || "-")} · ${escapeHtml(
      lastJob.status || "-",
    )}${details ? ` · ${escapeHtml(details)}` : ""}</p>`;
  }

  function renderOpsDetail(ops, snapshot) {
    const gate = snapshot?.scopeGate || {};
    const defaultScope = gate.defaultScope || "-";
    return detailSection(
      "运行状态",
      `<div class="host-shell-ops-badges">
        ${statusBadge(`phase: ${phaseLabel(ops?.phase || snapshot?.host?.phase)}`, true)}
        ${statusBadge(`accessReady: ${boolText(!!ops?.accessReady)}`, !!ops?.accessReady)}
        ${statusBadge(`warmupReady: ${boolText(!!ops?.warmupReady)}`, !!ops?.warmupReady)}
        ${statusBadge(`scopeGate: ${boolText(!!snapshot?.host?.scopeGateReady)}`, !!snapshot?.host?.scopeGateReady)}
      </div>
      ${jobLine(ops)}
      ${kvTable([
        ["默认 scope", escapeHtml(defaultScope)],
        ["scope blockers", escapeHtml((gate.blockers || []).join(" | ") || "-")],
        ["prebuild plan", escapeHtml(snapshot?.warmup?.planSource || "-")],
        ["dirty slots", escapeHtml(String(snapshot?.warmup?.dirtySlotCount || 0))],
      ])}
      <div class="host-runtime-actions">
        <button type="button" class="mei-btn mei-btn--sm" data-host-ops="refresh">刷新状态</button>
        <button type="button" class="mei-btn mei-btn--sm" data-host-ops="reload">重新加载（compile + import）</button>
        <button type="button" class="mei-btn mei-btn--sm mei-btn--accent" data-host-ops="prebuild">完整预构建</button>
      </div>
      ${hintBlock([
        "reload = compile + import，用于刷新当前 app 的编译与 registry。",
        "prebuild = standard policy，会推进数据、warmup 与 finalize。",
        "停止/重启进程、promote/rollback、verify-only 等细粒度运维仍保留在 CLI/脚本。",
      ])}`,
      "同页同时承载安全动作与运行证据，但不把所有脚本语义都伪装成按钮。",
    );
  }

  function renderNavigationSummary(snapshot) {
    const routes = allRoutes(snapshot);
    const scopes = allScopes(snapshot);
    const rows = scopes
      .map(
        (scope) =>
          `<tr>
            <td>${shellLink(`scope:${scope.scopeKey}`, `scope · ${scope.scopeKey}`, null, "", "build-toolbar-btn")}</td>
            <td>${escapeHtml(String(scope.routeCount || 0))}</td>
            <td>${escapeHtml(String(scope.slotCount || 0))}</td>
            <td>${escapeHtml(scope.accessUrl || "-")}</td>
          </tr>`,
      )
      .join("");
    return detailSection(
      "入口总览",
      kvTable([
        ["routes", escapeHtml(String(routes.length))],
        ["scopes", escapeHtml(String(scopes.length))],
        ["duplicate routes", escapeHtml(String(snapshot?.navigation?.duplicateRouteCount || 0))],
        ["orphan urls", escapeHtml(String(snapshot?.navigation?.orphanUrlCount || 0))],
      ]) +
        `<div class="host-runtime-table-wrap">
          <table class="host-runtime-table">
            <thead><tr><th>Scope</th><th>Routes</th><th>Slots</th><th>默认入口</th></tr></thead>
            <tbody>${rows || `<tr><td colspan="4">暂无入口</td></tr>`}</tbody>
          </table>
        </div>` +
        hintBlock([
          "这里的 route 是入口登记，不是 MRG scope 节点本身。",
          "同一 scope 对应多条 route 时会在 scope 详情里展开真实入口列表，不再重复伪装成多个 scene 节点。",
        ]),
      "从 route 看入口分布，再钻到 scope 看 gate / warmup / slot。",
    );
  }

  function renderRouteDetail(snapshot, route) {
    if (!route) return renderNavigationSummary(snapshot);
    const scope = findScope(snapshot, route.scopeKey);
    return detailSection(
      `Route · ${route.sceneId || route.scopeKey || "-"}`,
      kvTable([
        ["scope", shellLink(`scope:${route.scopeKey}`, `scope · ${route.scopeKey}`, null, "", "build-toolbar-btn")],
        ["url", escapeHtml(route.url || "-")],
        ["assemblyKey", escapeHtml(route.assemblyKey || "-")],
        ["sceneId", escapeHtml(route.sceneId || "-")],
        ["scope slots", escapeHtml(String(scope?.slotCount || 0))],
      ]) +
        `<div class="host-runtime-actions">
          ${route.url ? `<a class="mei-btn mei-btn--sm" href="${escapeHtml(route.url)}">打开访问入口</a>` : ""}
        </div>` +
        hintBlock([
          "route 只说明入口与装配归属，不直接表示 slot 是否已 warmup/命中缓存。",
          "判断运行就绪请继续看对应 scope 或 slot 详情。",
        ]),
      "route / scope / slot 是三种不同对象，不应混成同一列。",
    );
  }

  function renderScopeDetail(snapshot, scopeKey) {
    const scope = findScope(snapshot, scopeKey);
    if (!scope) return renderNavigationSummary(snapshot);
    const routes = routesOfScope(snapshot, scopeKey);
    const slots = slotsOfScope(snapshot, scopeKey);
    const status = scopeStatus(scope);
    const routeRows = routes
      .map(
        (route) =>
          `<tr>
            <td>${shellLink(route.nodeId, route.sceneId || route.scopeKey, null, "", "build-toolbar-btn")}</td>
            <td>${escapeHtml(route.url || "-")}</td>
            <td>${escapeHtml(route.assemblyKey || "-")}</td>
          </tr>`,
      )
      .join("");
    return detailSection(
      `Scope · ${scopeKey}`,
      `<div class="host-shell-ops-badges">
        ${statusBadge(`status: ${status}`, status === "ready")}
        ${statusBadge(`routes: ${scope.routeCount || 0}`, (scope.routeCount || 0) > 0)}
        ${statusBadge(`dirty: ${scope.dirtySlots || 0}`, (scope.dirtySlots || 0) === 0)}
      </div>
      <div class="host-runtime-actions">
        ${scope.accessUrl ? `<a class="mei-btn mei-btn--sm" href="${escapeHtml(scope.accessUrl)}">打开默认入口</a>` : ""}
        <button type="button" class="mei-btn mei-btn--sm" data-host-ops="activate-scope" data-host-scope="${escapeHtml(scopeKey)}">补热当前 scope（1-hop）</button>
        <button type="button" class="mei-btn mei-btn--sm" data-host-ops="refresh">刷新状态</button>
      </div>
      ${kvTable([
        ["routeCount", escapeHtml(String(scope.routeCount || 0))],
        ["slotCount", escapeHtml(String(scope.slotCount || 0))],
        ["readySlots", escapeHtml(String(scope.readySlots || 0))],
        ["staleSlots", escapeHtml(String(scope.staleSlots || 0))],
        ["failedSlots", escapeHtml(String(scope.failedSlots || 0))],
        ["dirtySlots", escapeHtml(String(scope.dirtySlots || 0))],
        ["clientEligibleSlots", escapeHtml(String(scope.clientEligibleSlots || 0))],
        ["worksetIds", escapeHtml((scope.worksetIds || []).join(", ") || "-")],
        ["blockers", escapeHtml((scope.blockers || []).join(" | ") || "-")],
      ])}
      <div class="host-runtime-table-wrap">
        <table class="host-runtime-table">
          <thead><tr><th>Route</th><th>URL</th><th>Assembly</th></tr></thead>
          <tbody>${routeRows || `<tr><td colspan="3">暂无 route</td></tr>`}</tbody>
        </table>
      </div>
      ${renderSlotsTable(slots, { title: `Scope ${scopeKey} 的 slots`, scopeFirst: false })}
      ${hintBlock([
        "scope 是 gate / warmup / materialization 的落点；多条 route 进入同一 scope 不代表存在多份 MRG scope。",
        "clientEligible 仅表示可写入 client tier 的资格，不代表浏览器当前 tab 已命中。",
        "若要进一步核对四层 readiness，请回到 readiness / scope-gate / block CLI。",
      ])}`,
      "这个面板应该能直接回答：入口有哪些、slot 状态怎样、为什么 ready / degraded。",
    );
  }

  function renderGateSummary(snapshot) {
    const gate = snapshot?.scopeGate || {};
    const degradedScopes = Array.isArray(gate.degradedScopes) ? gate.degradedScopes : [];
    const degradedLinks = degradedScopes
      .map((scopeKey) => shellLink(`scope:${scopeKey}`, `scope · ${scopeKey}`, null, "", "build-toolbar-btn"))
      .join(" ");
    return detailSection(
      "Scope Gate",
      kvTable([
        ["defaultScope", escapeHtml(gate.defaultScope || "-")],
        ["accessReady", escapeHtml(boolText(!!gate.accessReady))],
        ["shellReady", escapeHtml(boolText(!!gate.shellReady))],
        ["dataReady", escapeHtml(boolText(!!gate.dataReady))],
        ["blockers", escapeHtml((gate.blockers || []).join(" | ") || "-")],
        ["L2/L3/L4 sweep", escapeHtml(prettyJson(gate.scopeGateSweep || {}))],
      ]) +
        (degradedLinks
          ? `<section class="rounded-lg border border-white/10 bg-black/10 p-3">
              <h3 class="mb-2 mei-font-2 mei-text-primary">Degraded scopes</h3>
              <div class="flex flex-wrap gap-2">${degradedLinks}</div>
            </section>`
          : "") +
        hintBlock([
          "host-shell 当前给出的是轻量 gate 摘要，用于说明入口、装配和物化是否能继续观测。",
          "当你需要严格的 L2/L3/L4 parity 时，请结合 readiness / scope-gate CLI 与磁盘证据。",
        ]),
      "把“为什么不 ready”先压缩成 blockers，再决定是否回到 CLI。",
    );
  }

  function renderWarmupSummary(snapshot) {
    const warmup = snapshot?.warmup || {};
    const hotScopes = Array.isArray(warmup.hotScopes) ? warmup.hotScopes : [];
    const rows = hotScopes
      .map(
        (item) =>
          `<tr><td>${shellLink(`scope:${item.scope}`, item.scope || "-", null, "", "build-toolbar-btn")}</td><td>${escapeHtml(
            String(item.slots || 0),
          )}</td></tr>`,
      )
      .join("");
    return detailSection(
      "Warmup / Frontier",
      kvTable([
        ["planSource", escapeHtml(warmup.planSource || "-")],
        ["dirtySlotCount", escapeHtml(String(warmup.dirtySlotCount || 0))],
        ["dirtyScopes", escapeHtml((warmup.dirtyScopes || []).join(", ") || "-")],
        ["bootstrapManifests", escapeHtml(String(warmup.bootstrapManifestCount || 0))],
        ["mrgEvalSkips", escapeHtml(String(warmup.mrgEvalSkips || 0))],
      ]) +
        `<div class="host-runtime-table-wrap">
          <table class="host-runtime-table">
            <thead><tr><th>Hot scope</th><th>Slots</th></tr></thead>
            <tbody>${rows || `<tr><td colspan="2">暂无 hot scopes</td></tr>`}</tbody>
          </table>
        </div>` +
        hintBlock([
          "warmup 关心哪些 scope/workset/slot 需要推进，不等同于 compile/import 是否完成。",
          "dirty slot = 仍需推进或已 stale/failed 的物化单元，是 prebuild 与运行排障的重要交集。",
        ]),
      "预热计划、dirty frontier 与 bootstrap 资格在这里汇合。",
    );
  }

  function renderWarmupScopeDetail(snapshot, scopeKey) {
    const scope = findScope(snapshot, scopeKey);
    if (!scope) return renderWarmupSummary(snapshot);
    return detailSection(
      `Warmup · ${scopeKey}`,
      kvTable([
        ["dirtySlots", escapeHtml(String(scope.dirtySlots || 0))],
        ["readySlots", escapeHtml(String(scope.readySlots || 0))],
        ["failedSlots", escapeHtml(String(scope.failedSlots || 0))],
        ["worksetIds", escapeHtml((scope.worksetIds || []).join(", ") || "-")],
      ]) +
        renderSlotsTable(slotsOfScope(snapshot, scopeKey), { title: `Warmup 关注的 slots · ${scopeKey}` }) +
        hintBlock([
          "若 dirty slot 长时间不下降，优先核对该 scope 的 route / blockers / artifact 输入是否匹配。",
        ]),
      "按 scope 看 warmup frontier，而不是把 dirty slot 散落在全局列表里。",
    );
  }

  function renderMrgSummary(snapshot) {
    const mrg = snapshot?.mrg || {};
    const tiers = mrg.slotsByTier || {};
    return detailSection(
      "MRG 总览",
      kvTable([
        ["schemaVersion", escapeHtml(mrg.schemaVersion || "-")],
        ["registryRevision", escapeHtml(mrg.registryRevision || "-")],
        ["updatedAtMs", escapeHtml(String(mrg.updatedAtMs || 0))],
        ["slotCount", escapeHtml(String(mrg.slotCount || 0))],
        ["failedSlots", escapeHtml(String((mrg.failedSlots || []).length))],
        ["edgeCount", escapeHtml(String(mrg.edgeCount || 0))],
        ["diskReady", escapeHtml(String(tiers.diskReady || 0))],
        ["memoryResident", escapeHtml(String(tiers.memoryResident || 0))],
        ["clientEligible", escapeHtml(String(tiers.clientEligible || 0))],
      ]) +
        hintBlock([
          "MRG 是当前 materialization 真源；scope 详情会把同一 scope 下的 slot 汇总回来。",
          "“全部 slots”是排障索引，不是 scene 树的一一镜像。",
        ]),
      "用来回答：当前 materialization 到了哪一步、tier 状态如何。",
    );
  }

  function renderSlotsTable(slots, options) {
    const rows = (slots || [])
      .map(
        (slot) =>
          `<tr>
            <td>${options?.scopeFirst ? escapeHtml(slot.scopeKey || "-") : shellLink(slot.nodeId, slot.nodeKey || "-", null, "", "build-toolbar-btn")}</td>
            <td>${options?.scopeFirst ? shellLink(slot.nodeId, slot.nodeKey || "-", null, "", "build-toolbar-btn") : escapeHtml(slot.state || "-")}</td>
            <td>${options?.scopeFirst ? escapeHtml(slot.state || "-") : escapeHtml(slot.residentTier || "-")}</td>
            <td>${options?.scopeFirst ? escapeHtml(slot.residentTier || "-") : escapeHtml(slot.ownerResourceId || "-")}</td>
            ${
              options?.scopeFirst
                ? `<td>${escapeHtml(slot.ownerResourceId || "-")}</td>`
                : ""
            }
          </tr>`,
      )
      .join("");
    const headers = options?.scopeFirst
      ? "<th>Scope</th><th>Slot</th><th>状态</th><th>Tier</th><th>Owner</th>"
      : "<th>Slot</th><th>状态</th><th>Tier</th><th>Owner</th>";
    const span = options?.scopeFirst ? 5 : 4;
    return `
<section class="rounded-lg border border-white/10 bg-black/10 p-3">
  <h3 class="mb-2 mei-font-2 mei-text-primary">${escapeHtml(options?.title || "Slots")}</h3>
  <div class="host-runtime-table-wrap">
    <table class="host-runtime-table">
      <thead><tr>${headers}</tr></thead>
      <tbody>${rows || `<tr><td colspan="${span}">暂无 slot</td></tr>`}</tbody>
    </table>
  </div>
</section>`;
  }

  function renderAllSlots(snapshot) {
    return detailSection(
      "全部 slots",
      renderSlotsTable(allSlots(snapshot), { title: "MRG 全量 slot 索引", scopeFirst: true }) +
        hintBlock([
          "这是排障总表，便于按 scope / state / tier 观察；不再假装与左侧入口一一对应。",
        ]),
      `共 ${allSlots(snapshot).length} 个 slot`,
    );
  }

  function renderFailedSlots(snapshot) {
    const failed = Array.isArray(snapshot?.mrg?.failedSlots) ? snapshot.mrg.failedSlots : [];
    return detailSection(
      "失败 slots",
      renderSlotsTable(failed, { title: "当前 failed slots", scopeFirst: true }) +
        hintBlock([
          "failed slot 说明当前 materialization 已进入错误态，通常需要结合日志、layer/block CLI 或输入产物继续确认根因。",
        ]),
      `当前 ${failed.length} 个 failed slot`,
    );
  }

  function renderSlotDetail(snapshot, nodeId) {
    const slot = findSlot(snapshot, nodeId);
    if (!slot) return renderAllSlots(snapshot);
    const scope = findScope(snapshot, slot.scopeKey);
    return detailSection(
      `Slot · ${slot.nodeKey || "-"}`,
      kvTable([
        ["scope", shellLink(`scope:${slot.scopeKey}`, slot.scopeKey || "-", null, "", "build-toolbar-btn")],
        ["state", escapeHtml(slot.state || "-")],
        ["slotRevision", escapeHtml(slot.slotRevision || "-")],
        ["ownerResourceId", escapeHtml(slot.ownerResourceId || "-")],
        ["metricDefBundleRevision", escapeHtml(slot.metricDefBundleRevision || "-")],
        ["dataSourceRevision", escapeHtml(slot.dataSourceRevision || "-")],
        ["cachePolicy", escapeHtml(slot.cachePolicy || "-")],
        ["evalEngine", escapeHtml(slot.evalEngine || "-")],
        ["residentTier", escapeHtml(slot.residentTier || "-")],
        ["clientEligible", escapeHtml(boolText(!!slot.clientEligible))],
        ["clientRevision", escapeHtml(slot.clientRevision || "-")],
        ["payloadBytes", escapeHtml(formatBytes(slot.payloadBytes))],
        ["accessCount", escapeHtml(String(slot.accessCount || 0))],
        ["lastAccessMs", escapeHtml(formatMaybe(slot.lastAccessMs))],
        ["worksetId", escapeHtml(slot.worksetId || "-")],
      ]) +
        `<section class="rounded-lg border border-white/10 bg-black/10 p-3">
          <h3 class="mb-2 mei-font-2 mei-text-primary">最近一次求值</h3>
          ${kvTable([
            ["atMs", escapeHtml(formatMaybe(slot.lastEval?.atMs))],
            ["wallMs", escapeHtml(formatMs(slot.lastEval?.wallMs))],
            ["artifactHit", escapeHtml(boolText(!!slot.lastEval?.artifactHit))],
            ["cacheLayer", escapeHtml(slot.lastEval?.cacheLayer || "-")],
          ])}
        </section>
        <section class="rounded-lg border border-white/10 bg-black/10 p-3">
          <h3 class="mb-2 mei-font-2 mei-text-primary">Payload / Tier 备注</h3>
          <pre class="runtime-detail-json overflow-auto rounded bg-black/20 p-3 font-mono mei-font-1 leading-5 mei-text-body">${escapeHtml(
            prettyJson({
              payloadRef: slot.payloadRef || null,
              tiersReady: slot.tiersReady || null,
              scopeSummary: scope || null,
            }),
          )}</pre>
        </section>
        ${hintBlock([
          "artifactHit/cacheLayer 描述最近一次已记录求值如何命中，并非浏览器当前 tab 的实时命中轨迹。",
          "clientRevision 是 client tier 的失效键；是否被浏览器实际消费仍需结合 access 页 perf / 日志确认。",
        ])}`,
      "slot 是 (owner, scopeKey) 级别的求值单元，这里展示最接近原始 registry 的字段。",
    );
  }

  function renderCacheSummary(snapshot) {
    const cache = snapshot?.cache || {};
    const flags = cache.flags || {};
    const content = cache.contentStore || {};
    const evalInfo = cache.eval || {};
    const disk = cache.disk || {};
    const build = cache.build || {};
    return detailSection(
      "Cache / Artifact / Store",
      kvTable([
        ["dataGeneration", escapeHtml(cache.dataGeneration || "-")],
        ["accessSlimArtifacts", escapeHtml(boolText(!!flags.accessSlimArtifacts))],
        ["canonicalArtifactPersist", escapeHtml(boolText(!!flags.canonicalArtifactPersist))],
        ["graphRegistryDedup", escapeHtml(boolText(!!flags.graphRegistryDedup))],
        ["envOverrides", escapeHtml((flags.envOverrides || []).join(", ") || "-")],
        ["CAS store", escapeHtml(`${formatBytes(content.bytes)} / ${Object.keys(content.filesByKind || {}).length} kinds`)],
        ["eval response", escapeHtml(`${evalInfo.metricResponseFiles || 0} / ${formatBytes(evalInfo.metricResponseBytes)}`)],
        ["eval dataframe", escapeHtml(`${evalInfo.metricDataframeFiles || 0} / ${formatBytes(evalInfo.metricDataframeBytes)}`)],
        ["disk artifacts", escapeHtml(`${disk.evalArtifactFileCount || 0} / ${formatBytes(disk.evalArtifactBytes)}`)],
        ["compile index", escapeHtml(`${build.compileIndexEntries || 0} entries / ${build.compileIndexHits || 0} hit`)],
      ]) +
        hintBlock([
          "这里区分 sealed artifact / content store / client tier 资格，避免把资格误读成 live cache hit。",
          "浏览器当前 tab 的 runtime-query Map / sessionStorage 命中率不在 host-shell 直接真源内。",
        ]),
      "缓存面板回答：哪些东西已存在、哪些层只是资格或提示。",
    );
  }

  function renderDiagnosticsSummary(snapshot) {
    const diagnostics = snapshot?.diagnostics || {};
    const alerts = Array.isArray(diagnostics.alerts) ? diagnostics.alerts : [];
    const alertHtml = alerts.length
      ? `<section class="rounded-lg border border-amber-500/30 bg-amber-500/10 p-3">
          <h3 class="mb-2 mei-font-2 mei-text-primary">告警</h3>
          <ul class="grid gap-1 mei-font-1">${alerts
            .map((alert) => `<li>${escapeHtml(alert)}</li>`)
            .join("")}</ul>
        </section>`
      : "";
    return detailSection(
      "Diagnostics",
      kvTable([
        ["compile source", escapeHtml(diagnostics.build?.source || "-")],
        ["compile index stale", escapeHtml(String(diagnostics.build?.compileIndexStaleEntries || 0))],
        ["mrg stale ratio", escapeHtml(String(Math.round((diagnostics.mrg?.staleRatio || 0) * 100)) + "%")],
        ["L2/L3/L4 sweep", escapeHtml(prettyJson(diagnostics.scopeGateSweep || {}))],
      ]) +
        alertHtml +
        hintBlock([
          "诊断面板是对 disk / eval / build / gate 的聚合摘要，不等同于单个 scope/slot 的原始真源。",
          "当这里的摘要不足以解释根因时，请优先切回当前节点 JSON，再决定是否回到 CLI。",
        ]),
      "聚合视角，帮助决定从哪条证据链继续下钻。",
    );
  }

  function renderDetail(activeNode, appId, ops, snapshot) {
    if (activeNode === "ops:overview") return renderOpsDetail(ops, snapshot);
    if (activeNode === "ops:versions") return renderVersionDetail(ops, snapshot);
    if (activeNode === "nav:summary") return renderNavigationSummary(snapshot);
    if (activeNode === "gate:summary") return renderGateSummary(snapshot);
    if (activeNode === "warmup:summary") return renderWarmupSummary(snapshot);
    if (activeNode === "mrg:summary") return renderMrgSummary(snapshot);
    if (activeNode === "mrg:failed") return renderFailedSlots(snapshot);
    if (activeNode === "mrg:slots") return renderAllSlots(snapshot);
    if (activeNode === "cache:summary") return renderCacheSummary(snapshot);
    if (activeNode === "diag:summary") return renderDiagnosticsSummary(snapshot);
    if (activeNode.startsWith("scope:")) {
      return renderScopeDetail(snapshot, activeNode.slice("scope:".length));
    }
    if (activeNode.startsWith("nav:route:")) {
      return renderRouteDetail(snapshot, findRoute(snapshot, activeNode));
    }
    if (activeNode.startsWith("warmup:scope:")) {
      return renderWarmupScopeDetail(snapshot, activeNode.slice("warmup:scope:".length));
    }
    if (activeNode.startsWith("mrg:slot:")) {
      return renderSlotDetail(snapshot, activeNode);
    }
    return renderOpsDetail(ops, snapshot);
  }

  function selectNodeJson(activeNode, snapshot, ops) {
    if (activeNode === "ops:overview") {
      return {
        nodeId: activeNode,
        ops: ops || snapshot?.ops || {},
        host: snapshot?.host || {},
        scopeGate: snapshot?.scopeGate || {},
      };
    }
    if (activeNode === "ops:versions") {
      return {
        nodeId: activeNode,
        ops: ops || snapshot?.ops || {},
        build: snapshot?.diagnostics?.build || {},
      };
    }
    if (activeNode === "nav:summary") return snapshot?.navigation || {};
    if (activeNode === "gate:summary") return snapshot?.scopeGate || {};
    if (activeNode === "warmup:summary") return snapshot?.warmup || {};
    if (activeNode === "mrg:summary") return snapshot?.mrg || {};
    if (activeNode === "mrg:failed") return { failedSlots: snapshot?.mrg?.failedSlots || [] };
    if (activeNode === "mrg:slots") return { slots: allSlots(snapshot) };
    if (activeNode === "cache:summary") return snapshot?.cache || {};
    if (activeNode === "diag:summary") return snapshot?.diagnostics || {};
    if (activeNode.startsWith("scope:")) {
      const scopeKey = activeNode.slice("scope:".length);
      return {
        scope: findScope(snapshot, scopeKey),
        routes: routesOfScope(snapshot, scopeKey),
        slots: slotsOfScope(snapshot, scopeKey),
        gate: snapshot?.scopeGate || {},
        warmup: snapshot?.warmup || {},
      };
    }
    if (activeNode.startsWith("nav:route:")) return findRoute(snapshot, activeNode) || {};
    if (activeNode.startsWith("warmup:scope:")) {
      const scopeKey = activeNode.slice("warmup:scope:".length);
      return {
        scope: findScope(snapshot, scopeKey),
        warmup: snapshot?.warmup || {},
        slots: slotsOfScope(snapshot, scopeKey),
      };
    }
    if (activeNode.startsWith("mrg:slot:")) return findSlot(snapshot, activeNode) || {};
    return snapshot || {};
  }

  function setJsonPanels(activeNode, snapshot, ops) {
    const nodePanel = document.getElementById("host-runtime-node-json");
    if (nodePanel) {
      nodePanel.textContent = prettyJson(selectNodeJson(activeNode, snapshot, ops));
    }
    const snapshotPanel = document.getElementById("host-runtime-snapshot-json");
    if (snapshotPanel) {
      snapshotPanel.textContent = prettyJson(snapshot || {});
    }
  }

  function setBusy(root, busy) {
    if (!root) return;
    root.querySelectorAll("[data-host-ops]").forEach((btn) => {
      if (btn.getAttribute("data-host-ops") === "refresh") return;
      btn.disabled = busy;
    });
  }

  async function fetchOps() {
    const res = await fetch(STATUS_URL, { headers: { Accept: "application/json" } });
    if (!res.ok) return null;
    const data = await res.json();
    return data && data.hostShellOps ? data : null;
  }

  async function fetchSnapshot(appId) {
    const res = await fetch(`${SNAPSHOT_URL}?appId=${encodeURIComponent(appId)}`, {
      headers: { Accept: "application/json" },
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data && data.hostShellMgmt ? data : null;
  }

  async function postReload(root) {
    setBusy(root, true);
    try {
      const res = await fetch(RELOAD_URL, { method: "POST" });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body.error || res.statusText || "reload failed");
      global.location.reload();
    } catch (err) {
      global.alert(String(err && err.message ? err.message : err));
    } finally {
      setBusy(root, false);
    }
  }

  async function postPrebuild(root) {
    if (
      !global.confirm(
        "将执行完整 prebuild（compile + import + data + warmup + finalize），可能需要较长时间。继续？",
      )
    ) {
      return;
    }
    setBusy(root, true);
    try {
      const res = await fetch(PREBUILD_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ policy: "standard" }),
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok && res.status !== 202) {
        throw new Error(body.error || res.statusText || "prebuild failed");
      }
      schedulePoll(root);
      await refreshConsole();
    } catch (err) {
      global.alert(String(err && err.message ? err.message : err));
    } finally {
      setBusy(root, false);
    }
  }

  async function postActivateScope(root, scopeKey) {
    setBusy(root, true);
    try {
      const appId = appIdFromShell();
      const appQuery = appId ? `&appId=${encodeURIComponent(appId)}` : "";
      const url = `${ACTIVATE_SCOPE_URL}?scope=${encodeURIComponent(scopeKey)}&hops=1${appQuery}`;
      const res = await fetch(url, { method: "POST" });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body.error || res.statusText || "scope activation failed");
      await refreshConsole();
    } catch (err) {
      global.alert(String(err && err.message ? err.message : err));
    } finally {
      setBusy(root, false);
    }
  }

  function bindDetailActions(detailRoot, ops) {
    if (!detailRoot) return;
    detailRoot.querySelectorAll("[data-host-ops]").forEach((btn) => {
      if (btn.__hostRuntimeOpsBound) return;
      btn.__hostRuntimeOpsBound = true;
      btn.addEventListener("click", () => {
        const action = btn.getAttribute("data-host-ops");
        if (action === "reload") postReload(detailRoot);
        else if (action === "prebuild") postPrebuild(detailRoot);
        else if (action === "activate-scope") {
          const scopeKey = btn.getAttribute("data-host-scope");
          if (scopeKey) postActivateScope(detailRoot, scopeKey);
        } else if (action === "refresh") {
          void refreshConsole();
        }
      });
    });
    if (ops?.job && ops.job.status === "running") {
      setBusy(detailRoot, true);
    }
  }

  function bindToolbarActions() {
    const refreshBtn = document.getElementById("runtime-refresh-btn");
    if (!refreshBtn || refreshBtn.__hostRuntimeBound) return;
    refreshBtn.__hostRuntimeBound = true;
    refreshBtn.addEventListener("click", () => {
      void refreshConsole();
    });
  }

  function hideLegacyPanels() {
    document.querySelectorAll("[data-host-runtime-legacy-tree]").forEach((el) => {
      el.hidden = true;
    });
    document.querySelectorAll("[data-host-runtime-legacy-overview]").forEach((el) => {
      el.hidden = true;
    });
    const workspace = document.querySelector(".runtime-workspace");
    if (workspace) workspace.classList.add("host-runtime-console-active");
  }

  function paintConsole(appId, ops, snapshot) {
    const activeNode = resolveActiveNode(snapshot);
    const navMount = document.getElementById("host-runtime-nav-mount");
    const detailMount = document.getElementById("host-runtime-detail-mount");
    if (!navMount || !detailMount) return;
    hideLegacyPanels();
    bindToolbarActions();
    navMount.innerHTML = renderNav(appId, snapshot, activeNode);
    detailMount.innerHTML = renderDetail(activeNode, appId, ops, snapshot);
    setJsonPanels(activeNode, snapshot, ops);
    bindDetailActions(detailMount, ops);
  }

  async function refreshConsole() {
    const appId = appIdFromShell();
    if (!appId) return false;
    const ops = await fetchOps();
    if (!ops) return false;
    opsCache = ops;
    const snapshot = await fetchSnapshot(appId);
    if (!snapshot) return false;
    snapshotCache = snapshot;
    paintConsole(appId, ops, snapshot);
    if (ops.job && ops.job.status === "running") {
      schedulePoll(document.getElementById("host-runtime-detail-mount"));
    } else if (pollTimer) {
      clearTimeout(pollTimer);
      pollTimer = null;
    }
    return true;
  }

  function schedulePoll(detailRoot) {
    if (pollTimer) return;
    pollTimer = global.setTimeout(async () => {
      pollTimer = null;
      const hadJob = opsCache?.job?.status === "running";
      await refreshConsole();
      if (hadJob && opsCache && !opsCache.job && opsCache.lastJob?.status === "success") {
        global.setTimeout(() => global.location.reload(), 800);
      }
      if (opsCache?.job?.status === "running") {
        schedulePoll(detailRoot);
      }
    }, 1500);
  }

  async function initHostRuntimeConsole() {
    if (!document.querySelector(".runtime-workspace")) return;
    syncShellNodeFromUrl();
    const ok = await refreshConsole();
    if (!ok) return;
    if (!activeNodeFromUrl()) {
      navigateToNode(defaultNodeId(snapshotCache), { replace: true });
    }
  }

  function bindHostRuntimeNavCapture() {
    if (document.__hostRuntimeNavCaptureBound) return;
    document.__hostRuntimeNavCaptureBound = true;
    document.addEventListener(
      "click",
      (event) => {
        const link = event.target.closest("[data-runtime-node-link='1']");
        if (!link) return;
        if (!document.querySelector(".runtime-workspace")?.contains(link)) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        const nodeId = link.getAttribute("data-runtime-node");
        if (nodeId) navigateToNode(nodeId);
      },
      true,
    );
  }

  bindHostRuntimeNavCapture();

  global.addEventListener("popstate", () => {
    if (!document.querySelector(".runtime-workspace")) return;
    syncShellNodeFromUrl();
    if (opsCache && snapshotCache) {
      paintConsole(appIdFromShell(), opsCache, snapshotCache);
    } else {
      void initHostRuntimeConsole();
    }
  });

  global.addEventListener("meilang:preview-updated", () => {
    if (document.getElementById("host-runtime-nav-mount")) {
      void initHostRuntimeConsole();
    }
  });

  global.MeiHostRuntimeConsole = { refreshConsole, initHostRuntimeConsole, navigateToNode };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initHostRuntimeConsole);
  } else {
    initHostRuntimeConsole();
  }
})(typeof window !== "undefined" ? window : globalThis);


/* ===== frame-stage/preamble.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (typeof boot.disposeFrameStage === "function") {
    try {
      boot.disposeFrameStage();
    } catch (_) {}
    boot.disposeFrameStage = null;
  }
  const tracked = new WeakMap();
  const observers = new Set();



/* ===== frame-stage/util.js ===== */
  function round(value) {
    return Math.round(value * 1000) / 1000;
  }

  function computeScale(mode, hostWidth, hostHeight, designWidth, designHeight, root) {
    if (hostWidth <= 0 || hostHeight <= 0 || designWidth <= 0 || designHeight <= 0) {
      return 1;
    }
    const sx = hostWidth / designWidth;
    const sy = hostHeight / designHeight;
    const normalized = String(mode || "contain").trim().toLowerCase();
    if (normalized === "cover") {
      return Math.max(sx, sy);
    }
    if (
      normalized === "fit-width" ||
      normalized === "fit_width" ||
      normalized === "width"
    ) {
      return sx;
    }
    // 访问态 contain：优先按宽度适配，高度不足时再缩小（纵向 letterbox）
    if (normalized === "contain" && root && !isManagePreviewRoute(root)) {
      const heightAtWidth = designHeight * sx;
      if (heightAtWidth <= hostHeight + 0.5) {
        return sx;
      }
      return Math.min(sx, sy);
    }
    return Math.min(sx, sy);
  }

  function overflowModeIsDebug(mode) {
    const value = String(mode || "").trim().toLowerCase();
    return value === "debug" || value === "scroll" || value === "visible";
  }

  /** 构建/管理端预览始终允许缩放；访问态仍依赖显式 viewport 配置。 */
  function viewportToolbarEnabled(root) {
    if (isManagePreviewRoute(root)) return true;
    return String(root?.dataset?.viewportExplicit || "").toLowerCase() === "true";
  }

  /** 管理端固定调试视口；访问/演示端固定裁切。以 data-route-mode 为准。 */
  function isManagePreviewRoute(root) {
    const route = String(root?.dataset?.routeMode || "").trim().toLowerCase();
    if (route === "manage" || route === "build") return true;
    if (
      route === "access" ||
      route === "app" ||
      route === "presentation" ||
      route === "run"
    ) {
      return false;
    }
    return overflowModeIsDebug(String(root?.dataset?.overflowMode || "clip"));
  }

  function showDesignBoundsEnabled(root) {
    const raw = String(root.dataset.showDesignBounds || "").trim().toLowerCase();
    return raw !== "false" && raw !== "0";
  }

  /** 仅访问态隐藏 chrome（app-view + chrome-none）；演示态虽无 chrome 但 preview 宿主仍走 shell 链。 */
  function isChromeNoneAccess() {
    return (
      document.body.classList.contains("app-view") &&
      document.body.classList.contains("chrome-none")
    );
  }

  function readSafeInsets(root, overflowMode) {
    const inDebug = overflowModeIsDebug(overflowMode);
    return {
      top: Number((inDebug ? root.dataset.editSafeTop : root.dataset.safeTop) || 0),
      right: Number((inDebug ? root.dataset.editSafeRight : root.dataset.safeRight) || 0),
      bottom: Number((inDebug ? root.dataset.editSafeBottom : root.dataset.safeBottom) || 0),
      left: Number((inDebug ? root.dataset.editSafeLeft : root.dataset.safeLeft) || 0),
    };
  }

  /** 宿主 = 包裹 viewport 的可用区域；chrome=none 时退化为浏览器窗口。 */
  function resolveHostSize(root, safe) {
    if (isChromeNoneAccess()) {
      const vv = window.visualViewport;
      const width = vv?.width ?? window.innerWidth;
      const height = vv?.height ?? window.innerHeight;
      return {
        hostWidth: Math.max(1, width - safe.left - safe.right),
        hostHeight: Math.max(1, height - safe.top - safe.bottom),
      };
    }
    if (root && !isManagePreviewRoute(root)) {
      const accessHost = resolveAccessPreviewHost(root);
      if (accessHost) {
        return {
          hostWidth: Math.max(1, accessHost.width - safe.left - safe.right),
          hostHeight: Math.max(1, accessHost.height - safe.top - safe.bottom),
        };
      }
    }
    const rect = root.getBoundingClientRect();
    if (rect.width >= 1 && rect.height >= 1) {
      return {
        hostWidth: Math.max(1, rect.width - safe.left - safe.right),
        hostHeight: Math.max(1, rect.height - safe.top - safe.bottom),
      };
    }
    return {
      hostWidth: Math.max(1, window.innerWidth - safe.left - safe.right),
      hostHeight: Math.max(1, window.innerHeight - safe.top - safe.bottom),
    };
  }

  /** 访问态：用 main / 滚动宿主可见区，避免窄屏断点下 viewport rect 高度塌缩。 */
  function resolveAccessPreviewHost(root) {
    const candidates = [
      root.closest(".main"),
      root.closest(".preview-pane-scroll"),
      root.parentElement,
      root,
    ];
    for (const node of candidates) {
      if (!(node instanceof HTMLElement)) continue;
      const rect = node.getBoundingClientRect();
      if (rect.width >= 1 && rect.height >= 1) {
        return { width: rect.width, height: rect.height };
      }
      if (node.clientWidth >= 1 && node.clientHeight >= 1) {
        return { width: node.clientWidth, height: node.clientHeight };
      }
    }
    const topbar = document.querySelector(".topbar");
    const statusbar = document.querySelector(".statusbar");
    const topH = topbar?.getBoundingClientRect().height || 0;
    const bottomH = statusbar?.getBoundingClientRect().height || 0;
    const vv = window.visualViewport;
    const width = vv?.width ?? window.innerWidth;
    const height = (vv?.height ?? window.innerHeight) - topH - bottomH;
    if (width >= 1 && height >= 1) {
      return { width, height };
    }
    return null;
  }

  /**
   * 管理端：用 preview-pane-scroll 的可见区域作宿主，避免 viewport 随画布撑高导致 fit 缩放反馈振荡。
   */
  function resolveManageHostSize(root, safe) {
    const scrollPane = root.closest(".preview-pane-scroll");
    if (scrollPane && scrollPane.clientWidth >= 1 && scrollPane.clientHeight >= 1) {
      const toolbar = root.querySelector(":scope > .preview-viewport-toolbar");
      const toolbarHeight = toolbar?.offsetHeight || 0;
      return {
        hostWidth: Math.max(1, scrollPane.clientWidth - safe.left - safe.right),
        hostHeight: Math.max(
          1,
          scrollPane.clientHeight - safe.top - safe.bottom - toolbarHeight,
        ),
      };
    }
    const host = root.parentElement;
    if (host && host.clientWidth >= 1 && host.clientHeight >= 1) {
      return {
        hostWidth: Math.max(1, host.clientWidth - safe.left - safe.right),
        hostHeight: Math.max(1, host.clientHeight - safe.top - safe.bottom),
      };
    }
    return resolveHostSize(root, safe);
  }

  const viewportUpdateQueued = new WeakMap();
  const viewportLayoutApplying = new WeakMap();

  function manageLayoutKey(
    contentWidth,
    contentHeight,
    appliedZoom,
    hostWidth,
    hostHeight,
    canvasWidth,
  ) {
    return [
      Math.round(contentWidth),
      Math.round(contentHeight),
      round(appliedZoom),
      Math.round(hostWidth),
      Math.round(hostHeight),
      Math.round(canvasWidth),
    ].join(":");
  }

  function buildRouteSlugFromPathname(pathname = window.location.pathname) {
    const match = String(pathname || "").match(/^\/apps\/([^/]+)\//);
    return match ? String(match[1] || "").trim().toLowerCase() : "";
  }

  function isBuildShellRoute(pathname = window.location.pathname) {
    const slug = buildRouteSlugFromPathname(pathname);
    return slug === "build" || slug === "manage";
  }

  function activeBuildTabSlug() {
    const shell = document.querySelector("[data-build-tab]");
    const fromShell =
      shell && String(shell.getAttribute("data-build-tab") || "").trim().toLowerCase();
    if (fromShell) return fromShell;
    try {
      return String(new URL(window.location.href).searchParams.get("tab") || "overview")
        .trim()
        .toLowerCase();
    } catch (_) {
      return "overview";
    }
  }

  /** 构建视图非 preview 标签时不应触发 dataset/metric 预取与 viewport 扫描。 */
  function shouldMountBuildPreviewRuntime() {
    if (!isBuildShellRoute()) return true;
    return activeBuildTabSlug() === "preview";
  }

  boot.shouldMountBuildPreviewRuntime = shouldMountBuildPreviewRuntime;
  boot.activeBuildTabSlug = activeBuildTabSlug;



/* ===== frame-stage/viewport/p1.js ===== */
  function queueUpdateViewport(root) {
    if (viewportUpdateQueued.get(root)) return;
    viewportUpdateQueued.set(root, true);
    requestAnimationFrame(() => {
      viewportUpdateQueued.delete(root);
      updateViewport(root);
      try {
        const scale = Number(root?.dataset?.meiFrameScale || 1);
        window.dispatchEvent(
          new CustomEvent("meilang:viewport-stage-layout", {
            detail: { root, scale },
          }),
        );
        if (scale > 0 && root?.dataset?.meiFrameScale) {
          window.dispatchEvent(
            new CustomEvent("meilang:viewport-stage-ready", {
              detail: { root, scale },
            }),
          );
        }
        window.__meiLangBoot?.relocateStageOverlaysInViewport?.() ||
          window.__meiLangBoot?.relocateCopilotInViewport?.();
        window.__meiLangBoot?.syncCockpitMapToolsOverlays?.();
      } catch (_) {}
    });
  }

  function invalidateManageLayout(root) {
    delete root.dataset.meiLayoutKey;
    root.dataset.meiRelayoutPass = "0";
    const timers = manageRelayoutTimers.get(root);
    if (timers?.t500) clearTimeout(timers.t500);
    manageRelayoutTimers.delete(root);
  }

  function applyFluidWidthLayout(shell, stage, contentMaxWidth, hostWidth) {
    const stageWidth = Math.min(contentMaxWidth, hostWidth);
    shell.style.width = `${round(stageWidth)}px`;
    shell.style.height = "auto";
    shell.style.maxHeight = "none";
    shell.style.overflow = "visible";
    stage.style.width = `${round(stageWidth)}px`;
    stage.style.height = "auto";
    stage.style.maxHeight = "none";
    stage.style.transform = "none";
    removeDesignBounds(shell);
  }

  function removeViewportChrome(root, shell) {
    root?.querySelector(".preview-viewport-chrome")?.remove();
    shell?.querySelector(".preview-viewport-chrome")?.remove();
  }

  function debugLayoutContainer(shell) {
    return shell?.querySelector(".preview-stage-scale-wrap") || shell;
  }

  function ensureStageScaleWrap(shell, stage) {
    let wrap = shell.querySelector(".preview-stage-scale-wrap");
    if (!wrap) {
      wrap = document.createElement("div");
      wrap.className = "preview-stage-scale-wrap";
      if (stage.parentElement === shell) {
        shell.insertBefore(wrap, stage);
        wrap.appendChild(stage);
      } else {
        shell.appendChild(wrap);
        if (stage.parentElement !== wrap) {
          wrap.appendChild(stage);
        }
      }
    }
    return wrap;
  }

  function ensureStageScaleInner(wrap) {
    let inner = wrap.querySelector(":scope > .preview-stage-scale-inner");
    if (!inner) {
      inner = document.createElement("div");
      inner.className = "preview-stage-scale-inner";
      [...wrap.childNodes].forEach((node) => inner.appendChild(node));
      wrap.appendChild(inner);
    }
    return inner;
  }

  const MANAGE_ZOOM_STORAGE_KEY = "mei-manage-preview-zoom";
  const MANAGE_ZOOM_MIN = 0.1;
  const MANAGE_ZOOM_MAX = 2;

  function initManagePreviewZoom(root) {
    if (!root.dataset.previewZoom) {
      root.dataset.previewZoom =
        localStorage.getItem(MANAGE_ZOOM_STORAGE_KEY) || "fit";
    }
  }

  function computeManageFitScale(
    hostWidth,
    hostHeight,
    contentWidth,
    contentHeight,
  ) {
    if (hostWidth <= 0 || hostHeight <= 0 || contentWidth <= 0 || contentHeight <= 0) {
      return 1;
    }
    const sx = hostWidth / contentWidth;
    const sy = hostHeight / contentHeight;
    const fit = Math.min(sx, sy);
    return fit > 0 ? fit : 1;
  }

  /** page-flow / fit-width：仅按宽度适配宿主，纵向可滚动，避免「贴右长条」。 */
  function computeManageWidthFitScale(root, hostWidth, contentWidth, fluidHeight) {
    if (hostWidth <= 0 || contentWidth <= 0) return 1;
    const editMode = String(root.dataset.editScaleMode || "")
      .trim()
      .toLowerCase();
    const widthOnly =
      fluidHeight ||
      editMode === "fit-width" ||
      editMode === "fit_width" ||
      editMode === "width";
    if (!widthOnly) {
      return null;
    }
    const fit = hostWidth / contentWidth;
    return fit > 0 ? fit : 1;
  }

  function resolveManagePreviewZoom(root, fitScale) {
    initManagePreviewZoom(root);
    const raw = String(root.dataset.previewZoom || "fit").trim().toLowerCase();
    if (raw === "fit" || raw === "auto") return fitScale;
    const value = Number(raw);
    if (Number.isFinite(value) && value > 0) {
      return Math.min(MANAGE_ZOOM_MAX, Math.max(MANAGE_ZOOM_MIN, value));
    }
    return fitScale;
  }

  function setManagePreviewZoom(root, value) {
    if (!viewportToolbarEnabled(root)) return;
    root.dataset.previewZoom = value;
    try {
      localStorage.setItem(MANAGE_ZOOM_STORAGE_KEY, value);
    } catch (_) {}
    invalidateManageLayout(root);
    updateManageZoomToolbar(root);
    updateViewport(root);
  }

  function stepManagePreviewZoom(root, delta) {
    initManagePreviewZoom(root);
    const fitScale = Number(root.dataset.meiFitScale || 1);
    const current =
      root.dataset.previewZoom === "fit"
        ? fitScale
        : resolveManagePreviewZoom(root, fitScale);
    const next = Math.min(
      MANAGE_ZOOM_MAX,
      Math.max(MANAGE_ZOOM_MIN, round(current + delta)),
    );
    setManagePreviewZoom(root, String(next));
  }

  function ensureManageZoomToolbar(root) {
    if (!viewportToolbarEnabled(root)) {
      root?.querySelector(":scope > .preview-viewport-toolbar")?.remove();
      return null;
    }
    let toolbar = root.querySelector(":scope > .preview-viewport-toolbar");
    const shell = root.querySelector(".preview-stage-shell");
    if (!toolbar) {
      toolbar = document.createElement("div");
      toolbar.className = "preview-viewport-toolbar";
      const bar = document.createElement("div");
      bar.className = "preview-viewport-zoom-bar";
      bar.dataset.previewZoomBar = "true";
      const title = document.createElement("span");
      title.className = "preview-viewport-zoom-title";
      title.textContent = "视窗";
      bar.appendChild(title);
      const presets = [
        ["fit", "自适应"],
        ["1", "100%"],
        ["0.75", "75%"],
        ["0.5", "50%"],
        ["minus", "−"],
        ["plus", "+"],
      ];
      presets.forEach(([value, label]) => {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "preview-viewport-zoom-btn";
        btn.dataset.previewZoom = value;
        btn.textContent = label;
        if (value === "minus") btn.title = "缩小";
        if (value === "plus") btn.title = "放大";
        bar.appendChild(btn);
      });
      const readout = document.createElement("span");
      readout.className = "preview-viewport-zoom-readout";
      readout.dataset.previewZoomReadout = "true";
      readout.textContent = "—";
      bar.appendChild(readout);
      toolbar.appendChild(bar);
      const chrome = document.createElement("div");
      chrome.className = "preview-viewport-chrome";
      chrome.setAttribute("aria-hidden", "true");
      toolbar.appendChild(chrome);
      root.insertBefore(toolbar, shell || root.firstChild);
    }
    const orphanChrome = root.querySelector(":scope > .preview-viewport-chrome");
    const toolbarChrome = toolbar.querySelector(".preview-viewport-chrome");
    if (orphanChrome && toolbarChrome && orphanChrome !== toolbarChrome) {
      toolbarChrome.replaceWith(orphanChrome);
    } else if (orphanChrome && !toolbarChrome) {
      toolbar.appendChild(orphanChrome);
    }
    return toolbar;
  }

  function updateManageZoomToolbar(root) {
    if (!viewportToolbarEnabled(root)) return;
    ensureManageZoomToolbar(root);
    const bar = root.querySelector("[data-preview-zoom-bar]");
    if (!bar) return;
    const mode = String(root.dataset.previewZoom || "fit");
    const applied = Number(root.dataset.meiAppliedZoom || 1);
    bar.querySelectorAll("[data-preview-zoom]").forEach((btn) => {
      const zoom = String(btn.dataset.previewZoom || "");
      const isStep = zoom === "minus" || zoom === "plus";
      const isActive =
        !isStep &&
        (zoom === mode ||
          (mode !== "fit" &&
            zoom !== "minus" &&
            zoom !== "plus" &&
            Math.abs(Number(zoom) - Number(mode)) < 0.001));
      btn.classList.toggle("is-active", isActive);
    });
    const readout = bar.querySelector("[data-preview-zoom-readout]");
    if (readout) {
      readout.textContent = `${Math.round(applied * 100)}%`;
    }
  }

  function unlockStageLayoutForDebug(stage, designHeight, fluidHeight) {
    stage.style.overflow = "visible";
    stage.style.height = "auto";
    stage.style.minHeight = fluidHeight ? "0" : `${round(designHeight)}px`;
    stage.style.maxHeight = "none";
    if (fluidHeight) {
      relaxPageFlowStageGrid(stage);
    } else if (stage.dataset.meiDebugLayoutUnlocked !== "true") {
      const rows = getComputedStyle(stage).gridTemplateRows;
      if (rows && rows !== "none") {
        const parts = rows.split(/\s+/).filter((row) => row && row !== "none");
        stage.style.gridTemplateRows = parts
          .map((row, index) => {
            if (/^\d+(\.\d+)?px$/.test(row) && parseFloat(row) < 48) {
              return "minmax(240px, auto)";
            }
            if (index === 0) return row;
            if (/minmax|fr/i.test(row)) return "auto";
            return row;
          })
          .join(" ");
      }
      stage.dataset.meiDebugLayoutUnlocked = "true";
    }
    stage.querySelectorAll(".preview-card, .preview-panel-body").forEach((node) => {
      node.style.overflow = "visible";
      node.style.maxHeight = "none";
    });
  }

  function resolveCanvasWidth(root, designWidth) {
    const cap = Number(root.dataset.contentMaxWidth || 0);
    const declared = Number(designWidth || root.dataset.designWidth || 0);
    if (cap > 0 && declared > 0) return Math.min(cap, declared);
    return declared;
  }

  function clearDebugOverlayNodes(container) {
    container
      ?.querySelectorAll(
        ".preview-design-bounds, .preview-design-overflow-veil, .preview-design-overflow-veil-x",
      )
      .forEach((node) => node.remove());
  }

  /** 在布局坐标（未缩放）下测量；勿用缩放后的 getBoundingClientRect（边栏变宽→zoom 变大→假横向溢出）。 */
  function measureStageContentExtent(stage, contentMaxWidth) {
    const cap = contentMaxWidth > 0 ? contentMaxWidth : 0;
    if (cap > 0 && stage.offsetWidth > 0 && stage.offsetWidth <= cap + 2) {
      const height = Math.max(stage.offsetHeight, stage.scrollHeight);
      return { width: cap, height: Math.max(1, height) };
    }
    let maxRight = 0;
    let maxBottom = 0;
    let hasContent = false;
    stage
      .querySelectorAll(".preview-card, .panel-head-cell, .panel-body-cell, .panel-heading, .preview-panel-body")
      .forEach((node) => {
        if (
          node.closest(
            ".preview-design-bounds, .preview-design-overflow-veil, .preview-design-overflow-veil-x",
          )
        ) {
          return;
        }
        const right = node.offsetLeft + node.offsetWidth;
        const bottom = node.offsetTop + node.offsetHeight;
        if (node.offsetWidth < 1 || node.offsetHeight < 1) return;
        hasContent = true;
        if (right > maxRight) maxRight = right;
        if (bottom > maxBottom) maxBottom = bottom;
      });
    let width = hasContent ? Math.max(1, maxRight, stage.offsetWidth) : stage.offsetWidth;
    let height = hasContent ? Math.max(1, maxBottom, stage.offsetHeight) : stage.offsetHeight;
    if (cap > 0 && width <= cap + 2) {
      width = cap;
    }
    return { width, height };
  }

  function measureStageContentExtentByRect(stage, contentMaxWidth) {
    const cap = contentMaxWidth > 0 ? contentMaxWidth : 0;
    const stageRect = stage.getBoundingClientRect();
    if (cap > 0 && stageRect.width > 0 && stageRect.width <= cap + 2) {
      return { width: cap, height: Math.max(1, stageRect.height) };
    }
    let maxRight = 0;
    let maxBottom = 0;
    let hasContent = false;
    stage
      .querySelectorAll(".preview-card, .panel-head-cell, .panel-body-cell, .panel-heading, .preview-panel-body")
      .forEach((node) => {
        if (
          node.closest(
            ".preview-design-bounds, .preview-design-overflow-veil, .preview-design-overflow-veil-x",
          )
        ) {
          return;
        }
        const rect = node.getBoundingClientRect();
        if (rect.width < 1 || rect.height < 1) return;
        hasContent = true;
        const right = rect.right - stageRect.left;
        const bottom = rect.bottom - stageRect.top;
        if (right > maxRight) maxRight = right;
        if (bottom > maxBottom) maxBottom = bottom;
      });
    let width = hasContent ? Math.max(1, maxRight, stageRect.width) : stageRect.width;
    let height = hasContent ? Math.max(1, maxBottom, stageRect.height) : stageRect.height;
    if (cap > 0 && width <= cap + 2) {
      width = cap;
    }
    return { width, height };
  }

  function measureStageContentSize(
    stage,


/* ===== frame-stage/viewport/p2.js ===== */
    canvasWidth,
    designHeight,
    fluidHeight,
    contentMaxWidth,
  ) {
    const extent = measureStageContentExtent(stage, contentMaxWidth);
    return {
      width: Math.max(canvasWidth, extent.width),
      extentWidth: extent.width,
      height: Math.max(fluidHeight ? extent.height : designHeight, extent.height),
      extentHeight: extent.height,
    };
  }

  function nodeAuditLabel(node) {
    if (!node) return "unknown";
    const id = node.id ? `#${node.id}` : "";
    if (id) return id;
    const area =
      node.getAttribute("data-area") || node.getAttribute("area") || node.dataset?.area;
    if (area) return `${node.tagName.toLowerCase()}[area=${area}]`;
    const klass = String(node.className || "")
      .split(/\s+/)
      .map((item) => item.trim())
      .filter(Boolean)[0];
    if (klass) return `${node.tagName.toLowerCase()}.${klass}`;
    return node.tagName.toLowerCase();
  }

  function closestPanelId(node) {
    const panel = node?.closest?.(".preview-card[data-mei-panel-id]");
    const id = String(panel?.getAttribute?.("data-mei-panel-id") || "").trim();
    return id || null;
  }

  function closestPanelLabel(node) {
    const panel = node?.closest?.(".preview-card[data-mei-panel-id]");
    return panel ? nodeAuditLabel(panel) : nodeAuditLabel(node);
  }

  function parsePropsPayload(node) {
    const raw = String(node?.getAttribute?.("data-props") || "").trim();
    if (!raw) return {};
    try {
      return JSON.parse(raw);
    } catch (_) {
      return {};
    }
  }

  function metricRoleNodes(card) {
    return Array.from(card.querySelectorAll("[data-props]"))
      .map((node) => ({ node, props: parsePropsPayload(node) }))
      .filter((entry) => String(entry.props?.metric_role || "").trim());
  }

  function widthBucket(width) {
    return Math.round(Number(width || 0) / 16) * 16;
  }

  function buildRuntimeEvalReport(diagnostics) {
    const items = Array.isArray(diagnostics) ? diagnostics : [];
    const severityWeight = {
      error: 100,
      warning: 40,
      info: 10,
    };
    const metrics = {
      total: items.length,
      errors: 0,
      warnings: 0,
      infos: 0,
      countsByCode: {},
    };
    const panelScores = new Map();
    let score = 0;
    items.forEach((diag) => {
      const severity = String(diag?.severity || "info").trim().toLowerCase();
      if (severity === "error") metrics.errors += 1;
      else if (severity === "warning") metrics.warnings += 1;
      else metrics.infos += 1;
      const weight = severityWeight[severity] || 0;
      score += weight;
      const code = String(diag?.code || "layout_eval_runtime_unknown").trim();
      metrics.countsByCode[code] = (metrics.countsByCode[code] || 0) + 1;
      const panelId = String(diag?.panelId || "").trim();
      if (panelId) {
        panelScores.set(panelId, (panelScores.get(panelId) || 0) + weight);
      }
    });
    const worstPanels = Array.from(panelScores.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([panelId, panelScore]) => ({
        panelId,
        score: panelScore,
      }));
    return {
      score,
      blocking: metrics.errors > 0,
      worstPanels,
      metrics,
    };
  }

  function detectDegenerateBoxes(stage, limit = 8) {
    const hits = [];
    stage
      .querySelectorAll(
        ".preview-card, .preview-panel-body, .panel-body-cell, .panel-head-cell, .panel-heading",
      )
      .forEach((node) => {
        if (hits.length >= limit) return;
        if (node.offsetWidth > 0 && node.offsetHeight > 0) return;
        hits.push({
          panelId: closestPanelId(node),
          label: nodeAuditLabel(node),
        });
      });
    return hits;
  }

  function detectClippedNodes(stage, limit = 8) {
    const hits = [];
    stage
      .querySelectorAll(
        ".preview-card, .preview-panel-body, .panel-body-cell, .panel-head-cell, .panel-heading",
      )
      .forEach((node) => {
        if (hits.length >= limit) return;
        const style = getComputedStyle(node);
        const clipsY = /hidden|clip/.test(style.overflowY || style.overflow || "");
        const clipsX = /hidden|clip/.test(style.overflowX || style.overflow || "");
        if (!clipsY && !clipsX) return;
        const nodeRect = node.getBoundingClientRect();
        let xOverflow = false;
        let yOverflow = false;
        node.querySelectorAll(":scope > *, :scope > * *").forEach((child) => {
          if (xOverflow && yOverflow) return;
          if (!(child instanceof Element)) return;
          const rect = child.getBoundingClientRect();
          if (rect.width < 1 || rect.height < 1) return;
          if (clipsX && (rect.left < nodeRect.left - 1 || rect.right > nodeRect.right + 1)) {
            xOverflow = true;
          }
          if (clipsY && (rect.top < nodeRect.top - 1 || rect.bottom > nodeRect.bottom + 1)) {
            yOverflow = true;
          }
        });
        if ((clipsY && yOverflow) || (clipsX && xOverflow)) {
          hits.push({
            panelId: closestPanelId(node),
            label: nodeAuditLabel(node),
          });
        }
      });
    return hits;
  }

  function detectHeadMetricSpacing(stage, limit = 6) {
    const hits = [];
    stage.querySelectorAll(".preview-card").forEach((panel) => {
      if (hits.length >= limit) return;
      const head = panel.querySelector(":scope > .panel-head-cell");
      const body = panel.querySelector(":scope > .panel-body-cell");
      if (!head || !body) return;
      const first = body.querySelector(
        ":scope > .preview-card, :scope > .component-card, :scope > .mei-text, :scope > [data-metric-role]",
      );
      if (!first) return;
      const gap = first.getBoundingClientRect().top - body.getBoundingClientRect().top;
      if (gap > 28) {
        hits.push({
          panelId: String(panel.getAttribute("data-mei-panel-id") || "").trim() || null,
          label: nodeAuditLabel(panel),
          gap,
        });
      }
    });
    return hits;
  }

  function detectBottomClipRisk(stage, limit = 6) {
    const hits = [];
    stage.querySelectorAll(".preview-card").forEach((panel) => {
      if (hits.length >= limit) return;
      const body = panel.querySelector(":scope > .panel-body-cell");
      if (!body) return;
      const panelStyle = getComputedStyle(panel);
      const bodyStyle = getComputedStyle(body);
      const panelClips = /hidden|clip/.test(panelStyle.overflowY || panelStyle.overflow || "");
      const bodyClips = /hidden|clip/.test(bodyStyle.overflowY || bodyStyle.overflow || "");
      if (!panelClips && !bodyClips) return;
      const bodyRect = body.getBoundingClientRect();
      let maxBottom = bodyRect.top;
      body
        .querySelectorAll(":scope > .preview-card, :scope > .component-card, :scope > *")
        .forEach((node) => {
          const rect = node.getBoundingClientRect();
          if (rect.height < 1) return;
          if (rect.bottom > maxBottom) maxBottom = rect.bottom;
        });
      if (maxBottom > bodyRect.bottom + 1) {
        hits.push({
          panelId: String(panel.getAttribute("data-mei-panel-id") || "").trim() || null,
          label: nodeAuditLabel(panel),
          overflowPx: maxBottom - bodyRect.bottom,
        });
      }
    });
    return hits;
  }

  function rectsOverlap(a, b) {
    return (
      a.left < b.right - 1 &&
      a.right > b.left + 1 &&
      a.top < b.bottom - 1 &&
      a.bottom > b.top + 1
    );
  }

  function rectOverlapX(a, b) {
    return Math.min(a.right, b.right) - Math.max(a.left, b.left);
  }

  function rectOverlapY(a, b) {
    return Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
  }

  function detectCardOverlap(stage, limit = 6) {
    const hits = [];
    stage.querySelectorAll(".panel-body-cell").forEach((body) => {
      if (hits.length >= limit) return;
      const groupPanelId = closestPanelId(body);
      const groupLabel = closestPanelLabel(body);
      const cards = Array.from(
        body.querySelectorAll(':scope > .preview-card[data-mei-panel-id]'),
      );
      if (cards.length < 2) return;
      for (let i = 0; i < cards.length; i += 1) {
        if (hits.length >= limit) break;
        const a = cards[i].getBoundingClientRect();
        if (a.width < 1 || a.height < 1) continue;
        for (let j = i + 1; j < cards.length; j += 1) {
          if (hits.length >= limit) break;
          const b = cards[j].getBoundingClientRect();
          if (b.width < 1 || b.height < 1) continue;
          if (rectsOverlap(a, b)) {
            hits.push({
              panelId: groupPanelId,
              label: groupLabel,
              pair: [nodeAuditLabel(cards[i]), nodeAuditLabel(cards[j])],
            });
          }
        }
      }
    });
    return hits;
  }

  function detectCardGapBudget(stage, limit = 6) {
    const hits = [];
    stage.querySelectorAll(".panel-body-cell").forEach((body) => {
      if (hits.length >= limit) return;
      const groupPanelId = closestPanelId(body);
      const groupLabel = closestPanelLabel(body);
      const cards = Array.from(
        body.querySelectorAll(':scope > .preview-card[data-mei-panel-id]'),
      );
      if (cards.length < 2) return;
      const isMetricGroup = cards.every((card) => metricRoleNodes(card).length > 0);
      const maxHorizontalGap = isMetricGroup ? 32 : 12;
      const maxVerticalGap = isMetricGroup ? 24 : 16;
      const maxPadding = isMetricGroup ? 64 : 24;
      const bodyRect = body.getBoundingClientRect();
      const horizontal = cards
        .map((node) => node.getBoundingClientRect())
        .filter((rect) => rect.width > 1 && rect.height > 1)
        .sort((a, b) => a.left - b.left);
      if (horizontal.length >= 2) {
        const pair = horizontal.find((rect, idx) => {
          if (idx === 0) return false;
          return rectOverlapY(horizontal[idx - 1], rect) > 8;
        });
        const pairIdx = pair ? horizontal.indexOf(pair) : -1;
        const prev = pairIdx > 0 ? horizontal[pairIdx - 1] : null;
        const gap = prev && pair ? pair.left - prev.right : null;
        if (gap != null && (gap < 4 || gap > maxHorizontalGap)) {
          hits.push({
            panelId: groupPanelId,
            label: groupLabel,
            axis: "horizontal",
            gap,
          });
        }
      }
      const vertical = cards
        .map((node) => node.getBoundingClientRect())
        .filter((rect) => rect.width > 1 && rect.height > 1)
        .sort((a, b) => a.top - b.top);
      if (vertical.length >= 2) {
        const pair = vertical.find((rect, idx) => {
          if (idx === 0) return false;
          return rectOverlapX(vertical[idx - 1], rect) > 8;
        });
        const pairIdx = pair ? vertical.indexOf(pair) : -1;
        const prev = pairIdx > 0 ? vertical[pairIdx - 1] : null;
        const gap = prev && pair ? pair.top - prev.bottom : null;
        if (gap != null && (gap < 4 || gap > maxVerticalGap)) {
          hits.push({
            panelId: groupPanelId,
            label: groupLabel,
            axis: "vertical",
            gap,
          });
        }
      }
      const leftPad = Math.max(0, horizontal[0]?.left - bodyRect.left || 0);
      const rightPad = Math.max(
        0,
        bodyRect.right - (horizontal[horizontal.length - 1]?.right || bodyRect.right),
      );
      const topPad = Math.max(0, vertical[0]?.top - bodyRect.top || 0);
      const bottomPad = Math.max(
        0,
        bodyRect.bottom - (vertical[vertical.length - 1]?.bottom || bodyRect.bottom),
      );
      const maxPad = Math.max(leftPad, rightPad, topPad, bottomPad);
      if (maxPad > maxPadding) {
        hits.push({
          panelId: groupPanelId,
          label: groupLabel,
          axis: "padding",
          gap: maxPad,
        });
      }
      const horizontalPadDelta = Math.abs(leftPad - rightPad);
      if (horizontalPadDelta > 12) {
        hits.push({
          panelId: groupPanelId,
          label: groupLabel,
          axis: "padding_symmetry",
          gap: horizontalPadDelta,
          leftPad,
          rightPad,
        });


/* ===== frame-stage/viewport/p3.js ===== */
      }
    });
    return hits;
  }

  function detectMetricVerticalBandDrift(stage, limit = 6) {
    const hits = [];
    stage.querySelectorAll(".preview-card[data-mei-panel-id]").forEach((card) => {
      if (hits.length >= limit) return;
      const rect = card.getBoundingClientRect();
      if (rect.width < 8 || rect.height < 24) return;
      const roles = metricRoleNodes(card);
      const labelNode = roles.find((entry) => entry.props.metric_role === "label");
      const valueNode = roles.find((entry) => entry.props.metric_role === "value");
      if (!labelNode || !valueNode) return;
      const labelRect = labelNode.node.getBoundingClientRect();
      const valueRect = valueNode.node.getBoundingClientRect();
      const midY = rect.top + rect.height * 0.5;
      const labelCenterY = (labelRect.top + labelRect.bottom) / 2;
      const valueBottomY = valueRect.bottom;
      const panelId = closestPanelId(card);
      const label = closestPanelLabel(card);
      if (labelCenterY > midY + 6) {
        hits.push({
          panelId,
          label,
          role: "label",
          spread: labelCenterY - midY,
          detail: "label_below_midline",
        });
        return;
      }
      if (valueBottomY < midY - 4) {
        hits.push({
          panelId,
          label,
          role: "value",
          spread: midY - valueBottomY,
          detail: "value_above_midline",
        });
      }
    });
    return hits;
  }

  function detectMetricAlignmentDrift(stage, limit = 6) {
    const hits = [];
    stage.querySelectorAll(".panel-body-cell").forEach((body) => {
      if (hits.length >= limit) return;
      const groupPanelId = closestPanelId(body);
      const groupLabel = closestPanelLabel(body);
      const cards = Array.from(
        body.querySelectorAll(':scope > .preview-card[data-mei-panel-id]'),
      )
        .map((card) => {
          const rect = card.getBoundingClientRect();
          const roles = metricRoleNodes(card);
          const slotRects = {
            label: roles
              .filter((entry) => entry.props.metric_role === "label")
              .map((entry) => entry.node.getBoundingClientRect().left - rect.left),
            value: roles
              .filter((entry) => entry.props.metric_role === "value")
              .map((entry) => entry.node.getBoundingClientRect().right - rect.left),
            unit: roles
              .filter((entry) => entry.props.metric_role === "unit")
              .map((entry) => entry.node.getBoundingClientRect().right - rect.left),
          };
          return { rect, slotRects };
        })
        .filter((entry) => entry.rect.width > 1 && entry.rect.height > 1);
      if (cards.length < 2) return;
      const buckets = new Map();
      cards.forEach((card) => {
        const bucket = widthBucket(card.rect.width);
        if (!buckets.has(bucket)) buckets.set(bucket, []);
        buckets.get(bucket).push(card);
      });
      buckets.forEach((bucketCards) => {
        if (bucketCards.length < 2 || hits.length >= limit) return;
        const labelLefts = bucketCards.flatMap((item) => item.slotRects.label);
        const valueRights = bucketCards.flatMap((item) => item.slotRects.value);
        const unitRights = bucketCards.flatMap((item) => item.slotRects.unit);
        const spreads = [];
        if (labelLefts.length >= 2) {
          spreads.push({ role: "label", spread: Math.max(...labelLefts) - Math.min(...labelLefts) });
        }
        if (valueRights.length >= 2) {
          spreads.push({ role: "value", spread: Math.max(...valueRights) - Math.min(...valueRights) });
        }
        if (unitRights.length >= 2) {
          spreads.push({ role: "unit", spread: Math.max(...unitRights) - Math.min(...unitRights) });
        }
        const worst = spreads.sort((a, b) => b.spread - a.spread)[0];
        if (worst && worst.spread > 8) {
          hits.push({
            panelId: groupPanelId,
            label: groupLabel,
            role: worst.role,
            spread: worst.spread,
          });
        }
      });
    });
    return hits;
  }

  const LAYOUT_AUDIT_EVENT = "mei:layout-audit";

  function layoutAuditStorageKey(sourcePath) {
    const pathname = String(window.location.pathname || "").trim();
    const source = String(sourcePath || "main.mei").trim() || "main.mei";
    return `mei:layout-audit:${pathname}:${source}`;
  }

  function persistLayoutAudit(payload) {
    try {
      const key = layoutAuditStorageKey(payload?.sourcePath);
      sessionStorage.setItem(key, JSON.stringify(payload));
    } catch (_) {}
  }

  function dispatchLayoutAudit(targetDocument, payload) {
    if (!targetDocument) return;
    targetDocument.dispatchEvent(new CustomEvent(LAYOUT_AUDIT_EVENT, { detail: payload }));
  }

  function sceneIdFromLocation() {
    try {
      const url = new URL(window.location.href);
      const scene = String(url.searchParams.get("scene") || "").trim();
      if (scene) return scene;
      const match = String(url.pathname || "").match(/\/scene\/([^/?#]+)/i);
      if (match && match[1]) {
        return decodeURIComponent(match[1]);
      }
    } catch (_) {}
    return "";
  }

  function collectPanelMeta(stage) {
    const map = new Map();
    if (!stage || !stage.querySelectorAll) return map;
    stage.querySelectorAll("[data-mei-panel-id]").forEach((panel) => {
      const panelId = String(panel.getAttribute("data-mei-panel-id") || "").trim();
      if (!panelId || map.has(panelId)) return;
      const label =
        String(panel.querySelector?.("[data-mei-panel-head]")?.getAttribute?.("aria-label") || "").trim() ||
        panelId;
      map.set(panelId, {
        panelId,
        panelLabel: label,
        componentLabel: label,
      });
    });
    return map;
  }

  function enrichLayoutDiagnostics(diagnostics, panelMeta, sceneId, targetFile) {
    const list = Array.isArray(diagnostics) ? diagnostics : [];
    return list.map((diag) => {
      const panelId = String(diag?.panelId || "").trim();
      const panel = panelId ? panelMeta.get(panelId) : null;
      const panelLabel = String(diag?.panelLabel || diag?.label || panel?.panelLabel || "").trim();
      const componentLabel = String(diag?.component_label || panelLabel || panel?.componentLabel || "").trim();
      return {
        ...diag,
        panelId: panelId || undefined,
        panelLabel: panelLabel || undefined,
        component_label: componentLabel || undefined,
        scene_id: sceneId || undefined,
        target_file: targetFile || undefined,
        source_path: String(diag?.source_path || targetFile || "").trim() || undefined,
      };
    });
  }

  function publishLayoutAudit(root, stage, diagnostics, report = {}) {
    const targetFile = String(
      root?.dataset?.targetFile || root?.dataset?.sourcePath || root?.dataset?.activeTarget || "main.mei"
    ).trim();
    const sceneId = String(root?.dataset?.sceneId || "").trim() || sceneIdFromLocation();
    const panelMeta = collectPanelMeta(stage);
    const normalizedDiagnostics = enrichLayoutDiagnostics(diagnostics, panelMeta, sceneId, targetFile);
    const normalizedWorstPanels = (Array.isArray(report?.worstPanels) ? report.worstPanels : []).map((entry) => {
      const panelId = String(entry?.panelId || "").trim();
      const panel = panelId ? panelMeta.get(panelId) : null;
      return {
        ...entry,
        panelId: panelId || entry?.panelId,
        panelLabel: String(entry?.panelLabel || panel?.panelLabel || "").trim() || undefined,
      };
    });
    const payload = {
      sourcePath: targetFile || "main.mei",
      targetFile: targetFile || "main.mei",
      sceneId: sceneId || undefined,
      diagnostics: normalizedDiagnostics,
      score: Number(report?.score || 0),
      blocking: report?.blocking === true,
      worstPanels: normalizedWorstPanels,
      metrics: report?.metrics && typeof report.metrics === "object" ? report.metrics : {},
    };
    window.__meiLastLayoutEval = payload;
    persistLayoutAudit(payload);
    dispatchLayoutAudit(document, payload);
    if (window.parent && window.parent !== window) {
      try {
        window.parent.__meiLastLayoutEval = payload;
      } catch (_) {}
      try {
        dispatchLayoutAudit(window.parent.document, payload);
      } catch (_) {}
      try {
        window.parent.postMessage({ type: LAYOUT_AUDIT_EVENT, detail: payload }, window.location.origin);
      } catch (_) {}
    }
  }

  function runLayoutAudit(
    root,
    stage,
    designWidth,
    designHeight,
    contentWidth,
    contentHeight,
    extentWidth,
  ) {
    if (!root || !stage) return;
    const diagnostics = [];
    if (extentWidth > designWidth + 1) {
      diagnostics.push({
        severity: "error",
        code: "layout_eval_canvas_overflow_x",
        message: `横向内容超出设计宽度：实测 ${Math.round(extentWidth)}px / 设计 ${Math.round(designWidth)}px`,
      });
    }
    if (contentHeight > designHeight + 1) {
      diagnostics.push({
        severity: "warning",
        code: "layout_eval_canvas_overflow_y",
        message: `纵向内容超出设计高度：实测 ${Math.round(contentHeight)}px / 设计 ${Math.round(designHeight)}px`,
      });
    }
    const clipped = detectClippedNodes(stage);
    if (clipped.length) {
      diagnostics.push({
        severity: "error",
        code: "layout_eval_clipped_content",
        panelId: clipped[0]?.panelId || null,
        message: `检测到父容器裁切风险：${clipped.map((hit) => hit.label).join("、")}`,
      });
    }
    const degenerate = detectDegenerateBoxes(stage);
    if (degenerate.length) {
      diagnostics.push({
        severity: "error",
        code: "layout_eval_degenerate_box",
        panelId: degenerate[0]?.panelId || null,
        message: `检测到零尺寸/退化盒：${degenerate.map((hit) => hit.label).join("、")}`,
      });
    }
    const spacing = detectHeadMetricSpacing(stage);
    if (spacing.length) {
      diagnostics.push({
        severity: "info",
        code: "layout_eval_head_body_spacing_loose",
        panelId: spacing[0]?.panelId || null,
        message: `检测到标题与指标区起始距离偏大：${spacing
          .map((hit) => `${hit.label}(+${Math.round(hit.gap)}px)`)
          .join("、")}`,
      });
    }
    const bottomClip = detectBottomClipRisk(stage);
    if (bottomClip.length) {
      diagnostics.push({
        severity: "error",
        code: "layout_eval_panel_bottom_clip_risk",
        panelId: bottomClip[0]?.panelId || null,
        message: `检测到 panel 底部裁切风险：${bottomClip
          .map((hit) => `${hit.label}(+${Math.round(hit.overflowPx)}px)`)
          .join("、")}`,
      });
    }
    const overlap = detectCardOverlap(stage);
    if (overlap.length) {
      diagnostics.push({
        severity: "error",
        code: "layout_eval_card_overlap",
        panelId: overlap[0]?.panelId || null,
        message: `检测到卡片重叠：${overlap
          .map((hit) => `${hit.label}(${hit.pair.join(" x ")})`)
          .join("、")}`,
      });
    }
    const gapBudget = detectCardGapBudget(stage);
    if (gapBudget.length) {
      diagnostics.push({
        severity: gapBudget.some(
          (hit) => hit.axis === "padding" || hit.axis === "padding_symmetry",
        )
          ? "warning"
          : "info",
        code: "layout_eval_card_gap_budget_runtime",
        panelId: gapBudget[0]?.panelId || null,
        message: `检测到卡组 gap/留白偏离预算：${gapBudget
          .map((hit) => {
            if (hit.axis === "padding") return `${hit.label}(四周留白≈${Math.round(hit.gap)}px)`;
            if (hit.axis === "padding_symmetry") {
              return `${hit.label}(左右留白≈${Math.round(hit.leftPad || 0)}px/${Math.round(hit.rightPad || 0)}px)`;
            }
            const axis = hit.axis === "vertical" ? "纵向" : "横向";
            return `${hit.label}(${axis} gap≈${Math.round(hit.gap)}px)`;
          })
          .join("、")}`,
      });
    }
    const alignment = detectMetricAlignmentDrift(stage);
    if (alignment.length) {
      diagnostics.push({
        severity: "warning",
        code: "layout_eval_metric_alignment_drift",
        panelId: alignment[0]?.panelId || null,
        message: `检测到指标参考线漂移：${alignment
          .map((hit) => `${hit.label}(${hit.role} 偏移≈${Math.round(hit.spread)}px)`)
          .join("、")}`,
      });
    }
    const verticalBands = detectMetricVerticalBandDrift(stage);
    if (verticalBands.length) {
      diagnostics.push({
        severity: "warning",
        code: "layout_eval_metric_vertical_band_drift",
        panelId: verticalBands[0]?.panelId || null,
        message: `检测到指标垂直分区落点偏离：${verticalBands
          .map((hit) => {
            const hint =
              hit.detail === "label_below_midline"
                ? "标题区落入下半区"
                : "数值区落在上半区";
            return `${hit.label}(${hint}，≈${Math.round(hit.spread)}px)`;
          })
          .join("、")}`,
      });
    }
    publishLayoutAudit(root, stage, diagnostics, buildRuntimeEvalReport(diagnostics));
  }


/* ===== frame-stage/manage-zoom.js ===== */
  function shouldShowHorizontalOverflowVeil(canvasWidth, extentWidth, contentMaxWidth) {
    const cap = contentMaxWidth > 0 ? contentMaxWidth : 0;
    if (cap > 0) {
      if (extentWidth <= cap + 2) return false;
      if (extentWidth <= canvasWidth + 2) return false;
    }
    return extentWidth > canvasWidth + 2;
  }

  function removeDesignBounds(shell) {
    const container = debugLayoutContainer(shell);
    container?.querySelector(".preview-design-bounds")?.remove();
    container?.querySelector(".preview-design-overflow-veil")?.remove();
    container?.querySelector(".preview-design-overflow-veil-x")?.remove();
    shell?.querySelector(".preview-design-bounds")?.remove();
    shell?.querySelector(".preview-design-overflow-veil")?.remove();
    shell?.querySelector(".preview-design-overflow-veil-x")?.remove();
    removeViewportChrome(shell?.closest('[data-mei-frame-viewport="true"]'), shell);
  }

  function ensureDesignBounds(shell, designWidth, designHeight, scale) {
    let bounds = shell.querySelector(".preview-design-bounds");
    if (!bounds) {
      bounds = document.createElement("div");
      bounds.className = "preview-design-bounds";
      bounds.setAttribute("aria-hidden", "true");
      shell.appendChild(bounds);
    }
    bounds.style.width = `${round(designWidth * scale)}px`;
    bounds.style.height = `${round(designHeight * scale)}px`;
    return bounds;
  }

  /** 分辨率标签在 viewport 首行（管理端 SSR + 文档流）；仅更新文案，避免 shell overflow 裁切。 */
  function ensureViewportChrome(
    root,
    designWidth,
    designHeight,
    aspectRatio,
    contentHeight,
    fluidHeight,
  ) {
    if (!root) return;
    let chrome =
      root.querySelector(".preview-viewport-toolbar .preview-viewport-chrome") ||
      root.querySelector(":scope > .preview-viewport-chrome");
    if (!chrome) {
      const shell = root.querySelector(".preview-stage-shell");
      chrome = document.createElement("div");
      chrome.className = "preview-viewport-chrome";
      chrome.setAttribute("aria-hidden", "true");
      root.insertBefore(chrome, shell || root.firstChild);
    }
    const aspectSuffix =
      aspectRatio && String(aspectRatio).trim()
        ? ` · ${String(aspectRatio).trim()}`
        : "";
    const heightLabel =
      fluidHeight && contentHeight > 0
        ? Math.round(contentHeight)
        : Math.round(designHeight);
    const heightSuffix = fluidHeight ? " (内容高)" : "";
    let chromeText = `${Math.round(designWidth)} × ${heightLabel}${heightSuffix}${aspectSuffix}`;
    const measuredWidth = Number(root.dataset.meiContentWidth || 0);
    const measuredHeight = Number(root.dataset.meiContentHeight || 0);
    if (
      measuredWidth > designWidth + 1 ||
      measuredHeight > designHeight + 1
    ) {
      chromeText += ` · 实测 ${Math.round(measuredWidth)}×${Math.round(measuredHeight)}`;
    }
    const appliedZoom = Number(root.dataset.meiAppliedZoom || 0);
    if (appliedZoom > 0) {
      chromeText += ` · 缩放 ${Math.round(appliedZoom * 100)}%`;
    }
    chrome.textContent = chromeText;
    chrome.style.position = "";
    chrome.style.top = "";
    chrome.style.left = "";
    chrome.style.bottom = "";
    chrome.style.transform = "";
  }

  function ensureOverflowVeilLabel(veil, axis, overflowPx, contentSize, designSize) {
    let label = veil.querySelector(".preview-design-overflow-veil-label");
    if (!label) {
      label = document.createElement("span");
      label.className = "preview-design-overflow-veil-label";
      veil.appendChild(label);
    }
    const axisLabel = axis === "x" ? "横向" : "纵向";
    label.textContent = `${axisLabel}溢出 +${Math.round(overflowPx)}px（内容 ${Math.round(contentSize)} / 设计 ${Math.round(designSize)}）· 访问态将裁切`;
  }

  function ensureOverflowVeil(
    shell,
    designWidth,
    designHeight,
    scale,
    contentWidth,
    contentHeight,
    extentWidth,
    contentMaxWidth,
  ) {
    let veilY = shell.querySelector(":scope > .preview-design-overflow-veil:not(.preview-design-overflow-veil-x)");
    let veilX = shell.querySelector(":scope > .preview-design-overflow-veil-x");
    if (contentHeight > designHeight + 1) {
      if (!veilY) {
        veilY = document.createElement("div");
        veilY.className = "preview-design-overflow-veil";
        veilY.setAttribute("aria-hidden", "true");
        shell.appendChild(veilY);
      }
      const top = round(designHeight * scale);
      const height = round((contentHeight - designHeight) * scale);
      veilY.style.top = `${top}px`;
      veilY.style.left = "0";
      veilY.style.width = `${round(designWidth * scale)}px`;
      veilY.style.height = `${height}px`;
      ensureOverflowVeilLabel(
        veilY,
        "y",
        contentHeight - designHeight,
        contentHeight,
        designHeight,
      );
    } else {
      veilY?.remove();
    }
    const overflowExtentWidth = extentWidth > 0 ? extentWidth : contentWidth;
    if (
      shouldShowHorizontalOverflowVeil(
        designWidth,
        overflowExtentWidth,
        contentMaxWidth,
      )
    ) {
      if (!veilX) {
        veilX = document.createElement("div");
        veilX.className =
          "preview-design-overflow-veil preview-design-overflow-veil-x";
        veilX.setAttribute("aria-hidden", "true");
        shell.appendChild(veilX);
      }
      const left = round(designWidth * scale);
      const width = round((overflowExtentWidth - designWidth) * scale);
      veilX.style.top = "0";
      veilX.style.left = `${left}px`;
      veilX.style.width = `${width}px`;
      veilX.style.height = `${round(Math.max(designHeight, contentHeight) * scale)}px`;
      ensureOverflowVeilLabel(
        veilX,
        "x",
        overflowExtentWidth - designWidth,
        overflowExtentWidth,
        designWidth,
      );
    } else {
      veilX?.remove();
    }
  }

  function computeDebugScale(
    fluidHeight,
    scaleMode,
    hostWidth,
    hostHeight,
    designWidth,
    designHeight,
  ) {
    const sx = hostWidth / designWidth;
    const mode = String(scaleMode || "fit-width").trim().toLowerCase();
    if (fluidHeight || mode === "fit-width" || mode === "width" || mode === "fit_width") {
      return sx > 0 ? sx : 1;
    }
    if (mode === "cover" || mode === "contain") {
      return computeScale(mode, hostWidth, hostHeight, designWidth, designHeight);
    }
    return sx > 0 ? sx : 1;
  }

  function applyDebugPreviewLayout(
    root,
    shell,
    stage,
    hostWidth,
    hostHeight,
    designWidth,
    designHeight,
    fluidHeight,
    contentMaxWidth,
  ) {
    const canvasWidth = fluidHeight
      ? Math.min(designWidth, Math.max(1, hostWidth))
      : contentMaxWidth > 0
        ? Math.min(contentMaxWidth, designWidth)
        : designWidth;
    if (fluidHeight || (contentMaxWidth > 0 && designWidth > canvasWidth + 0.5)) {
      root.style.justifyItems = "start";
      root.style.alignItems = "start";
      root.style.alignContent = "start";
      shell.style.justifySelf = "start";
      shell.style.alignSelf = "start";
    }
    if (viewportToolbarEnabled(root)) {
      initManagePreviewZoom(root);
      ensureManageZoomToolbar(root);
    } else {
      root.querySelector(":scope > .preview-viewport-toolbar")?.remove();
    }
    const wrap = ensureStageScaleWrap(shell, stage);
    const inner = ensureStageScaleInner(wrap);
    clearDebugOverlayNodes(inner);
    inner.style.transform = "none";
    inner.style.width = "";
    inner.style.height = "";

    unlockStageLayoutForDebug(stage, designHeight, fluidHeight);
    stage.style.width = `${round(canvasWidth)}px`;
    stage.style.height = "auto";
    stage.style.maxHeight = "none";
    stage.style.transform = "none";
    stage.style.zoom = "";
    stage.style.transformOrigin = "top left";

    let {
      width: contentWidth,
      extentWidth,
      height: contentHeight,
    } = measureStageContentSize(
      stage,
      canvasWidth,
      designHeight,
      fluidHeight,
      contentMaxWidth,
    );

    const widthFit = computeManageWidthFitScale(
      root,
      hostWidth,
      contentWidth,
      fluidHeight,
    );
    const fitScale =
      widthFit != null
        ? widthFit
        : computeManageFitScale(
            hostWidth,
            hostHeight,
            contentWidth,
            contentHeight,
          );
    const rawZoom = String(root.dataset.previewZoom || "fit").trim().toLowerCase();
    let appliedZoom = resolveManagePreviewZoom(root, fitScale);
    if (
      fluidHeight &&
      widthFit != null &&
      (rawZoom === "fit" || rawZoom === "auto")
    ) {
      appliedZoom = widthFit;
    }
    const aspectRatio = String(root.dataset.aspectRatio || "").trim();
    const layoutKey = manageLayoutKey(
      contentWidth,
      contentHeight,
      appliedZoom,
      hostWidth,
      hostHeight,
      canvasWidth,
    );
    if (root.dataset.meiLayoutKey === layoutKey) {
      clearDebugOverlayNodes(inner);
      ensureDesignBounds(inner, canvasWidth, fluidHeight ? contentHeight : designHeight, 1);
      ensureOverflowVeil(
        inner,
        canvasWidth,
        designHeight,
        1,
        contentWidth,
        contentHeight,
        extentWidth,
        contentMaxWidth,
      );
      ensureViewportChrome(
        root,
        canvasWidth,
        designHeight,
        aspectRatio,
        contentHeight,
        fluidHeight,
      );
      updateManageZoomToolbar(root);
      runLayoutAudit(
        root,
        stage,
        canvasWidth,
        designHeight,
        contentWidth,
        contentHeight,
        extentWidth,
      );
      return;
    }
    root.dataset.meiLayoutKey = layoutKey;
    root.dataset.meiFitScale = String(round(fitScale));
    root.dataset.meiAppliedZoom = String(round(appliedZoom));
    root.dataset.meiFrameScale = String(round(appliedZoom));

    inner.style.width = `${round(contentWidth)}px`;
    inner.style.height = `${round(contentHeight)}px`;
    inner.style.transformOrigin = "top left";
    inner.style.transform =
      Math.abs(appliedZoom - 1) > 0.001 ? `scale(${appliedZoom})` : "none";

    const shellWidth = round(contentWidth * appliedZoom);
    const shellHeight = round(contentHeight * appliedZoom);

    wrap.style.display = "block";
    wrap.style.position = "relative";
    wrap.style.overflow = "visible";
    wrap.style.width = `${shellWidth}px`;
    wrap.style.height = `${shellHeight}px`;
    wrap.style.margin = "0";

    shell.style.display = "block";
    shell.style.overflow = "visible";
    shell.style.maxHeight = "none";
    shell.style.position = "relative";
    shell.style.margin = "0";
    shell.style.justifyContent = "";
    shell.style.alignItems = "";
    shell.style.width = `${shellWidth}px`;
    shell.style.height = `${shellHeight}px`;

    root.dataset.meiContentWidth = String(Math.round(contentWidth));
    root.dataset.meiContentHeight = String(Math.round(contentHeight));

    ensureViewportChrome(
      root,
      canvasWidth,
      designHeight,
      aspectRatio,
      contentHeight,
      fluidHeight,
    );
    const boundsHeight = fluidHeight ? contentHeight : designHeight;
    ensureDesignBounds(inner, canvasWidth, boundsHeight, 1);
    ensureOverflowVeil(
      inner,
      canvasWidth,
      designHeight,
      1,
      contentWidth,
      contentHeight,
      extentWidth,
      contentMaxWidth,
    );
    updateManageZoomToolbar(root);
    runLayoutAudit(
      root,
      stage,
      canvasWidth,
      designHeight,
      contentWidth,
      contentHeight,
      extentWidth,
    );

    scheduleManageViewportRelayout(root, contentHeight);
  }


/* ===== frame-stage/layout-audit.js ===== */
  const manageRelayoutTimers = new WeakMap();

  /** 异步内容（字体/图表）稳定前最多补测一次，避免每帧触发 ResizeObserver 振荡。 */
  function scheduleManageViewportRelayout(root, contentHeight) {
    const pass = Number(root.dataset.meiRelayoutPass || 0);
    if (pass >= 1) return;
    const prev = manageRelayoutTimers.get(root) || {};
    if (prev.t500) return;
    const prevH = Number(root.dataset.meiScheduledContentHeight || 0);
    if (pass > 0 && Math.abs(prevH - contentHeight) < 2) return;
    root.dataset.meiScheduledContentHeight = String(Math.round(contentHeight));
    prev.t500 = setTimeout(() => {
      const timers = manageRelayoutTimers.get(root) || {};
      timers.t500 = null;
      root.dataset.meiRelayoutPass = "1";
      delete root.dataset.meiLayoutKey;
      updateViewport(root);
    }, 500);
    manageRelayoutTimers.set(root, prev);
  }

  /** 拆掉 manage 调试缩放壳，避免 inner 设计宽与 stage 宿主宽不一致导致整块偏右。 */
  function flattenStageScaleWrap(shell, stage) {
    const wrap = shell?.querySelector(":scope > .preview-stage-scale-wrap");
    if (!wrap) return;
    removeDesignBounds(shell);
    const inner = wrap.querySelector(":scope > .preview-stage-scale-inner");
    const moveOut = (node) => {
      if (!node || node === wrap) return;
      shell.insertBefore(node, wrap);
    };
    if (inner) {
      inner.style.transform = "none";
      inner.style.width = "";
      inner.style.height = "";
      [...inner.childNodes].forEach(moveOut);
    } else {
      [...wrap.childNodes].forEach(moveOut);
    }
    wrap.remove();
    if (stage && stage.parentElement !== shell) {
      shell.appendChild(stage);
    }
  }

  /** page-flow：舞台与 panel 行高随内容，取消 1fr 撑满与 slot 居中留白。 */
  function relaxPageFlowStageGrid(stage) {
    const panels = stage?.querySelectorAll(":scope > .preview-card") || [];
    if (panels.length > 0) {
      stage.style.gridTemplateRows = `repeat(${panels.length}, auto)`;
    }
    panels.forEach((card) => {
      card.style.gridTemplate = "none";
      card.style.gridTemplateAreas = '"body"';
      card.style.gridTemplateColumns = "minmax(0, 1fr)";
      card.style.gridTemplateRows = "auto";
      card.style.alignSelf = "start";
      card.style.height = "auto";
      card.querySelectorAll(".panel-body-cell, .preview-panel-body").forEach((body) => {
        body.style.height = "auto";
        body.style.minHeight = "0";
        body.style.gridTemplateColumns = "minmax(0, 1fr)";
        body.style.gridTemplateAreas = "none";
      });
      card.querySelectorAll(".component-card").forEach((slot) => {
        slot.style.display = "flex";
        slot.style.flexDirection = "column";
        slot.style.alignItems = "stretch";
        slot.style.height = "auto";
        slot.style.minHeight = "0";
        slot.style.width = "100%";
        slot.style.maxWidth = "100%";
        slot.style.gridColumn = "1 / -1";
        slot.style.gridArea = "auto";
        slot.style.justifyContent = "flex-start";
      });
    });
  }

  /**
   * 访问态页面流（fluid_height）：定宽不超过宿主，左上对齐，纵向随内容延伸。
   */
  function resolvePageFlowHostWidth(root, safe, hostWidth) {
    const fromRoot = Math.max(
      1,
      (root?.clientWidth || 0) - safe.left - safe.right,
    );
    return Math.max(1, hostWidth || 0, fromRoot);
  }

  function applyFluidPageFlowLayout(root, shell, stage, hostWidth, designWidth) {
    flattenStageScaleWrap(shell, stage);
    removeDesignBounds(shell);
    const safe = readSafeInsets(root, String(root?.dataset?.overflowMode || "debug"));
    const effectiveHost = resolvePageFlowHostWidth(root, safe, hostWidth);
    const canvasWidth = Math.max(1, Math.min(designWidth, effectiveHost));
    root.style.display = "block";
    root.style.width = "100%";
    root.style.maxWidth = "100%";
    root.style.height = "auto";
    root.style.minHeight = "0";
    root.style.maxHeight = "none";
    root.style.justifyItems = "";
    root.style.alignItems = "";
    root.style.alignContent = "";
    shell.style.display = "block";
    shell.style.alignItems = "";
    shell.style.justifyContent = "";
    shell.style.justifySelf = "";
    shell.style.alignSelf = "";
    shell.style.width = "100%";
    shell.style.height = "auto";
    shell.style.maxWidth = "100%";
    shell.style.maxHeight = "none";
    shell.style.margin = "0";
    shell.style.marginInline = "0";
    shell.style.overflow = "visible";
    shell.style.position = "relative";
    stage.style.width = "100%";
    stage.style.maxWidth = `${round(canvasWidth)}px`;
    stage.style.margin = "0";
    stage.style.marginInline = "0";
    stage.style.height = "auto";
    stage.style.minHeight = "0";
    stage.style.maxHeight = "none";
    stage.style.transform = "none";
    stage.style.zoom = "";
    stage.style.transformOrigin = "top left";
    relaxPageFlowStageGrid(stage);
    root.dataset.meiFrameScale = "1";
    root.dataset.meiAppliedZoom = "1";
    root.style.setProperty("--mei-frame-scale", "1");
    shell.style.setProperty("--mei-frame-scale", "1");
    root.dataset.meiManageRelayout = "";
    delete root.dataset.meiLayoutKey;
    root.scrollLeft = 0;
  }

  /**
   * 访问 / 运行态：contain（默认）或 cover；contain 等比铺满宿主且不裁切，信纸区居中。
   */
  function applyCanvasScaleLayout(
    root,
    shell,
    stage,
    scaleMode,
    hostWidth,
    hostHeight,
    designWidth,
    designHeight,
  ) {
    removeDesignBounds(shell);
    const mode = String(scaleMode || "contain").trim().toLowerCase();
    const scale = computeScale(mode, hostWidth, hostHeight, designWidth, designHeight, root);
    const scaleText = round(scale);
    const shellWidth = round(designWidth * scale);
    const shellHeight = round(designHeight * scale);

    shell.style.display = "flex";
    shell.style.alignItems = "center";
    shell.style.justifyContent = "center";
    shell.style.width = `${shellWidth}px`;
    shell.style.height = `${shellHeight}px`;
    shell.style.maxWidth = "none";
    shell.style.maxHeight = "none";
    shell.style.margin = "0";
    shell.style.flex = "none";
    shell.style.position = "relative";
    shell.style.overflow = "hidden";
    shell.style.boxSizing = "border-box";

    stage.style.width = `${round(designWidth)}px`;
    stage.style.height = `${round(designHeight)}px`;
    stage.style.minHeight = "";
    stage.style.flexShrink = "0";
    stage.style.transformOrigin = "center center";
    stage.style.transform =
      Math.abs(scaleText - 1) > 0.001 ? `scale(${scaleText})` : "none";
    stage.style.zoom = "";

    root.dataset.meiFrameScale = String(scaleText);
    root.dataset.meiManageRelayout = "";
    root.style.setProperty("--mei-frame-scale", String(scaleText));
    shell.style.setProperty("--mei-frame-scale", String(scaleText));
  }

  function syncChromeNoneViewportBox(root) {
    if (!isChromeNoneAccess()) return;
    if (root.dataset.contentFluidHeight === "true") return;
    root.style.width = "100vw";
    root.style.height = "100vh";
    root.style.maxWidth = "100vw";
    root.style.maxHeight = "100vh";
    if (window.visualViewport) {
      root.style.width = `${window.visualViewport.width}px`;
      root.style.height = `${window.visualViewport.height}px`;
    }
  }

  function managePreviewTabIsActive() {
    try {
      const url = new URL(window.location.href);
      const tab = String(url.searchParams.get("tab") || "preview").trim().toLowerCase();
      return !tab || tab === "preview";
    } catch (_) {
      return true;
    }
  }

  function updateViewport(root) {
    if (!root || root.hidden || root.closest?.("[hidden]")) return;
    const auditOnly = root.dataset.meiLayoutAuditRoot === "true";
    if (auditOnly && String(root.dataset.routeMode || "").trim().toLowerCase() === "manage") {
      if (!managePreviewTabIsActive()) return;
    }
    const designWidthDeclared = Number(root.dataset.designWidth || 0);
    const designWidth = resolveCanvasWidth(root, designWidthDeclared);
    const designHeight = Number(root.dataset.designHeight || 0);
    const contentMaxWidth = Number(root.dataset.contentMaxWidth || 0);
    const contentHeightAttr = Number(root.dataset.contentHeight || 0);
    const fluidHeight = root.dataset.contentFluidHeight === "true";
    const contentHeight = contentHeightAttr || designHeight;
    const scaleMode = String(root.dataset.scaleMode || "contain").trim().toLowerCase();
    const editScaleMode = String(root.dataset.editScaleMode || "contain").trim().toLowerCase();
    const overflowMode = String(root.dataset.overflowMode || "clip").trim().toLowerCase();
    const safe = readSafeInsets(root, overflowMode);
    const shell = root.querySelector(".preview-stage-shell");
    const stage = root.querySelector(".preview-stage");
    if (auditOnly) {
      const auditStage =
        (root.matches?.(".preview-surface, .preview-stage") ? root : null) ||
        root.querySelector(".preview-surface, .preview-stage");
      if (!auditStage) return;
      const extent = measureStageContentExtentByRect(auditStage, contentMaxWidth);
      const auditWidth =
        designWidth ||
        auditStage.offsetWidth ||
        auditStage.getBoundingClientRect().width ||
        extent.width;
      const auditHeight =
        designHeight ||
        auditStage.offsetHeight ||
        auditStage.getBoundingClientRect().height ||
        extent.height;
      runLayoutAudit(
        root,
        auditStage,
        Math.max(1, auditWidth),
        Math.max(1, auditHeight),
        extent.width,
        extent.height,
        extent.width,
      );
      return;
    }
    if (!shell || !stage || !designWidth) return;

    syncChromeNoneViewportBox(root);
    const { hostWidth, hostHeight } = isManagePreviewRoute(root)
      ? resolveManageHostSize(root, safe)
      : resolveHostSize(root, safe);

    if (isManagePreviewRoute(root)) {
      if (viewportLayoutApplying.get(root)) return;
      viewportLayoutApplying.set(root, true);
      try {
        if (fluidHeight) {
          applyFluidPageFlowLayout(root, shell, stage, hostWidth, designWidth);
          unlockStageLayoutForDebug(stage, designHeight || contentHeight, true);
          if (viewportToolbarEnabled(root)) {
            initManagePreviewZoom(root);
            ensureManageZoomToolbar(root);
            updateManageZoomToolbar(root);
          }
          const canvasWidth = Math.max(
            1,
            Math.min(designWidth, Math.max(1, hostWidth)),
          );
          const extent = measureStageContentExtent(
            stage,
            contentMaxWidth > 0 ? contentMaxWidth : 0,
          );
          const aspectRatio = String(root.dataset.aspectRatio || "").trim();
          ensureViewportChrome(
            root,
            canvasWidth,
            designHeight || contentHeight,
            aspectRatio,
            extent.height,
            true,
          );
          runLayoutAudit(
            root,
            stage,
            canvasWidth,
            designHeight || contentHeight || extent.height,
            extent.width,
            extent.height,
            extent.width,
          );
        } else {
          applyDebugPreviewLayout(
            root,
            shell,
            stage,
            hostWidth,
            hostHeight,
            designWidthDeclared,
            designHeight || contentHeight,
            fluidHeight,
            contentMaxWidth > 0 ? contentMaxWidth : 0,
          );
        }
      } finally {
        requestAnimationFrame(() => viewportLayoutApplying.delete(root));
      }
      return;
    }

    if (fluidHeight) {
      applyFluidPageFlowLayout(root, shell, stage, hostWidth, designWidth);
      const extent = measureStageContentExtent(stage, designWidth);
      runLayoutAudit(
        root,
        stage,
        designWidth,
        designHeight || contentHeight || extent.height,
        extent.width,
        extent.height,
        extent.width,
      );
      return;
    }

    if (contentMaxWidth > 0) {
      applyFluidWidthLayout(shell, stage, contentMaxWidth, hostWidth);
      const extent = measureStageContentExtent(stage, contentMaxWidth);
      runLayoutAudit(
        root,
        stage,
        designWidth,
        designHeight || contentHeight,
        extent.width,
        extent.height,
        extent.width,
      );
      return;
    }

    if (!designHeight && !contentHeight) return;
    applyCanvasScaleLayout(
      root,
      shell,
      stage,
      scaleMode,
      hostWidth,
      hostHeight,
      designWidth,
      designHeight || contentHeight,
    );
    const extent = measureStageContentExtent(stage, contentMaxWidth);
    runLayoutAudit(
      root,
      stage,
      designWidth,
      designHeight || contentHeight,
      extent.width,
      extent.height,
      extent.width,
    );
  }


/* ===== frame-stage/lifecycle.js ===== */
  function observeHostResize(root) {
    const hosts = [];
    let node = root.parentElement;
    while (node && node !== document.body) {
      hosts.push(node);
      node = node.parentElement;
    }
    if (isChromeNoneAccess()) {
      hosts.push(document.body);
    }
    const seen = new Set();
    const callbacks = hosts
      .filter((host) => {
        if (!host || host === root || seen.has(host)) return false;
        seen.add(host);
        return true;
      })
      .map((host) => {
        const observer = new ResizeObserver(() => queueUpdateViewport(root));
        observer.observe(host);
        observers.add(observer);
        return observer;
      });
    return callbacks;
  }

  function observeViewport(root) {
    if (tracked.has(root)) {
      if (isManagePreviewRoute(root)) invalidateManageLayout(root);
      queueUpdateViewport(root);
      return;
    }
    const observersForRoot = [];
    const manage = isManagePreviewRoute(root);
    const scrollPane = root.closest(".preview-pane-scroll");
    const resizeTarget = manage && scrollPane ? scrollPane : root;
    const rootObserver = new ResizeObserver(() => queueUpdateViewport(root));
    rootObserver.observe(resizeTarget);
    observersForRoot.push(rootObserver);
    observers.add(rootObserver);

    if (!manage) {
      const hostObservers = observeHostResize(root);
      if (hostObservers?.length) observersForRoot.push(...hostObservers);
    }

    tracked.set(root, observersForRoot);
    invalidateManageLayout(root);
    updateViewport(root);
  }

  function scan(event) {
    if (event?.detail?.scope === "drilldown") return;
    if (event?.detail?.scope === "manage-board-preview") return;
    if (!shouldMountBuildPreviewRuntime()) return;
    document
      .querySelectorAll('[data-mei-frame-viewport="true"], [data-mei-layout-audit-root="true"]')
      .forEach((root) => observeViewport(root));
    scheduleMetricPrefetch();
  }

  const RUNTIME_QUERY_READY_EVENT = "meilang:runtime-query-ready";
  let runtimeQueryReady = Boolean(
    window.__meiDatasetRuntime &&
      typeof window.__meiDatasetRuntime.prefetchVisiblePanelMetrics === "function",
  );
  let pendingMetricPrefetch = false;

  function markRuntimeQueryReady() {
    runtimeQueryReady = true;
    if (pendingMetricPrefetch) {
      pendingMetricPrefetch = false;
      scheduleMetricPrefetch(0, { force: true });
    }
  }

  let metricPrefetchTimer = null;
  let lastMetricPrefetchKey = "";
  function buildMetricPrefetchKey() {
    const shell = document.querySelector(".shell[data-compile-target]");
    const scene = String(shell?.getAttribute("data-compile-scene") || "").trim();
    const target = String(shell?.getAttribute("data-compile-target") || "").trim();
    const viewport = document.querySelector("[data-mei-frame-viewport]");
    const queryStateId = String(viewport?.dataset?.queryStateId || "").trim();
    return `${scene}::${target}::${queryStateId}`;
  }
  function scheduleMetricPrefetch(delayMs = 0, options = {}) {
    const opts = options || {};
    if (!shouldMountBuildPreviewRuntime()) return;
    if (!opts.force && !runtimeQueryReady) {
      pendingMetricPrefetch = true;
      return;
    }
    const prefetchKey = buildMetricPrefetchKey();
    if (!opts.force && prefetchKey && prefetchKey === lastMetricPrefetchKey) {
      return;
    }
    if (metricPrefetchTimer != null && !opts.force) {
      return;
    }
    if (metricPrefetchTimer != null) {
      clearTimeout(metricPrefetchTimer);
    }
    metricPrefetchTimer = window.setTimeout(() => {
      metricPrefetchTimer = null;
      if (!opts.force && !runtimeQueryReady) {
        pendingMetricPrefetch = true;
        return;
      }
      if (document.body?.classList?.contains("access-drilldown-open")) {
        return;
      }
      lastMetricPrefetchKey = prefetchKey;
      window.dispatchEvent(new CustomEvent("meilang:prefetch-panel-metrics"));
    }, Math.max(0, Number(delayMs) || 0));
  }

  function scheduleViewportRelayout() {
    requestAnimationFrame(() => {
      document
        .querySelectorAll('[data-mei-frame-viewport="true"], [data-mei-layout-audit-root="true"]')
        .forEach((root) => {
          if (isManagePreviewRoute(root)) invalidateManageLayout(root);
          queueUpdateViewport(root);
        });
      scheduleMetricPrefetch(0);
    });
  }

  let domReadyHandler = null;
  if (document.readyState === "loading") {
    domReadyHandler = () => {
      scan();
      scheduleMetricPrefetch(0);
    };
    document.addEventListener("DOMContentLoaded", domReadyHandler, { once: true });
  } else {
    scan();
    scheduleMetricPrefetch(0);
  }

  function onManageTabChange(event) {
    const tab = event?.detail?.tab;
    if (!tab || tab === "preview") {
      scheduleViewportRelayout();
    }
  }

  function onWindowResize() {
    scheduleViewportRelayout();
  }

  function onRuntimeQueryReady() {
    markRuntimeQueryReady();
  }

  window.addEventListener("resize", onWindowResize);
  window.visualViewport?.addEventListener("resize", onWindowResize);
  window.visualViewport?.addEventListener("scroll", onWindowResize);
  window.addEventListener("meilang:preview-updated", scan);
  window.addEventListener(RUNTIME_QUERY_READY_EVENT, onRuntimeQueryReady);
  document.addEventListener("mei:manage-tab-change", onManageTabChange);
  document.addEventListener("click", (event) => {
    const btn = event.target.closest("[data-preview-zoom]");
    if (!btn) return;
    const root = btn.closest('[data-mei-frame-viewport="true"]');
    if (!root || !isManagePreviewRoute(root) || !viewportToolbarEnabled(root)) return;
    const mode = String(btn.dataset.previewZoom || "");
    if (mode === "minus") {
      stepManagePreviewZoom(root, -0.1);
      return;
    }
    if (mode === "plus") {
      stepManagePreviewZoom(root, 0.1);
      return;
    }
    setManagePreviewZoom(root, mode);
  });

  boot.scheduleFrameViewportRelayout = scheduleViewportRelayout;
  boot.disposeFrameStage = () => {
    if (metricPrefetchTimer != null) {
      window.clearTimeout(metricPrefetchTimer);
      metricPrefetchTimer = null;
    }
    window.removeEventListener("resize", onWindowResize);
    window.visualViewport?.removeEventListener("resize", onWindowResize);
    window.visualViewport?.removeEventListener("scroll", onWindowResize);
    window.removeEventListener("meilang:preview-updated", scan);
    window.removeEventListener(RUNTIME_QUERY_READY_EVENT, onRuntimeQueryReady);
    document.removeEventListener("mei:manage-tab-change", onManageTabChange);
    if (domReadyHandler) {
      document.removeEventListener("DOMContentLoaded", domReadyHandler);
      domReadyHandler = null;
    }
    observers.forEach((observer) => {
      try {
        observer.disconnect();
      } catch (_) {}
    });
    observers.clear();
    tracked.clear();
    boot.scheduleFrameViewportRelayout = null;
  };


/* ===== frame-stage/epilogue.js ===== */
})();


/* ===== workspace-splitters.js ===== */
(function initWorkspaceSplitters() {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (typeof boot.disposeWorkspaceSplitters === "function") {
    try {
      boot.disposeWorkspaceSplitters();
    } catch (_) {}
    boot.disposeWorkspaceSplitters = null;
  }
  const root = document.getElementById("workspace-root");
  const handles = Array.from(document.querySelectorAll("[data-workspace-splitter]"));
  const toggleButtons = Array.from(document.querySelectorAll("[data-workspace-toggle]"));
  const splitterPx = 8;
  const activateDragDeltaPx = 3;
  const minMain = 320;
  const config = {
    left: {
      cssVar: "--workspace-left-aside",
      storageKey: "mei-lang.workspaceLeftAsidePx",
      collapsedKey: "mei-lang.workspaceLeftAsideCollapsed",
      fallback: 320,
      min: 260,
      axis: "x",
      target: root
    },
    right: {
      cssVar: "--workspace-right-aside",
      storageKey: "mei-lang.workspaceRightAsidePx",
      collapsedKey: "mei-lang.workspaceRightAsideCollapsed",
      fallback: 320,
      min: 280,
      axis: "x",
      target: root
    }
  };
  const activeHandles = handles.filter(function (handle) {
    const side = handle && handle.getAttribute ? handle.getAttribute("data-workspace-splitter") : "";
    return !!config[side];
  });
  const activeSides = Array.from(
    new Set(
      activeHandles
        .map(function (handle) {
          return handle.getAttribute("data-workspace-splitter") || "";
        })
        .concat(
          toggleButtons
            .map(function (button) {
              return button.getAttribute("data-workspace-toggle") || "";
            })
            .filter(function (side) {
              return !!config[side];
            })
        )
    )
  );
  if (!root || !activeHandles.length || !activeSides.length) return;
  const collapsed = { left: false, right: false };
  function toggleButton(side) {
    return toggleButtons.find(function (button) {
      return button.getAttribute("data-workspace-toggle") === side;
    }) || null;
  }
  function syncCollapsedUi() {
    root.dataset.leftCollapsed = collapsed.left ? "true" : "false";
    root.dataset.rightCollapsed = collapsed.right ? "true" : "false";
    ["left", "right"].forEach(function (side) {
      const button = toggleButton(side);
      if (!button) return;
      const isCollapsed = !!collapsed[side];
      button.dataset.collapsed = isCollapsed ? "true" : "false";
      const noun = side === "left" ? "左侧资源栏" : "右侧助手栏";
      const action = isCollapsed ? "展开" : "折叠";
      button.setAttribute("aria-label", action + noun);
      button.setAttribute("title", action + noun);
    });
  }
  function clamp(n, lo, hi) {
    return Math.max(lo, Math.min(hi, n));
  }
  function readPx(side) {
    const meta = config[side];
    if (!meta || !meta.target) return 0;
    const raw = getComputedStyle(meta.target).getPropertyValue(meta.cssVar).trim();
    const m = raw.match(/^(\d+(?:\.\d+)?)px$/);
    if (m) return Math.round(parseFloat(m[1], 10));
    return meta.fallback;
  }
  function writePx(side, px) {
    const meta = config[side];
    if (!meta || !meta.target) return;
    meta.target.style.setProperty(meta.cssVar, px + "px");
  }
  function maxPx(side) {
    const meta = config[side];
    if (!meta || !meta.target) return meta ? meta.fallback : 0;
    const otherSide = side === "left" ? "right" : "left";
    const otherWidth = activeSides.includes(otherSide) ? readPx(otherSide) : 0;
    const rect = root.getBoundingClientRect();
    const splittersTotalPx = activeHandles.length * splitterPx;
    return Math.max(
      meta.min,
      rect.width - otherWidth - splittersTotalPx - minMain
    );
  }
  activeSides.forEach((side) => {
    try {
      const meta = config[side];
      if (!meta.target) return;
      collapsed[side] = localStorage.getItem(meta.collapsedKey) === "1";
      const saved = localStorage.getItem(meta.storageKey);
      let px = meta.fallback;
      if (saved) {
        const parsed = parseInt(saved, 10);
        if (!Number.isNaN(parsed) && parsed >= meta.min) {
          px = parsed;
        }
      }
      if (collapsed[side]) {
        writePx(side, 0);
      } else {
        writePx(side, clamp(px, meta.min, maxPx(side)));
      }
    } catch (_) {}
  });
  syncCollapsedUi();
  let dragging = false;
  let draggingSide = "";
  let activeHandle = null;
  let startCoord = 0;
  let startW = 0;
  let dragActivated = false;
  function applySize(clientCoord) {
    if (!draggingSide) return;
    const meta = config[draggingSide];
    const delta = clientCoord - startCoord;
    const rawNext =
      draggingSide === "left" || draggingSide === "preview"
        ? startW + delta
        : startW - delta;
    const next = clamp(rawNext, meta.min, maxPx(draggingSide));
    writePx(draggingSide, next);
  }
  function onMove(ev) {
    if (!dragging) return;
    const meta = config[draggingSide];
    const point = ev.touches && ev.touches[0] ? ev.touches[0] : ev;
    const coord = meta && meta.axis === "y" ? point.clientY : point.clientX;
    if (!dragActivated && Math.abs(coord - startCoord) >= activateDragDeltaPx) {
      dragActivated = true;
      if (activeHandle) activeHandle.classList.add("splitter-active");
    }
    applySize(coord);
    if (ev.cancelable) ev.preventDefault();
  }
  function onEnd() {
    if (!dragging) return;
    dragging = false;
    if (activeHandle) activeHandle.classList.remove("splitter-active");
    dragActivated = false;
    document.body.style.cursor = "";
    document.body.style.userSelect = "";
    window.removeEventListener("mousemove", onMove);
    window.removeEventListener("mouseup", onEnd);
    window.removeEventListener("touchmove", onMove);
    window.removeEventListener("touchend", onEnd);
    window.removeEventListener("touchcancel", onEnd);
    try {
      const meta = config[draggingSide];
      if (meta) {
        localStorage.setItem(meta.storageKey, String(readPx(draggingSide)));
      }
    } catch (_) {}
    activeHandle = null;
    draggingSide = "";
  }
  function onStart(ev) {
    if (ev.type === "mousedown" && ev.button !== 0) return;
    if (ev.target instanceof Element && ev.target.closest("[data-workspace-toggle]")) return;
    const handle = ev.currentTarget;
    const side = handle && handle.getAttribute ? handle.getAttribute("data-workspace-splitter") : "";
    if (!config[side]) return;
    if (collapsed[side]) return;
    const meta = config[side];
    if (!meta.target) return;
    dragging = true;
    draggingSide = side;
    activeHandle = handle;
    const point = ev.touches && ev.touches[0] ? ev.touches[0] : ev;
    startCoord = meta.axis === "y" ? point.clientY : point.clientX;
    startW = readPx(side);
    dragActivated = false;
    handle.classList.remove("splitter-active");
    document.body.style.cursor = meta.axis === "y" ? "row-resize" : "col-resize";
    document.body.style.userSelect = "none";
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onEnd);
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onEnd);
    window.addEventListener("touchcancel", onEnd);
    ev.preventDefault();
  }
  function toggleSide(side) {
    const meta = config[side];
    if (!meta || !meta.target) return;
    if (collapsed[side]) {
      collapsed[side] = false;
      try {
        localStorage.removeItem(meta.collapsedKey);
      } catch (_) {}
      const saved = localStorage.getItem(meta.storageKey);
      let px = meta.fallback;
      if (saved) {
        const parsed = parseInt(saved, 10);
        if (!Number.isNaN(parsed) && parsed >= meta.min) {
          px = parsed;
        }
      }
      writePx(side, clamp(px, meta.min, maxPx(side)));
    } else {
      const current = readPx(side);
      if (current >= meta.min) {
        try {
          localStorage.setItem(meta.storageKey, String(current));
        } catch (_) {}
      }
      collapsed[side] = true;
      writePx(side, 0);
      try {
        localStorage.setItem(meta.collapsedKey, "1");
      } catch (_) {}
    }
    syncCollapsedUi();
  }
  function onToggleClick(ev) {
    ev.preventDefault();
    ev.stopPropagation();
    const button = ev.currentTarget;
    const side = button && button.getAttribute ? button.getAttribute("data-workspace-toggle") || "" : "";
    if (!side) return;
    toggleSide(side);
  }
  activeHandles.forEach((handle) => {
    handle.addEventListener("mousedown", onStart);
    handle.addEventListener("touchstart", onStart, { passive: false });
  });
  toggleButtons.forEach((button) => {
    button.addEventListener("click", onToggleClick);
  });
  const onResize = function () {
    activeSides.forEach((side) => {
      const meta = config[side];
      if (!meta || !meta.target) return;
      if (collapsed[side]) {
        writePx(side, 0);
      } else {
        writePx(side, clamp(readPx(side), meta.min, maxPx(side)));
      }
    });
    syncCollapsedUi();
  };
  window.addEventListener("resize", onResize);
  boot.disposeWorkspaceSplitters = function () {
    onEnd();
    activeHandles.forEach((handle) => {
      handle.removeEventListener("mousedown", onStart);
      handle.removeEventListener("touchstart", onStart, { passive: false });
    });
    toggleButtons.forEach((button) => {
      button.removeEventListener("click", onToggleClick);
    });
    window.removeEventListener("resize", onResize);
    window.removeEventListener("mousemove", onMove);
    window.removeEventListener("mouseup", onEnd);
    window.removeEventListener("touchmove", onMove);
    window.removeEventListener("touchend", onEnd);
    window.removeEventListener("touchcancel", onEnd);
  };
})();


/* ===== manage-tabs.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});

  const BUILD_VIEW_TABS = [
    "overview",
    "preview",
    "exec",
    "semantic",
    "eval",
    "artifact",
    "provenance",
    "agent",
  ];

  function listTabs() {
    return Array.from(
      document.querySelectorAll("a.manage-view-tab[data-manage-tab]"),
    ).filter((node) => !node.hidden);
  }

  function clearManageTabLoadingOverlay() {
    const main = document.querySelector("#workspace-root main.main");
    if (!main) return;
    main.removeAttribute("aria-busy");
    main.querySelectorAll('[data-mei-manage-nav-loading="true"]').forEach((node) => {
      node.remove();
    });
    const globalOverlay = document.getElementById("mei-spa-loading");
    if (globalOverlay) {
      globalOverlay.classList.remove("is-visible");
    }
  }

  function requestRuntimeAbort(reason, options) {
    const opts = options && typeof options === "object" ? options : {};
    try {
      window.dispatchEvent(
        new CustomEvent("mei:abort-runtime-queries", {
          detail: {
            reason: String(reason || "").trim(),
            clearCaches: opts.clearCaches,
          },
        }),
      );
    } catch (_) {}
  }

  function normalizeTab(raw) {
    const value = String(raw || "").trim().toLowerCase();
    if (BUILD_VIEW_TABS.includes(value)) return value;
    if (value === "source" || value === "diagnostics" || value === "diff") {
      return "overview";
    }
    return "";
  }

  function resolveRenderableTab(tab) {
    const active = normalizeTab(tab);
    if (active && BUILD_VIEW_TABS.includes(active)) return active;
    const shell = document.querySelector("[data-build-tab]");
    const fromShell = normalizeTab(shell && shell.getAttribute("data-build-tab"));
    if (fromShell) return fromShell;
    if (document.querySelector('[data-manage-tab-panel="preview"]')) return "preview";
    return "overview";
  }

  function getPanels() {
    const panels = {};
    document.querySelectorAll("[data-manage-tab-panel]").forEach((node) => {
      const id = normalizeTab(node.getAttribute("data-manage-tab-panel"));
      if (id) panels[id] = node;
    });
    return panels;
  }

  function tabFromUrl() {
    try {
      const url = new URL(window.location.href);
      return resolveRenderableTab(url.searchParams.get("tab"));
    } catch (_) {
      return resolveRenderableTab("");
    }
  }

  function panelVisibility(tab) {
    const active = resolveRenderableTab(tab);
    const panels = getPanels();
    BUILD_VIEW_TABS.forEach((slug) => {
      if (panels[slug]) {
        panels[slug].hidden = slug !== active;
      }
    });
  }

  function tabVisual(tab) {
    const active = resolveRenderableTab(tab);
    listTabs().forEach((node) => {
      const nodeTab = normalizeTab(node.getAttribute("data-manage-tab"));
      const isActive = nodeTab === active;
      node.classList.toggle("is-active", isActive);
      node.setAttribute("aria-selected", isActive ? "true" : "false");
      if (isActive) {
        node.setAttribute("aria-current", "page");
      } else {
        node.removeAttribute("aria-current");
      }
    });
    const shell = document.querySelector("[data-build-tab]");
    if (shell) {
      shell.setAttribute("data-build-tab", active);
    }
  }

  function tabLink(tab) {
    const active = resolveRenderableTab(tab);
    const visible = listTabs();
    return (
      visible.find((node) => normalizeTab(node.getAttribute("data-manage-tab")) === active) ||
      visible[0]
    );
  }

  function updateUrl(nextTab) {
    const link = tabLink(nextTab);
    if (!link || !link.href) return;
    const nextHref = new URL(link.href, window.location.href).toString();
    const currentHref = window.location.href;
    if (nextHref === currentHref) return;
    window.history.replaceState(window.history.state, "", nextHref);
  }

  function emitTabChange(nextTab) {
    document.dispatchEvent(
      new CustomEvent("mei:manage-tab-change", {
        detail: { tab: resolveRenderableTab(nextTab) },
      }),
    );
  }

  function refreshBuildPanelForTab(tab) {
    const active = resolveRenderableTab(tab);
    if (typeof globalThis.__meiBuildCopyContextRefresh === "function") {
      globalThis.__meiBuildCopyContextRefresh(active);
    }
  }

  function installManageTabs() {
    if (typeof boot.disposeManageTabs === "function") {
      try {
        boot.disposeManageTabs();
      } catch (_) {}
      boot.disposeManageTabs = null;
    }

    if (!listTabs().length) return;

    let currentTab = tabFromUrl();

    function switchManageTab(nextTab, options) {
      const opts = options || {};
      const active = resolveRenderableTab(nextTab);
      currentTab = active;
      clearManageTabLoadingOverlay();
      tabVisual(active);
      panelVisibility(active);
      if (opts.updateUrl !== false) {
        updateUrl(active);
      }
      if (opts.emit !== false) {
        emitTabChange(active);
      }
      if (active !== "preview") {
        requestRuntimeAbort(`manage_tab:${active}`, { clearCaches: false });
      }
      if (active === "preview") {
        requestAnimationFrame(() => {
          if (typeof boot.scheduleFrameViewportRelayout === "function") {
            try {
              boot.scheduleFrameViewportRelayout();
            } catch (_) {}
          }
          requestAnimationFrame(() => {
            window.dispatchEvent(
              new CustomEvent("meilang:preview-updated", {
                detail: { scope: "page", resetRuntimeQueryCache: false },
              }),
            );
          });
        });
      }
      refreshBuildPanelForTab(active);
      return active;
    }

    const onClick = (event) => {
      if (event.defaultPrevented) return;
      if (event.button !== 0) return;
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const target =
        event.target instanceof Element
          ? event.target.closest("a.manage-view-tab[data-manage-tab]")
          : null;
      if (!target) return;
      if (target.hidden) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      switchManageTab(target.getAttribute("data-manage-tab"), {
        updateUrl: true,
        emit: true,
      });
    };

    document.addEventListener("click", onClick, true);

    boot.switchManageTab = function (tab) {
      return switchManageTab(tab, { updateUrl: true, emit: true });
    };

    boot.disposeManageTabs = function () {
      document.removeEventListener("click", onClick, true);
      if (boot.switchManageTab) {
        boot.switchManageTab = null;
      }
      boot.disposeManageTabs = null;
    };

    switchManageTab(currentTab, { updateUrl: false, emit: false });
    refreshBuildPanelForTab(currentTab);
  }

  boot.installManageTabs = installManageTabs;
  installManageTabs();
})();


/* ===== build-copy-context.js ===== */
/**
 * Build view: copy Markdown agent context + load previews.
 */
(function (global) {
  "use strict";

  async function copyText(value) {
    const text = String(value || "");
    if (!text) return false;
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text);
        return true;
      }
    } catch (_) {}
    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.setAttribute("readonly", "");
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      return ok;
    } catch (_) {
      return false;
    }
  }

  function copyButtonLabel(btn, intent) {
    if (btn.id === "build-copy-agent-context-top") {
      return "复制 Agent 上下文";
    }
    return intent === "full" ? "复制 Agent 上下文" : "复制 Markdown 简报";
  }

  async function handleCopyClick(btn) {
    const appId = btn.getAttribute("data-app-path");
    const node = btn.getAttribute("data-node");
    const tab =
      btn.getAttribute("data-tab") ||
      document.querySelector(".shell[data-build-node]")?.getAttribute("data-build-tab") ||
      "overview";
    const intent = btn.getAttribute("data-intent") || "lock_node";
    const defaultLabel = copyButtonLabel(btn, intent);
    if (!appId || !node) {
      console.warn("build copy: missing app_id or node on button", btn);
      return;
    }
    const prevLabel = btn.textContent;
    btn.disabled = true;
    try {
      const params = {
        app_id: appId,
        node,
        tab,
        intent,
        include_readiness: "1",
      };
      if (intent === "full") {
        params.include_graph = "semantic,eval,mcg,mrg";
      }
      const md = await fetchMarkdown(params);
      const ok = await copyText(md);
      btn.textContent = ok ? "已复制" : "复制失败";
      setTimeout(() => {
        btn.textContent = prevLabel || defaultLabel;
        btn.disabled = false;
      }, 1500);
    } catch (err) {
      console.error("build copy failed", err);
      btn.textContent = "复制失败";
      setTimeout(() => {
        btn.textContent = prevLabel || defaultLabel;
        btn.disabled = false;
      }, 1500);
    }
  }

  async function fetchMarkdown(params) {
    const qs = new URLSearchParams(params);
    const res = await fetch("/api/build/context/export?" + qs.toString());
    if (!res.ok) {
      throw new Error("export failed: " + res.status + " " + (await res.text()));
    }
    return res.text();
  }

  function shellContext() {
    const shell = document.querySelector("[data-build-node]");
    if (!shell) return null;
    return {
      appPath: shell.getAttribute("data-app-path") || "",
      node: shell.getAttribute("data-build-node") || "",
      tab: shell.getAttribute("data-build-tab") || "overview",
    };
  }

  function installCopyDelegation() {
    if (document.__buildCopyDelegationBound) return;
    document.__buildCopyDelegationBound = true;
    document.addEventListener("click", (event) => {
      const provBtn = event.target.closest(".build-copy-provenance[data-copy-text]");
      if (provBtn) {
        event.preventDefault();
        void copyText(provBtn.getAttribute("data-copy-text") || "");
        return;
      }
      const btn = event.target.closest("[data-app-path][data-node][data-intent]");
      if (!btn) return;
      event.preventDefault();
      void handleCopyClick(btn);
    });
  }

  async function refreshAgentPreview() {
    const pre = document.getElementById("build-agent-context-preview");
    const ctx = shellContext();
    if (!pre || !ctx || !ctx.appPath || !ctx.node) return;
    try {
      pre.textContent = "加载中…";
      pre.textContent = await fetchMarkdown({
        app_id: ctx.appPath,
        node: ctx.node,
        tab: "agent",
        intent: "full",
        include_graph: "semantic,eval,mcg,mrg",
        include_readiness: "1",
      });
    } catch (err) {
      pre.textContent = String(err);
    }
  }

  async function refreshGraphPanels(kind) {
    const ctx = shellContext();
    if (!ctx || !ctx.appPath || !ctx.node) return;
    const kinds = kind ? [kind] : ["semantic", "eval"];
    for (const graphKind of kinds) {
      const el = document.querySelector(
        '.build-graph-markdown[data-graph-kind="' + graphKind + '"]',
      );
      if (!el) continue;
      try {
        el.textContent = "加载图摘要…";
        el.textContent = await fetchMarkdown({
          app_id: ctx.appPath,
          node: ctx.node,
          tab: graphKind,
          intent: "debug_eval",
          include_graph: graphKind,
        });
      } catch (err) {
        el.textContent = String(err);
      }
    }
  }

  async function refreshOverviewGate() {
    const gateHost = document.getElementById("build-overview-gate");
    if (!gateHost) return;
    try {
      const res = await fetch("/api/host/readiness");
      if (!res.ok) {
        gateHost.textContent = "Gate 状态暂不可用";
        return;
      }
      const readiness = await res.json();
      const ctx = shellContext();
      const app = (readiness.apps || []).find((entry) => entry.app_id === (ctx && ctx.appPath));
      gateHost.textContent = [
        readiness.phase ? "host_phase=" + readiness.phase : "",
        app ? "app_phase=" + app.phase : "",
        readiness.access_ready != null ? "access_ready=" + readiness.access_ready : "",
      ]
        .filter(Boolean)
        .join(" · ") || "Gate 状态已加载";
    } catch (_) {
      gateHost.textContent = "";
    }
  }

  async function refreshArtifactPanels() {
    const ctx = shellContext();
    if (!ctx || !ctx.appPath || !ctx.node) return;

    const gateHost = document.getElementById("build-overview-gate");
    const artifactSummary = document.getElementById("build-artifact-summary");
    try {
      const md = await fetchMarkdown({
        app_id: ctx.appPath,
        node: ctx.node,
        tab: "artifact",
        intent: "debug_artifact",
        include_readiness: "1",
      });
      if (artifactSummary) {
        artifactSummary.textContent = md.split("### 建议 Agent 任务")[0].trim();
      }
      if (gateHost) {
        const gateLine = md
          .split("\n")
          .find((line) => line.includes("**Gate**") || line.includes("Gate"));
        gateHost.textContent = gateLine ? gateLine.replace(/^-\s*/, "") : "Gate 状态已加载";
      }
    } catch (err) {
      if (artifactSummary) artifactSummary.textContent = String(err);
    }

    try {
      const res = await fetch("/api/host/readiness");
      if (!res.ok || !artifactSummary) return;
      const readiness = await res.json();
      const app = (readiness.apps || []).find((entry) => entry.app_id === ctx.appPath);
      const cacheBits = [
        readiness.phase ? "host_phase=" + readiness.phase : "",
        app ? "app_phase=" + app.phase : "",
        readiness.access_ready != null ? "access_ready=" + readiness.access_ready : "",
      ].filter(Boolean);
      if (cacheBits.length) {
        artifactSummary.textContent += "\n\n" + cacheBits.join(" · ");
      }
    } catch (_) {}
  }

  function refreshBuildPanelForTab(tab) {
    const slug = String(tab || "").trim().toLowerCase();
    if (slug === "agent") {
      refreshAgentPreview();
      return;
    }
    if (slug === "semantic" || slug === "eval") {
      refreshGraphPanels(slug);
      return;
    }
    if (slug === "artifact") {
      refreshArtifactPanels();
      return;
    }
    if (slug === "overview") {
      refreshOverviewGate();
    }
  }

  function initBuildCopyContext() {
    installCopyDelegation();
    const ctx = shellContext();
    refreshBuildPanelForTab(ctx ? ctx.tab : "overview");
  }

  global.__meiBuildCopyContextInit = initBuildCopyContext;
  global.__meiBuildCopyContextRefresh = refreshBuildPanelForTab;

  document.addEventListener("mei:manage-tab-change", (event) => {
    const tab = event && event.detail ? event.detail.tab : "";
    refreshBuildPanelForTab(tab);
  });
})(typeof window !== "undefined" ? window : globalThis);


/* ===== build-scoped-rebuild.js ===== */
/**
 * Build view scoped AOT rebuild (POST /api/host/build).
 */
(function (global) {
  "use strict";

  function shellCompileContext() {
    const shell = document.querySelector(".shell[data-compile-target], .shell[data-app-path]");
    if (!shell) return null;
    return {
      appId: String(
        shell.getAttribute("data-app-path") ||
          shell.getAttribute("data-app-id") ||
          "",
      ).trim(),
      sceneId: String(shell.getAttribute("data-compile-scene") || "").trim(),
      targetFile: String(shell.getAttribute("data-compile-target") || "").trim(),
    };
  }

  async function runScopedRebuild(ctx, trigger) {
    const appId = String((ctx && ctx.appId) || "").trim();
    if (!appId) {
      throw new Error("缺少 appId，无法重建 scope");
    }
    const body = { appId, mode: "build" };
    const sceneId = String((ctx && ctx.sceneId) || "").trim();
    const targetFile = String((ctx && ctx.targetFile) || "").trim();
    if (sceneId) body.sceneId = sceneId;
    if (targetFile) body.targetFile = targetFile;

    if (trigger) {
      trigger.disabled = true;
      trigger.dataset.meiRebuildPrev = trigger.textContent || "";
      trigger.textContent = "重建中…";
    }

    try {
      const res = await fetch("/api/host/build", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(text || res.statusText || "scoped rebuild failed");
      }
      global.dispatchEvent(new CustomEvent("meilang:scoped-rebuild-complete"));
      global.location.reload();
    } finally {
      if (trigger) {
        trigger.disabled = false;
        if (trigger.dataset.meiRebuildPrev) {
          trigger.textContent = trigger.dataset.meiRebuildPrev;
        }
      }
    }
  }

  function bindScopedRebuildControls(root) {
    const scope = root || document;
    scope.querySelectorAll("[data-mei-scoped-rebuild]").forEach((btn) => {
      if (btn.__meiScopedRebuildBound) return;
      btn.__meiScopedRebuildBound = true;
      btn.addEventListener("click", () => {
        const ctx = {
          appId: btn.getAttribute("data-app-id") || shellCompileContext()?.appId,
          sceneId: btn.getAttribute("data-scene-id") || shellCompileContext()?.sceneId,
          targetFile:
            btn.getAttribute("data-target-file") || shellCompileContext()?.targetFile,
        };
        runScopedRebuild(ctx, btn).catch((err) => {
          global.alert(String(err && err.message ? err.message : err));
        });
      });
    });
  }

  function bindOverviewGate() {
    const gateHost = document.getElementById("build-overview-gate");
    if (!gateHost || gateHost.querySelector("[data-mei-scoped-rebuild]")) return;
    const ctx = shellCompileContext();
    if (!ctx || !ctx.appId) return;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "mei-btn mei-btn--sm mt-2";
    btn.setAttribute("data-mei-scoped-rebuild", "1");
    btn.setAttribute("data-app-id", ctx.appId);
    if (ctx.sceneId) btn.setAttribute("data-scene-id", ctx.sceneId);
    if (ctx.targetFile) btn.setAttribute("data-target-file", ctx.targetFile);
    btn.textContent = "重建此 scope";
    gateHost.appendChild(btn);
    bindScopedRebuildControls(gateHost);
  }

  function initBuildScopedRebuild() {
    bindScopedRebuildControls(document);
    bindOverviewGate();
  }

  global.MeiBuildScopedRebuild = {
    runScopedRebuild,
    initBuildScopedRebuild,
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initBuildScopedRebuild);
  } else {
    initBuildScopedRebuild();
  }

  global.addEventListener("meilang:preview-updated", initBuildScopedRebuild);
})(typeof window !== "undefined" ? window : globalThis);


/* ===== build-tree-persist.js ===== */
/**
 * Build view: persist left-tree open state + click/double-click expand shortcuts.
 */
(function (global) {
  "use strict";

  const STORAGE_KEY = "mei-build-tree-open";
  const SCROLL_KEY = "mei-build-tree-scroll";
  const MODE_KEY = "mei-build-tree-mode";
  const CLICK_DELAY_MS = 280;

  function isBuildRoute() {
    return /^\/apps\/(?:build|manage)\//.test(String(global.location.pathname || ""));
  }

  function sidebarScrollEl(root) {
    return root?.closest?.(".sidebar-scroll") || null;
  }

  function loadOpenSet() {
    try {
      const raw = global.sessionStorage.getItem(STORAGE_KEY);
      if (!raw) return new Set();
      const parsed = JSON.parse(raw);
      return new Set(Array.isArray(parsed) ? parsed : []);
    } catch {
      return new Set();
    }
  }

  function saveOpenSet(set) {
    try {
      global.sessionStorage.setItem(STORAGE_KEY, JSON.stringify([...set]));
    } catch {
      /* ignore quota */
    }
  }

  function captureScroll(root) {
    const scroll = sidebarScrollEl(root);
    if (!scroll) return;
    try {
      global.sessionStorage.setItem(SCROLL_KEY, String(scroll.scrollTop || 0));
    } catch {
      /* ignore */
    }
  }

  function restoreScroll(root, explicitTop) {
    const scroll = sidebarScrollEl(root);
    if (!scroll) return;
    try {
      if (typeof explicitTop === "number" && Number.isFinite(explicitTop)) {
        scroll.scrollTop = explicitTop;
        return;
      }
      const raw = global.sessionStorage.getItem(SCROLL_KEY);
      if (raw == null) return;
      const top = Number(raw);
      if (Number.isFinite(top)) {
        scroll.scrollTop = top;
      }
    } catch {
      /* ignore */
    }
  }

  function pinSidebarScroll(root, mutate) {
    const scroll = sidebarScrollEl(root);
    const pinnedTop = scroll?.scrollTop ?? null;
    mutate();
    if (!scroll || pinnedTop == null) return;
    const apply = () => {
      scroll.scrollTop = pinnedTop;
    };
    requestAnimationFrame(() => {
      apply();
      requestAnimationFrame(apply);
    });
  }

  function branchId(details) {
    return String(details?.getAttribute("data-build-tree-branch") || "").trim();
  }

  function branchDetailsFromSummary(summary) {
    if (!(summary instanceof HTMLElement)) return null;
    const details = summary.parentElement;
    if (!(details instanceof HTMLDetailsElement)) return null;
    if (!details.matches("details.build-tree-details[data-build-tree-branch]")) return null;
    return details;
  }

  function isNavigationClick(event) {
    const target = event.target;
    if (!(target instanceof Element)) return false;
    return Boolean(target.closest("a[href]"));
  }

  function nestedBranchDetails(details) {
    return Array.from(
      details.querySelectorAll(":scope > ul .build-tree-details[data-build-tree-branch]"),
    ).filter((node) => node instanceof HTMLDetailsElement);
  }

  function allDescendantBranchDetails(details) {
    return Array.from(
      details.querySelectorAll(".build-tree-details[data-build-tree-branch]"),
    ).filter((node) => node instanceof HTMLDetailsElement);
  }

  function syncOpenSetForDetails(details, openSet, open) {
    const id = branchId(details);
    if (!id) return;
    if (open) {
      openSet.add(id);
    } else {
      openSet.delete(id);
    }
  }

  function syncOpenSetForSubtree(details, openSet, open) {
    syncOpenSetForDetails(details, openSet, open);
    for (const nested of allDescendantBranchDetails(details)) {
      syncOpenSetForDetails(nested, openSet, open);
    }
  }

  function expandOneLevel(details, openSet) {
    details.open = true;
    syncOpenSetForDetails(details, openSet, true);
  }

  function expandAllDescendants(details, openSet) {
    details.open = true;
    for (const nested of allDescendantBranchDetails(details)) {
      nested.open = true;
    }
    syncOpenSetForSubtree(details, openSet, true);
  }

  function collapseAllDescendants(details, openSet) {
    for (const nested of allDescendantBranchDetails(details)) {
      nested.open = false;
    }
    details.open = false;
    syncOpenSetForSubtree(details, openSet, false);
  }

  function bindTreeExpandBehavior(root) {
    if (!root || root.__buildTreeExpandBound) return;
    root.__buildTreeExpandBound = true;
    const clickTimers = new WeakMap();

    root.addEventListener(
      "click",
      (event) => {
        if (isNavigationClick(event)) return;
        const summary = event.target.closest("summary.build-tree-summary");
        const details = branchDetailsFromSummary(summary);
        if (!details) return;
        event.preventDefault();

        const existing = clickTimers.get(details);
        if (existing) {
          global.clearTimeout(existing);
          clickTimers.delete(details);
          const openSet = loadOpenSet();
          expandAllDescendants(details, openSet);
          saveOpenSet(openSet);
          return;
        }

        const timer = global.setTimeout(() => {
          clickTimers.delete(details);
          const openSet = loadOpenSet();
          if (details.open) {
            collapseAllDescendants(details, openSet);
          } else {
            expandOneLevel(details, openSet);
            for (const nested of nestedBranchDetails(details)) {
              nested.open = false;
              syncOpenSetForDetails(nested, openSet, false);
            }
          }
          saveOpenSet(openSet);
        }, CLICK_DELAY_MS);
        clickTimers.set(details, timer);
      },
      true,
    );
  }

  function restoreOpenState(root) {
    const openSet = loadOpenSet();
    root.querySelectorAll("details.build-tree-details[data-build-tree-branch]").forEach((details) => {
      const id = branchId(details);
      if (id && openSet.has(id)) {
        details.open = true;
      }
    });
  }

  function ensureActivePathOpen(root) {
    const active =
      root.querySelector(".build-tree-link--active") ||
      root.querySelector(".build-tree-summary--active");
    if (!active) return;
    const openSet = loadOpenSet();
    let node = active.closest("li.build-tree-node");
    while (node) {
      const details = node.querySelector(":scope > details.build-tree-details[data-build-tree-branch]");
      if (details) {
        const id = branchId(details);
        if (id) {
          details.open = true;
          openSet.add(id);
        }
      }
      const parentList = node.parentElement?.closest("li.build-tree-node");
      node = parentList || null;
    }
    saveOpenSet(openSet);
  }

  function bindTreePersist(root) {
    if (!root || root.__buildTreePersistBound) return;
    root.__buildTreePersistBound = true;
    restoreOpenState(root);
    ensureActivePathOpen(root);
    restoreScroll(root);
    bindTreeExpandBehavior(root);
    root.addEventListener(
      "toggle",
      (event) => {
        const details = event.target;
        if (!details?.matches?.("details.build-tree-details[data-build-tree-branch]")) return;
        const id = branchId(details);
        if (!id) return;
        const openSet = loadOpenSet();
        if (details.open) {
          openSet.add(id);
        } else {
          openSet.delete(id);
        }
        saveOpenSet(openSet);
      },
      true,
    );
  }

  function currentManageTab() {
    try {
      const url = new URL(global.location.href);
      const tab = String(url.searchParams.get("tab") || "").trim().toLowerCase();
      if (tab) return tab;
    } catch (_) {}
    const shell = document.querySelector(".shell[data-build-tab]");
    return String(shell?.getAttribute("data-build-tab") || "overview").trim().toLowerCase();
  }

  function treeLinkTab(rawUrl, linkEl) {
    const nav = global.MeiBuildNavigation;
    if (nav && typeof nav.treeLinkTab === "function") {
      return nav.treeLinkTab(rawUrl, linkEl);
    }
    if (nav && typeof nav.inferPreviewTabFromNodeId === "function") {
      const nodeId = String(linkEl?.getAttribute?.("data-build-node") || "").trim();
      const inferred = nav.inferPreviewTabFromNodeId(nodeId);
      if (inferred) return inferred;
    }
    return currentManageTab();
  }

  function syncTreeLinkTabs(root) {
    root.querySelectorAll("a.build-tree-link, a.build-tree-label--link").forEach((link) => {
      try {
        const url = new URL(link.href, global.location.href);
        const tab = treeLinkTab(url.toString(), link);
        url.searchParams.set("tab", tab);
        link.href = url.toString();
      } catch (_) {}
    });
  }

  function bindTreeTabPersist(root) {
    if (root.__buildTreeTabBound) return;
    root.__buildTreeTabBound = true;
    root.addEventListener(
      "click",
      (event) => {
        const link = event.target.closest("a.build-tree-link, a.build-tree-label--link");
        if (!link || !link.href) return;
        captureScroll(root);
        try {
          const url = new URL(link.href, global.location.href);
          url.searchParams.set("tab", treeLinkTab(url.toString(), link));
          url.searchParams.delete("focus");
          link.href = url.toString();
        } catch (_) {}
        const nodeId = String(link.getAttribute("data-build-node") || "").trim();
        const structureNode = /^(?:ui-scope|scene-panel|scene-block):/i.test(nodeId);
        const nav = global.MeiBuildNavigation;
        if (!structureNode || typeof nav?.tryNavigateBuild !== "function") return;
        event.preventDefault();
        event.stopImmediatePropagation();
        void nav
          .tryNavigateBuild(global.location.href, link.href, { linkEl: link })
          .then((result) => {
            if (result?.handled) {
              if (typeof nav.noteUrl === "function") nav.noteUrl(link.href);
              return;
            }
            if (typeof global.__meiLangBoot?.navigateInternal === "function") {
              void global.__meiLangBoot.navigateInternal(link.href, false, { skipBuildNav: true });
            }
          })
          .catch(() => {
            if (typeof global.__meiLangBoot?.navigateInternal === "function") {
              void global.__meiLangBoot.navigateInternal(link.href, false, { skipBuildNav: true });
            }
          });
      },
      true,
    );
    root.addEventListener(
      "mousedown",
      (event) => {
        const link = event.target.closest("a.build-tree-link, a.build-tree-label--link");
        if (!link) return;
        // Prevent focus scroll-into-view jitter when SPA handles navigation.
        event.preventDefault();
      },
      true,
    );
  }

  function loadTreeMode() {
    try {
      const raw = String(global.sessionStorage.getItem(MODE_KEY) || "").trim().toLowerCase();
      return raw === "compile" ? "compile" : "structure";
    } catch {
      return "structure";
    }
  }

  function saveTreeMode(mode) {
    try {
      global.sessionStorage.setItem(MODE_KEY, mode);
    } catch {
      /* ignore */
    }
  }

  function applyTreeMode(root, mode) {
    const shell = root.closest(".build-tree-shell") || root.parentElement;
    const activeMode = mode === "compile" ? "compile" : "structure";
    root.setAttribute("data-build-tree-mode-active", activeMode);
    shell?.querySelectorAll(".build-tree-mode-btn").forEach((btn) => {
      const btnMode = String(btn.getAttribute("data-build-tree-mode") || "");
      btn.classList.toggle("is-active", btnMode === activeMode);
    });
    root.querySelectorAll("[data-build-tree-root-group]").forEach((details) => {
      const group = String(details.getAttribute("data-build-tree-root-group") || "");
      const branch = details.closest(".build-tree-node");
      if (!(branch instanceof HTMLElement)) return;
      if (activeMode === "structure") {
        branch.hidden = group !== "ui_structure";
      } else {
        branch.hidden = group === "ui_structure";
      }
    });
  }

  function bindTreeModeToggle(root) {
    const shell = root.closest(".build-tree-shell");
    if (!shell || shell.__buildTreeModeBound) return;
    shell.__buildTreeModeBound = true;
    shell.querySelectorAll(".build-tree-mode-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const mode = String(btn.getAttribute("data-build-tree-mode") || "structure");
        saveTreeMode(mode);
        applyTreeMode(root, mode);
      });
    });
  }

  function refresh(options) {
    if (!isBuildRoute()) return;
    const root = document.querySelector(".build-reachability-tree");
    if (!root) return;
    bindTreePersist(root);
    bindTreeTabPersist(root);
    bindTreeModeToggle(root);
    applyTreeMode(root, loadTreeMode());
    syncTreeLinkTabs(root);
    pinSidebarScroll(root, () => {
      syncTreeActiveFromNode(root);
    });
    if (options && options.restorePersistedScroll) {
      restoreScroll(root);
    }
  }

  function syncTreeActiveFromNode(root) {
    let nodeId = "";
    try {
      nodeId = String(new URL(global.location.href).searchParams.get("node") || "").trim();
    } catch (_) {}
    if (!nodeId) {
      nodeId = String(document.querySelector(".shell[data-build-node]")?.getAttribute("data-build-node") || "").trim();
    }
    root.querySelectorAll(".build-tree-link--active").forEach((el) => {
      el.classList.remove("build-tree-link--active");
    });
    root.querySelectorAll(".build-tree-summary--active").forEach((el) => {
      el.classList.remove("build-tree-summary--active");
    });
    if (!nodeId) return;
    const escaped =
      typeof global.CSS !== "undefined" && typeof global.CSS.escape === "function"
        ? global.CSS.escape(nodeId)
        : nodeId.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
    const activeLink = root.querySelector(`a[data-build-node="${escaped}"]`);
    if (!(activeLink instanceof HTMLElement)) return;
    activeLink.classList.add("build-tree-link--active");
    const summary = activeLink.closest("summary");
    if (summary instanceof HTMLElement) {
      summary.classList.add("build-tree-summary--active");
    }
    ensureActivePathOpen(root);
  }

  function bind() {
    if (!isBuildRoute()) return;
    refresh({ restorePersistedScroll: true });
    global.addEventListener("popstate", refresh);
    global.addEventListener("mei:manage-tab-change", refresh);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", bind);
  } else {
    bind();
  }

  global.MeiBuildTreePersist = { refresh, captureScroll };
})(window);


/* ===== runtime-refresh.js ===== */
(function initRuntimeObservatoryRefresh() {
  const shell = document.querySelector("[data-runtime-node]");
  if (!shell) return;
  const appPath = shell.getAttribute("data-app-path") || "";
  const refreshBtn = document.getElementById("runtime-refresh-btn");
  let timer = null;

  function formatBytes(bytes) {
    const value = Number(bytes) || 0;
    if (value < 1024) return `${value} B`;
    if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KiB`;
    if (value < 1024 * 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MiB`;
    return `${(value / 1024 / 1024 / 1024).toFixed(2)} GiB`;
  }

  function msLabel(value) {
    return value == null ? "-" : `${value}ms`;
  }

  function gateCount(host, sweep) {
    return host == null ? String(sweep || 0) : String(host);
  }

  function metricRow(label, value) {
    return `<div class="flex justify-between gap-2"><dt class="mei-text-muted">${label}</dt><dd>${value}</dd></div>`;
  }

  function renderLayerMetrics(payload) {
    const host = payload.host || {};
    const prebuild = payload.prebuild || {};
    const diag = payload.diagnostics || {};
    const disk = diag.disk || {};
    const evalStats = diag.eval || {};
    const mcg = diag.mcg || {};
    const mrg = diag.mrg || {};
    const cache = diag.cache || {};
    const build = diag.build || {};
    const sweep = diag.scopeGateSweep || {};
    const contentStore = diag.contentStore || {};
    return `
      <section class="rounded-lg border border-white/10 bg-black/10 p-3">
        <h3 class="mb-2 mei-font-2 mei-text-primary">宿主 / 构建</h3>
        <dl class="grid gap-1 mei-font-1">
          ${metricRow("宿主 phase", host.phase || "-")}
          ${metricRow("App phase", host.appPhase || "-")}
          ${metricRow("access_ready", String(Boolean(host.accessReady)))}
          ${metricRow("wall", msLabel(prebuild.totalWallMs))}
          ${metricRow("compile", msLabel(prebuild.compileScopesMs))}
          ${metricRow("peak RSS", prebuild.peakRssBytes == null ? "-" : formatBytes(prebuild.peakRssBytes))}
          ${metricRow("current RSS", prebuild.currentRssBytes == null ? "-" : formatBytes(prebuild.currentRssBytes))}
        </dl>
      </section>
      <section class="rounded-lg border border-white/10 bg-black/10 p-3">
        <h3 class="mb-2 mei-font-2 mei-text-primary">L1 · Cache</h3>
        <dl class="grid gap-1 mei-font-1">
          ${metricRow("dedup", String(Boolean(cache.graphRegistryDedup)))}
          ${metricRow("compile_index", `${build.compileIndexEntries || 0} / ${build.compileIndexHits || 0} hit`)}
          ${metricRow("eval files", String(evalStats.evalTotalFiles || 0))}
          ${metricRow("eval bytes", formatBytes(evalStats.evalTotalBytes || 0))}
          ${metricRow("CAS store", formatBytes(contentStore.bytes || 0))}
        </dl>
      </section>
      <section class="rounded-lg border border-white/10 bg-black/10 p-3">
        <h3 class="mb-2 mei-font-2 mei-text-primary">L2 · Navigation</h3>
        <dl class="grid gap-1 mei-font-1">
          ${metricRow("L2 miss", gateCount(host.gateL2Miss, sweep.l2Miss))}
          ${metricRow("nav nodes", String(mrg.navigationNodeCount || 0))}
          ${metricRow("nav dup", String(mrg.navigationDuplicateKeys || 0))}
        </dl>
      </section>
      <section class="rounded-lg border border-white/10 bg-black/10 p-3">
        <h3 class="mb-2 mei-font-2 mei-text-primary">L3 · Assembly</h3>
        <dl class="grid gap-1 mei-font-1">
          ${metricRow("MCG nodes", String(mcg.nodeCount || 0))}
          ${metricRow("scene_payload", String(mcg.scenePayloadNodes || 0))}
          ${metricRow("L3 fail", gateCount(host.gateL3Fail, sweep.l3Fail))}
          ${metricRow("payload disk", formatBytes(disk.scenePayloadBytes || 0))}
        </dl>
      </section>
      <section class="rounded-lg border border-white/10 bg-black/10 p-3">
        <h3 class="mb-2 mei-font-2 mei-text-primary">L4 · Materialization</h3>
        <dl class="grid gap-1 mei-font-1">
          ${metricRow("slots", `${mrg.readySlots || 0} ready / ${mrg.failedSlots || 0} fail`)}
          ${metricRow("stale", `${mrg.staleSlots || 0} (${Math.round((mrg.staleRatio || 0) * 100)}%)`)}
          ${metricRow("L4 stale", gateCount(host.gateL4Stale, sweep.l4Stale))}
          ${metricRow("data snapshots", formatBytes(disk.dataSnapshotsBytes || 0))}
        </dl>
      </section>
      <section class="rounded-lg border border-white/10 bg-black/10 p-3">
        <h3 class="mb-2 mei-font-2 mei-text-primary">磁盘</h3>
        <dl class="grid gap-1 mei-font-1">
          ${metricRow("app_root", formatBytes(disk.appRootBytes || 0))}
          ${metricRow("compiled_app", `${disk.compiledAppFileCount || 0} / ${formatBytes(disk.compiledAppBytes || 0)}`)}
          ${metricRow("graph", formatBytes(disk.graphBytes || 0))}
          ${metricRow("prebuild", formatBytes(disk.prebuildBytes || 0))}
        </dl>
      </section>`;
  }

  function applySnapshot(payload) {
    if (!payload || typeof payload !== "object") return;
    const rootsScript = document.getElementById("mei-runtime-observability-tree");
    if (rootsScript && Array.isArray(payload.roots)) {
      rootsScript.textContent = JSON.stringify(payload.roots);
    }
    const snapshotScript = document.getElementById("mei-runtime-observability-snapshot");
    if (snapshotScript) {
      snapshotScript.textContent = JSON.stringify(payload);
    }
    const metricsHost = document.getElementById("runtime-layer-metrics");
    if (metricsHost) {
      metricsHost.innerHTML = renderLayerMetrics(payload);
    }
    const loading = document.getElementById("runtime-layer-metrics-loading");
    if (loading) loading.remove();
    const detail = document.getElementById("runtime-detail-json");
    if (detail) {
      detail.textContent = JSON.stringify(payload, null, 2);
    }
  }

  async function refreshSnapshot() {
    if (!appPath) return;
    const url = `/api/runtime/snapshot?appId=${encodeURIComponent(appPath)}`;
    try {
      const response = await fetch(url, {
        headers: { Accept: "application/json" },
        credentials: "same-origin",
      });
      if (!response.ok) return;
      const payload = await response.json();
      applySnapshot(payload);
    } catch (_error) {
      /* ignore transient refresh errors */
    }
  }

  if (refreshBtn) {
    refreshBtn.addEventListener("click", () => {
      refreshSnapshot();
    });
  }

  refreshSnapshot();
  timer = window.setInterval(refreshSnapshot, 5000);
  window.addEventListener(
    "pagehide",
    () => {
      if (timer) window.clearInterval(timer);
    },
    { once: true },
  );
})();


/* ===== build-navigation/p1.js ===== */
/**
 * Build view fast navigation: Tier0 client-only (same compile coordinate),
 * Tier1 workspace fragment fetch, Tier2 full SPA fallback.
 */
(function (global) {
  "use strict";

  const boot = (global.__meiLangBoot = global.__meiLangBoot || {});
  const stats = { tier0: 0, tier1: 0, tier2: 0 };
  const FRAGMENT_FETCH_TIMEOUT_MS = 8000;
  global.__meiBuildNavStats = stats;
  let lastBuildNavUrl = global.location.href;
  let buildNavInFlight = false;

  function isBuildWorkspacePathname(pathname) {
    return /^\/apps\/(?:build|manage)\//.test(String(pathname || ""));
  }

  function inferPreviewTabFromNodeId(nodeId) {
    const id = String(nodeId || "").trim();
    if (!id) return "";
    if (/^component:|^template:/i.test(id)) return "preview";
    if (/^(?:scene|route|projection):/i.test(id)) return "preview";
    if (/^board-(?:file|slot):/i.test(id)) return "preview";
    if (/^world-(?:dataset|metric|file):/i.test(id)) return "preview";
    if (/^dataset:/i.test(id)) return "preview";
    if (/^ui-scope:/i.test(id)) return "preview";
    if (/^(?:scene-panel|scene-block):/i.test(id)) return "preview";
    return "";
  }

  function treeLinkTab(rawUrl, linkEl) {
    const nodeId =
      (linkEl && linkEl.getAttribute && linkEl.getAttribute("data-build-node")) ||
      nodeIdFromUrl(rawUrl);
    return inferPreviewTabFromNodeId(nodeId) || currentManageTabFromUrl(rawUrl) || "overview";
  }

  function currentManageTabFromUrl(rawUrl) {
    try {
      const parsed = new URL(rawUrl, global.location.href);
      const tab = String(parsed.searchParams.get("tab") || "").trim().toLowerCase();
      if (tab) return tab;
    } catch (_) {}
    const shell = document.querySelector(".shell[data-build-tab]");
    return String(shell?.getAttribute("data-build-tab") || "overview").trim().toLowerCase();
  }

  function buildTab(rawUrl, linkEl) {
    try {
      const nodeId =
        (linkEl && linkEl.getAttribute && linkEl.getAttribute("data-build-node")) ||
        nodeIdFromUrl(rawUrl);
      const fromNode = inferPreviewTabFromNodeId(nodeId);
      if (fromNode) return fromNode;
      const parsed = new URL(rawUrl, global.location.href);
      const fromQuery = String(parsed.searchParams.get("tab") || "").trim().toLowerCase();
      if (fromQuery) return fromQuery;
      const shell = document.querySelector(".shell[data-build-tab]");
      return String(shell?.getAttribute("data-build-tab") || "overview").trim().toLowerCase();
    } catch (_) {
      return "overview";
    }
  }

  function isPackCatalogNodeId(nodeId) {
    return /^(?:component|template):/i.test(String(nodeId || "").trim());
  }

  function isBuildCatalogPreviewNode(nodeId) {
    return isPackCatalogNodeId(nodeId);
  }

  function nodeIdChanged(prevUrl, nextUrl) {
    return nodeIdFromUrl(prevUrl) !== nodeIdFromUrl(nextUrl);
  }

  function sceneIdFromNodeId(nodeId) {
    const raw = String(nodeId || "").trim();
    if (!raw) return "";
    const payload = raw.includes(":") ? raw.split(":").slice(1).join(":") : raw;
    const head = payload.split("/").filter(Boolean)[0];
    return head || "";
  }

  function inferCompileCoordinateFromNodeId(nodeId) {
    const id = String(nodeId || "").trim();
    if (!id) return null;
    if (/^board-(?:file|slot):/i.test(id)) {
      const payload = id.replace(/^board-(?:file|slot):/i, "");
      const slash = payload.indexOf("/");
      const boardKey = slash >= 0 ? payload.slice(0, slash) : payload;
      const hashAt = boardKey.indexOf("#");
      const file = hashAt >= 0 ? boardKey.slice(0, hashAt) : boardKey;
      const scene = hashAt >= 0 ? boardKey.slice(hashAt + 1) : "";
      if (file) return { scene, target: file };
    }
    if (/^(?:scene-panel|scene-block|scene|route|ui-scope):/i.test(id)) {
      const scene = sceneIdFromNodeId(id);
      const fromTree = readCompileCoordinateFromReachabilityTree(id);
      if (fromTree) return fromTree;
      const shell = readCompileCoordinateFromShell();
      if (shell?.target && (!shell.scene || !scene || shell.scene === scene)) {
        return { scene: scene || shell.scene, target: shell.target };
      }
    }
    if (/^(?:component|template):/i.test(id)) {
      const fromTree = readCompileCoordinateFromReachabilityTree(id);
      if (fromTree) return fromTree;
      const link = document.querySelector(
        `.build-reachability-tree a[data-build-node="${CSS.escape(id)}"]`,
      );
      if (link instanceof HTMLElement) {
        const target = String(link.getAttribute("data-compile-target") || "").trim();
        if (target) {
          return {
            scene: String(link.getAttribute("data-compile-scene") || "").trim(),
            target,
          };
        }
      }
    }
    return null;
  }

  function readCompileCoordinateFromReachabilityTree(nodeId) {
    const id = String(nodeId || "").trim();
    if (!id) return null;
    const script = document.getElementById("mei-build-reachability-tree");
    if (!script) return null;
    try {
      const roots = JSON.parse(script.textContent || "[]");
      if (!Array.isArray(roots)) return null;
      const walk = (nodes) => {
        for (const node of nodes || []) {
          if (node?.node_id === id) {
            const target = String(node.compile_target || "").trim();
            if (!target) return null;
            return {
              scene: String(node.compile_scene || "").trim(),
              target,
            };
          }
          const nested = walk(node.children);
          if (nested) return nested;
        }
        return null;
      };
      for (const root of roots) {
        const found = walk(root.children);
        if (found) return found;
      }
    } catch (_) {}
    return null;
  }

  function nodeIdFromUrl(rawUrl) {
    try {
      return String(new URL(rawUrl, global.location.href).searchParams.get("node") || "").trim();
    } catch (_) {
      return "";
    }
  }

  function readCompileCoordinateFromLink(el) {
    if (!(el instanceof HTMLElement)) return null;
    const anchor =
      el.matches("a[data-compile-target]") ? el : el.closest("a[data-compile-target]");
    if (!(anchor instanceof HTMLElement)) return null;
    const target = String(anchor.getAttribute("data-compile-target") || "").trim();
    if (!target) return null;
    return {
      scene: String(anchor.getAttribute("data-compile-scene") || "").trim(),
      target,
    };
  }

  function readCompileCoordinateFromShell() {
    const shell = document.querySelector(".shell[data-compile-target]");
    if (!shell) return null;
    const target = String(shell.getAttribute("data-compile-target") || "").trim();
    if (!target) return null;
    return {
      scene: String(shell.getAttribute("data-compile-scene") || "").trim(),
      target,
    };
  }

  function readCompileCoordinate(rawUrl, linkEl) {
    const fromLink = linkEl ? readCompileCoordinateFromLink(linkEl) : null;
    if (fromLink) return fromLink;
    const nodeId = nodeIdFromUrl(rawUrl);
    const fromTree = readCompileCoordinateFromReachabilityTree(nodeId);
    if (fromTree) return fromTree;
    const inferred = inferCompileCoordinateFromNodeId(nodeId);
    if (inferred) return inferred;
    return readCompileCoordinateFromShell();
  }

  function coordinatesEqual(a, b) {
    if (!a || !b) return false;
    if (a.target !== b.target) return false;
    // Board capsule = file + scene_export; slot switches share capsule with board-file.
    return a.scene === b.scene;
  }

  function boardCapsuleKeyFromNodeId(nodeId) {
    const raw = String(nodeId || "").trim();
    if (!/^board-(?:file|slot):/i.test(raw)) return "";
    const payload = raw.replace(/^board-(?:file|slot):/i, "");
    const slash = payload.indexOf("/");
    return slash >= 0 ? payload.slice(0, slash) : payload;
  }

  function boardExportChanged(prevNodeId, nextNodeId) {
    if (!/^board-/i.test(String(nextNodeId || ""))) return false;
    const prevKey = boardCapsuleKeyFromNodeId(prevNodeId);
    const nextKey = boardCapsuleKeyFromNodeId(nextNodeId);
    if (!nextKey) return false;
    return prevKey !== nextKey;
  }

  function cssEscape(value) {
    const raw = String(value || "");
    if (typeof global.CSS !== "undefined" && typeof global.CSS.escape === "function") {
      return global.CSS.escape(raw);
    }
    return raw.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  }

  function panelScopePathFromNodeId(nodeId) {
    const raw = String(nodeId || "").trim();
    if (!/^scene-panel:/i.test(raw)) return "";
    const encoded = raw.replace(/^scene-panel:/i, "");
    const slash = encoded.indexOf("/");
    return slash >= 0 ? encoded.slice(slash + 1) : "";
  }

  function readUiScopeMetaFromReachabilityTree(nodeId) {
    const id = String(nodeId || "").trim();
    if (!id) return null;
    const script = document.getElementById("mei-build-reachability-tree");
    if (!script) return null;
    try {
      const roots = JSON.parse(script.textContent || "[]");
      if (!Array.isArray(roots)) return null;
      const walk = (nodes) => {
        for (const node of nodes || []) {
          if (node?.node_id === id) {
            return {
              ui_role: String(node.ui_role || node.badges?.[0] || "").trim(),
              preview_scope: String(node.preview_scope || "").trim(),
              plane_tier: String(node.plane_tier || "").trim(),
            };
          }
          const nested = walk(node.children);
          if (nested) return nested;
        }
        return null;
      };
      for (const root of roots) {
        const found = walk(root.children);
        if (found) return found;
      }
    } catch (_) {}
    return null;
  }

  function tier0PanelTargetInDom(nodeId) {
    const node = String(nodeId || "").trim();
    if (node.startsWith("ui-scope:")) {
      const previewRoot = document.querySelector('[data-manage-tab-panel="preview"]');
      if (!previewRoot) return false;
      const target = previewRoot.querySelector(`[data-build-node="${cssEscape(node)}"]`);
      if (target) return true;
      const fromTree = readUiScopeMetaFromReachabilityTree(node);
      const scopePath = String(fromTree?.preview_scope || "").trim();
      if (scopePath) {
        const scoped = previewRoot.querySelector(
          `[data-mei-ui-scope="${cssEscape(scopePath)}"], [data-preview-scope="${cssEscape(scopePath)}"]`,
        );
        if (scoped) return true;
      }
      return Boolean(
        previewRoot.querySelector("[data-mei-ui-scope], [data-mei-tier], [data-preview-scope]"),
      );
    }
    if (!node.startsWith("scene-panel:")) return true;
    const panel = document.querySelector(
      `[data-manage-tab-panel="preview"] [data-build-node="${cssEscape(node)}"]`,
    );
    if (panel) return true;
    const scopePath = panelScopePathFromNodeId(node);
    if (!scopePath) return false;
    return Boolean(
      document.querySelector(
        `[data-manage-tab-panel="preview"] [data-preview-scope="${cssEscape(scopePath)}"]`,
      ),
    );
  }

  function tier0TargetReady(toUrl) {
    const nodeId = nodeIdFromUrl(toUrl);
    if (!nodeId) return true;
    if (/^board-(?:file|slot):/i.test(nodeId)) {
      const surface = document.querySelector(
        '[data-manage-tab-panel="preview"] .preview-surface, [data-manage-tab-panel="preview"] .preview-stage',
      );
      return Boolean(surface);
    }
    return tier0PanelTargetInDom(nodeId);
  }

  function isStructureInspectNode(nodeId) {
    return /^(?:ui-scope|scene-panel|scene-block):/i.test(String(nodeId || "").trim());
  }

  function isSameSceneStructureNav(fromUrl, toUrl) {
    const fromNode = nodeIdFromUrl(fromUrl);
    const toNode = nodeIdFromUrl(toUrl);
    if (!isStructureInspectNode(toNode)) return false;
    const toScene = sceneIdFromNodeId(toNode);
    if (!toScene) return false;
    const fromScene =
      sceneIdFromNodeId(fromNode) ||
      readCompileCoordinateFromShell()?.scene ||
      "";
    return fromScene === toScene;
  }

  function classifyBuildNavTier(fromUrl, toUrl, linkEl) {
    try {
      const from = new URL(fromUrl, global.location.href);
      const to = new URL(toUrl, global.location.href);
      if (!isBuildWorkspacePathname(to.pathname)) return "full";
      if (!isBuildWorkspacePathname(from.pathname)) return "full";
      if (from.pathname !== to.pathname) return "full";
      const toNode = nodeIdFromUrl(toUrl);
      const previewTab =
        buildTab(toUrl, linkEl) === "preview" || Boolean(inferPreviewTabFromNodeId(toNode));
      if (!previewTab) return "full";
      if (isSameSceneStructureNav(fromUrl, toUrl)) {
        return "client";
      }
      const toCoord = readCompileCoordinate(toUrl, linkEl);
      const fromCoord = readCompileCoordinate(fromUrl);
      if (!toCoord || !fromCoord) return "full";
      if (coordinatesEqual(fromCoord, toCoord)) {
        return "client";
      }
      return "fragment";
    } catch (_) {
      return "full";
    }
  }

  function showBuildNavLoading(url) {
    if (typeof showManageWorkspaceLoadingState === "function") {
      showManageWorkspaceLoadingState(url);
    }
  }

  function clearBuildNavLoading() {
    if (typeof boot.clearManageWorkspaceLoadingState === "function") {
      boot.clearManageWorkspaceLoadingState();
    }
  }

  function syncBuildShellUrl(url, replaceHistory, linkEl) {
    const parsed = new URL(url, global.location.href);
    const shell = document.querySelector(".shell");
    if (shell) {
      const node = String(parsed.searchParams.get("node") || "").trim();
      const focus = String(parsed.searchParams.get("focus") || "").trim();
      let tab = String(parsed.searchParams.get("tab") || "").trim();
      const inferredTab = inferPreviewTabFromNodeId(node);
      if (!tab && inferredTab) {
        tab = inferredTab;
        parsed.searchParams.set("tab", inferredTab);
        url = parsed.href;
      }
      if (node) shell.setAttribute("data-build-node", node);
      else shell.removeAttribute("data-build-node");
      if (focus) shell.setAttribute("data-build-focus", focus);
      else shell.removeAttribute("data-build-focus");
      const resolvedTab = tab || inferredTab;
      if (resolvedTab) shell.setAttribute("data-build-tab", resolvedTab);
      const coord = readCompileCoordinate(url, linkEl);
      if (coord) {
        shell.setAttribute("data-compile-scene", coord.scene);
        shell.setAttribute("data-compile-target", coord.target);
      }
    }
    if (replaceHistory) global.history.replaceState({}, "", url);
    else global.history.pushState({}, "", url);
    lastBuildNavUrl = url;
  }

  function ensurePreviewTabVisible(rawUrl, linkEl, options) {
    const opts = options && typeof options === "object" ? options : {};
    const tab = buildTab(rawUrl, linkEl);
    const shell = document.querySelector(".shell[data-build-tab]");
    const current = String(
      shell?.getAttribute("data-build-tab") || buildTab(global.location.href, linkEl),
    )
      .trim()
      .toLowerCase();
    if (current === tab) {
      document.querySelectorAll("[data-manage-tab-panel]").forEach((panel) => {
        if (!(panel instanceof HTMLElement)) return;
        const slug = String(panel.getAttribute("data-manage-tab-panel") || "")
          .trim()
          .toLowerCase();


/* ===== build-navigation/p2.js ===== */
        panel.hidden = slug !== tab;
      });
      return;
    }
    if (typeof boot.switchManageTab === "function") {
      boot.switchManageTab(tab, { updateUrl: false, emit: opts.emit !== false });
      return;
    }
    document.querySelectorAll("[data-manage-tab-panel]").forEach((panel) => {
      if (!(panel instanceof HTMLElement)) return;
      const slug = String(panel.getAttribute("data-manage-tab-panel") || "").trim().toLowerCase();
      panel.hidden = slug !== tab;
    });
  }

  function wakePreviewRuntime(scope, options) {
    const opts = options || {};
    const resetCache = opts.resetRuntimeQueryCache === true;
    if (typeof boot.scheduleFrameViewportRelayout === "function") {
      try {
        boot.scheduleFrameViewportRelayout();
      } catch (_) {}
    }
    if (typeof publishManagePreviewFromDoc === "function") {
      publishManagePreviewFromDoc(document, { resetRuntimeQueryCache: resetCache });
    }
    if (typeof boot.mountManagePreviewBoard === "function") {
      void boot.mountManagePreviewBoard(document);
    }
    const dispatchPreviewUpdated = (pass) => {
      try {
        global.dispatchEvent(
          new CustomEvent("meilang:preview-updated", {
            detail: {
              scope: scope || "build-nav",
              resetRuntimeQueryCache: pass === 0 ? resetCache : false,
            },
          }),
        );
      } catch (_) {}
    };
    dispatchPreviewUpdated(0);
    if (opts.pulsePreviewUpdated) {
      global.requestAnimationFrame(() => {
        if (typeof boot.scheduleFrameViewportRelayout === "function") {
          try {
            boot.scheduleFrameViewportRelayout();
          } catch (_) {}
        }
        global.requestAnimationFrame(() => {
          dispatchPreviewUpdated(1);
          if (typeof boot.mountManagePreviewBoard === "function") {
            void boot.mountManagePreviewBoard(document);
          }
        });
      });
    }
  }

  function runTier0PostNav(prevUrl) {
    global.__meiBuildNavPrevUrl = String(prevUrl || global.location.href);
    ensurePreviewTabVisible(global.location.href, null, { emit: false });
    document.body.classList.remove("access-drilldown-open", "access-scene-board-open");
    if (typeof closeDrilldownOverlay === "function") {
      try {
        closeDrilldownOverlay();
      } catch (_) {}
    }
    if (typeof global.MeiBuildInspectHighlight?.refresh === "function") {
      global.MeiBuildInspectHighlight.refresh({ scope: "build-inspect" });
    }
    if (typeof global.MeiBuildTreePersist?.refresh === "function") {
      global.MeiBuildTreePersist.refresh();
    }
    if (typeof boot.activateManagePreviewBoardPool === "function") {
      boot.activateManagePreviewBoardPool(document);
    }
    const prevNode = nodeIdFromUrl(prevUrl || global.location.href);
    const nextNode = nodeIdFromUrl(global.location.href);
    if (boardExportChanged(prevNode, nextNode)) {
      wakePreviewRuntime("build-nav-board-export");
      return;
    }
    if (/^(?:ui-scope|scene-panel|scene-block):/i.test(nextNode)) {
      return;
    }
    if (isPackCatalogNodeId(nextNode) && nodeIdChanged(prevUrl, nextNode)) {
      wakePreviewRuntime("build-nav-catalog-node", {
        resetRuntimeQueryCache: true,
        pulsePreviewUpdated: true,
      });
    }
  }

  function shouldSkipPreviewRuntimeWake(prevUrl, nextUrl) {
    if (isSameSceneStructureNav(prevUrl, nextUrl)) return true;
    if (classifyBuildNavTier(prevUrl, nextUrl) !== "client") return false;
    const prevNode = nodeIdFromUrl(prevUrl);
    const nextNode = nodeIdFromUrl(nextUrl);
    if (boardExportChanged(prevNode, nextNode)) return false;
    return true;
  }

  function shouldWakePreviewRuntime(prevUrl, nextUrl) {
    return !shouldSkipPreviewRuntimeWake(prevUrl, nextUrl);
  }

  function applyBootstrapScripts(drilldownScript) {
    const raw = String(drilldownScript || "").trim();
    if (!raw) return;
    const scriptTpl = document.createElement("template");
    scriptTpl.innerHTML = raw;
    ["mei-scene-drilldown-context", "mei-host-runtime-capabilities"].forEach((id) => {
      const next = scriptTpl.content.querySelector(`#${CSS.escape(id)}`);
      if (!(next instanceof HTMLScriptElement)) return;
      const existing = document.getElementById(id);
      if (existing instanceof HTMLScriptElement) {
        existing.textContent = next.textContent || "";
        return;
      }
      document.body.appendChild(next.cloneNode(true));
    });
    try {
      delete global.__meiSceneDrilldownContext;
      delete global.__meiHostRuntimeCapabilities;
    } catch (_) {}
  }

  function swapPreviewFragment(previewHtml, drilldownScript) {
    const panel = document.querySelector('[data-manage-tab-panel="preview"]');
    if (!panel) return false;
    const html = String(previewHtml || "").trim();
    if (!html) return false;
    const tpl = document.createElement("template");
    tpl.innerHTML = html;
    const nextScroll = tpl.content.querySelector(".preview-pane-scroll");
    const scroll = panel.querySelector(".preview-pane-scroll");
    if (nextScroll instanceof HTMLElement && scroll instanceof HTMLElement) {
      scroll.replaceWith(document.importNode(nextScroll, true));
    } else if (scroll instanceof HTMLElement) {
      scroll.innerHTML = html;
    } else {
      panel.innerHTML = html;
    }
    const nextBar = tpl.content.querySelector("#build-inspect-bar");
    const curBar = panel.querySelector("#build-inspect-bar");
    if (nextBar instanceof HTMLElement && curBar instanceof HTMLElement) {
      curBar.replaceWith(document.importNode(nextBar, true));
    }
    applyBootstrapScripts(drilldownScript);
    return true;
  }

  async function fetchWorkspaceFragment(url) {
    const parsed = new URL(url, global.location.href);
    const parts = parsed.pathname.split("/").filter(Boolean);
    const appId = parts[2] || "";
    const params = new URLSearchParams({
      app_id: appId,
      node: String(parsed.searchParams.get("node") || ""),
      tab: buildTab(url) || "preview",
    });
    const focus = parsed.searchParams.get("focus");
    if (focus) params.set("focus", focus);
    const controller = new AbortController();
    const timer = global.setTimeout(() => controller.abort(), FRAGMENT_FETCH_TIMEOUT_MS);
    try {
      const resp = await fetch(`/api/build/workspace-fragment?${params.toString()}`, {
        credentials: "same-origin",
        headers: { Accept: "application/json", "x-mei-spa-nav": "1" },
        signal: controller.signal,
      });
      if (!resp.ok) throw new Error(`fragment failed: ${resp.status}`);
      return { payload: await resp.json(), resp };
    } finally {
      global.clearTimeout(timer);
    }
  }

  async function navigateBuildTier1(url, replaceHistory, linkEl) {
    showBuildNavLoading(url);
    try {
      ensurePreviewTabVisible(url);
      const { payload } = await fetchWorkspaceFragment(url);
      const ok = swapPreviewFragment(
        String(payload.preview_html || ""),
        String(payload.drilldown_script || ""),
      );
      if (!ok) return false;
      if (
        Array.isArray(payload.workspace_scripts) &&
        typeof boot.syncPreviewWorkspaceScripts === "function"
      ) {
        await boot.syncPreviewWorkspaceScripts(payload.workspace_scripts);
      }
      const shell = document.querySelector(".shell");
      if (shell) {
        if (payload.node) shell.setAttribute("data-build-node", String(payload.node));
        if (payload.focus) shell.setAttribute("data-build-focus", String(payload.focus));
        const coord = payload.compile_coordinate;
        if (coord && typeof coord === "object") {
          shell.setAttribute("data-compile-scene", String(coord.scene_id || ""));
          shell.setAttribute("data-compile-target", String(coord.preview_target || ""));
        }
        const parsed = new URL(url, global.location.href);
        const tab = String(parsed.searchParams.get("tab") || "").trim();
        const node = String(parsed.searchParams.get("node") || "").trim();
        const resolvedTab = tab || inferPreviewTabFromNodeId(node);
        if (resolvedTab) shell.setAttribute("data-build-tab", resolvedTab);
      }
      if (replaceHistory) global.history.replaceState({}, "", url);
      else global.history.pushState({}, "", url);
      lastBuildNavUrl = url;
      stats.tier1 += 1;
      runTier0PostNav(url);
      const nextNode = nodeIdFromUrl(url);
      wakePreviewRuntime("build-fragment", {
        resetRuntimeQueryCache: isPackCatalogNodeId(nextNode),
        pulsePreviewUpdated: true,
      });
      return true;
    } finally {
      clearBuildNavLoading();
    }
  }

  async function tryNavigateBuild(fromUrl, toUrl, options) {
    if (buildNavInFlight) {
      return { handled: false, tier: 2, reason: "in_flight" };
    }
    const opts = options || {};
    const structureNav = isSameSceneStructureNav(fromUrl, toUrl);
    let tier = classifyBuildNavTier(fromUrl, toUrl, opts.linkEl);
    if (structureNav && tier === "full") {
      tier = "client";
    }
    global.__meiBuildNavLastTier = { tier, structureNav, fromUrl, toUrl };

    const finishTier0 = () => {
      syncBuildShellUrl(toUrl, !!opts.replaceHistory, opts.linkEl);
      stats.tier0 += 1;
      runTier0PostNav(fromUrl);
      return { handled: true, tier: 0 };
    };

    if (tier === "client") {
      if (structureNav || tier0TargetReady(toUrl)) {
        buildNavInFlight = true;
        try {
          return finishTier0();
        } finally {
          buildNavInFlight = false;
        }
      }
      buildNavInFlight = true;
      try {
        const ok = await navigateBuildTier1(toUrl, !!opts.replaceHistory, opts.linkEl);
        if (ok) return { handled: true, tier: 1 };
      } catch (err) {
        console.warn("[build-navigation] tier0 missing DOM; tier1 failed", err);
      } finally {
        buildNavInFlight = false;
      }
      stats.tier2 += 1;
      return { handled: false, tier: 2 };
    }
    if ((tier === "fragment" || structureNav) && !opts.skipFragment) {
      if (structureNav) {
        buildNavInFlight = true;
        try {
          return finishTier0();
        } finally {
          buildNavInFlight = false;
        }
      }
      buildNavInFlight = true;
      try {
        const ok = await navigateBuildTier1(toUrl, !!opts.replaceHistory, opts.linkEl);
        if (ok) return { handled: true, tier: 1 };
      } catch (err) {
        console.warn("[build-navigation] tier1 failed; fallback to full SPA", err);
      } finally {
        buildNavInFlight = false;
      }
    }
    if (structureNav) {
      buildNavInFlight = true;
      try {
        return finishTier0();
      } finally {
        buildNavInFlight = false;
      }
    }
    stats.tier2 += 1;
    return { handled: false, tier: 2 };
  }

  async function tryHandleBuildClick(event, targetUrl, replaceHistory) {
    try {
      if (!targetUrl || !isBuildWorkspacePathname(new URL(targetUrl, global.location.href).pathname)) {
        return false;
      }
      let linkEl = null;
      const path = event?.composedPath ? event.composedPath() : [];
      for (const item of path) {
        if (item instanceof HTMLAnchorElement && item.hasAttribute("data-build-node")) {
          linkEl = item;
          break;
        }
      }
      const result = await tryNavigateBuild(global.location.href, targetUrl, {
        replaceHistory,
        linkEl,
      });
      return result.handled;
    } catch (err) {
      console.warn("[build-navigation] click handler failed; fallback to SPA", err);
      clearBuildNavLoading();
      return false;
    }
  }

  global.MeiBuildNavigation = {
    buildTab,
    inferPreviewTabFromNodeId,
    treeLinkTab,
    isSameSceneStructureNav,
    readCompileCoordinate,
    coordinatesEqual,
    classifyBuildNavTier,
    tryNavigateBuild,
    tryHandleBuildClick,
    shouldSkipPreviewRuntimeWake,
    shouldWakePreviewRuntime,
    swapPreviewFragment,
    getLastUrl: () => lastBuildNavUrl,
    noteUrl: (url) => {
      lastBuildNavUrl = String(url || global.location.href);
    },
    stats,
  };
  global.MeiBuildNavigation.noteUrl(global.location.href);
})(window);


/* ===== build-inspect-highlight/p1.js ===== */
/**
 * Build view: preview inspect — highlight, click-to-select node/focus, inspect bar, suppress drilldown.
 */
(function (global) {
  "use strict";

  const PANEL_SELECTOR = "[data-build-node^='scene-panel:'], [data-build-node^='ui-scope:']";
  const BLOCK_SELECTOR = "[data-build-focus^='scene-block:']";
  const UI_SCOPE_SELECTOR = "[data-mei-ui-scope]";
  const SELECTOR = `${PANEL_SELECTOR}, ${BLOCK_SELECTOR}`;

  function isBuildRoute() {
    return /^\/apps\/(?:build|manage)\//.test(String(global.location.pathname || ""));
  }

  function activeShell() {
    return document.querySelector(".shell[data-build-node]");
  }

  function activeBuildNode() {
    try {
      const fromUrl = String(new URL(global.location.href).searchParams.get("node") || "").trim();
      if (fromUrl) return fromUrl;
    } catch (_) {}
    return String(activeShell()?.getAttribute("data-build-node") || "").trim();
  }

  function activeBuildFocus() {
    try {
      const fromUrl = String(new URL(global.location.href).searchParams.get("focus") || "").trim();
      if (fromUrl) return fromUrl;
    } catch (_) {}
    return String(activeShell()?.getAttribute("data-build-focus") || "").trim();
  }

  function previewRoot() {
    return (
      document.querySelector("[data-manage-tab-panel='preview']") ||
      document.querySelector(".preview-surface") ||
      document.querySelector(".preview-pane-scroll")
    );
  }

  function inspectBarLabel() {
    return document.getElementById("build-inspect-bar-label");
  }

  function clearHighlights(root) {
    root.querySelectorAll(".build-inspect-selected, .build-inspect-focus-selected").forEach((el) => {
      el.classList.remove("build-inspect-selected", "build-inspect-focus-selected");
    });
  }

  function inferPlaneTierFromMeta(meta, nodeId) {
    const fromMeta = normalizePreviewTier(meta?.plane_tier || "");
    if (fromMeta) return fromMeta;
    const scope = String(meta?.preview_scope || "").trim();
    const hay = `${scope}:${String(nodeId || "").trim()}`;
    const match = hay.match(/(?:^|\/)(T[0-2])(?:\/|$)/i);
    return match ? normalizePreviewTier(match[1]) : "";
  }

  function updateInspectBar(node, focus, el, message) {
    const bar = inspectBarLabel();
    if (!bar) return;
    if (message) {
      bar.textContent = message;
      return;
    }
    if (!node && !focus) {
      bar.textContent = "在左侧体验树选择 Panel/Block，或在预览中点击组件以指认上下文。";
      return;
    }
    const blockId = el?.getAttribute("data-mei-block-id") || "";
    const useKey = el?.getAttribute("data-mei-use-key") || "";
    const panelId = el?.getAttribute("data-mei-panel-id") || "";
    const sourceMeta = readSourceMetaFromReachabilityTree(node);
    const bits = [];
    if (node) bits.push(`node=${node}`);
    if (focus) bits.push(`focus=${focus}`);
    if (sourceMeta?.file) bits.push(`src=${sourceMeta.file}`);
    if (sourceMeta?.symbol) bits.push(`sym=${sourceMeta.symbol}`);
    if (panelId) bits.push(`panel=${panelId}`);
    if (blockId) bits.push(`block=${blockId}`);
    if (useKey) bits.push(`use=${useKey}`);
    bar.textContent = bits.join(" · ");
  }

  function readSourceMetaFromReachabilityTree(nodeId) {
    const id = String(nodeId || "").trim();
    if (!id) return null;
    const script = document.getElementById("mei-build-reachability-tree");
    if (!script) return null;
    try {
      const roots = JSON.parse(script.textContent || "[]");
      if (!Array.isArray(roots)) return null;
      const walk = (nodes) => {
        for (const node of nodes || []) {
          if (node?.node_id === id) {
            const file = String(node.source_file || "").trim();
            const symbol = String(node.source_symbol || "").trim();
            if (file || symbol) return { file, symbol };
            return null;
          }
          const nested = walk(node.children);
          if (nested) return nested;
        }
        return null;
      };
      for (const root of roots) {
        const found = walk(root.children);
        if (found) return found;
      }
    } catch (_) {}
    return null;
  }

  function previewInspectHost(root) {
    if (!(root instanceof HTMLElement)) return null;
    return (
      root.querySelector(".preview-pane-scroll") ||
      root.querySelector(".preview-surface") ||
      root
    );
  }

  function syncInspectModeAttributes(root, meta, nodeId) {
    const host = previewInspectHost(root);
    if (!(host instanceof HTMLElement)) return;
    host.setAttribute("data-build-inspect-active", "true");
    const role = String(meta?.ui_role || "").trim();
    const scope = String(meta?.preview_scope || "").trim();
    const tier =
      normalizePreviewTier(meta?.plane_tier || "") || inferPlaneTierFromMeta(meta, nodeId);
    const node = String(nodeId || "").trim();
    if (node) host.setAttribute("data-build-inspect-node", node);
    else host.removeAttribute("data-build-inspect-node");
    if (role) host.setAttribute("data-build-inspect-role", role);
    else host.removeAttribute("data-build-inspect-role");
    if (scope) host.setAttribute("data-build-inspect-scope", scope);
    else host.removeAttribute("data-build-inspect-scope");
    // plane 仅描边，不裁剪 tier（否则 DOM 默认 t1 时会把整屏藏空）
    if (role === "plane") {
      host.removeAttribute("data-build-inspect-tier");
    } else if (tier) {
      host.setAttribute("data-build-inspect-tier", tier);
    } else {
      host.removeAttribute("data-build-inspect-tier");
    }
  }

  function clearInspectModeAttributes(root) {
    const host = previewInspectHost(root);
    if (!(host instanceof HTMLElement)) return;
    host.removeAttribute("data-build-inspect-active");
    host.removeAttribute("data-build-inspect-node");
    host.removeAttribute("data-build-inspect-role");
    host.removeAttribute("data-build-inspect-scope");
    host.removeAttribute("data-build-inspect-tier");
  }

  /** 仅同步 inspect 宿主属性，供 CSS 切换 tier 可见性；不使用 opacity 蒙板（会连带压暗地图与子内容）。 */
  function applyInspectFocusChrome(root, meta, nodeId) {
    syncInspectModeAttributes(root, meta, nodeId);
  }

  function syncBuildPreviewScopedChrome(root) {
    const scopedActive =
      root instanceof HTMLElement &&
      (root.querySelector("[data-preview-scope].build-preview-scoped-dim") != null ||
        root.querySelector("[data-mei-panel-id].build-preview-scoped-dim") != null ||
        root.querySelector("[data-chart-slot-index].build-preview-scoped-dim") != null ||
        root.querySelector("[data-build-board-slot].build-preview-scoped-dim") != null);
    document.body.classList.toggle("build-preview-scoped-active", scopedActive);
  }

  function catalogKeyFromNode(node) {
    const raw = String(node || "").trim();
    if (raw.startsWith("component:")) return raw.slice("component:".length).trim();
    if (raw.startsWith("template:")) return raw.slice("template:".length).trim();
    return "";
  }

  function templateKeyFromNode(node) {
    return catalogKeyFromNode(node);
  }

  function isTemplateAuthoringPreview() {
    const node = activeBuildNode();
    if (node.startsWith("component:")) {
      const target = String(activeShell()?.getAttribute("data-compile-target") || "")
        .trim()
        .toLowerCase();
      return target.includes("/previews/") || target.includes("stock/components/");
    }
    if (!node.startsWith("template:")) return false;
    const target = String(activeShell()?.getAttribute("data-compile-target") || "")
      .trim()
      .toLowerCase();
    if (!target) return false;
    return (
      target.includes("templates/") ||
      target.includes(".stock/templates") ||
      target.includes("stock/templates") ||
      target.includes("/previews/")
    );
  }

  function normalizeTemplateFileKey(value) {
    let raw = String(value || "").trim().replace(/\\/g, "/");
    while (raw.startsWith("./")) raw = raw.slice(2);
    while (raw.startsWith("/")) raw = raw.slice(1);
    if (raw.startsWith(".stock/templates/")) raw = raw.slice(".stock/templates/".length);
    else if (raw.startsWith("templates/")) raw = raw.slice("templates/".length);
    return raw;
  }

  function uniqueStrings(values) {
    const out = [];
    const seen = new Set();
    for (const value of values || []) {
      const item = String(value || "").trim();
      if (!item || seen.has(item)) continue;
      seen.add(item);
      out.push(item);
    }
    return out;
  }

  function templateUseKeysFromTree(templateNode) {
    const key = templateKeyFromNode(templateNode);
    if (!key) return [];
    const useKeys = [];
    if (!key.includes("/") && !/\.mei$/i.test(key)) {
      useKeys.push(key);
    }
    const normalizedFile = normalizeTemplateFileKey(key);
    if (!normalizedFile || (!key.includes("/") && !/\.mei$/i.test(key))) {
      return uniqueStrings(useKeys);
    }
    const roots = readReachabilityTreeRoots();
    const walk = (nodes) => {
      for (const node of nodes || []) {
        const kind = String(node?.kind || "").trim();
        const nodeId = String(node?.node_id || "").trim();
        if (
          (kind === "component" && nodeId.startsWith("component:")) ||
          (kind === "template" && nodeId.startsWith("template:"))
        ) {
          const useKey = nodeId.includes(":")
            ? nodeId.slice(nodeId.indexOf(":") + 1).trim()
            : "";
          const badges = Array.isArray(node?.badges) ? node.badges : [];
          const matched = badges.some(
            (badge) => normalizeTemplateFileKey(badge) === normalizedFile,
          );
          if (matched && useKey) {
            useKeys.push(useKey);
          }
        }
        walk(node?.children);
      }
    };
    for (const root of roots) {
      walk(root?.children);
    }
    return uniqueStrings(useKeys);
  }

  function applyTemplateScopedPreview(root, useKeys) {
    if (!Array.isArray(useKeys) || useKeys.length === 0) return;
    const keySet = new Set(useKeys);
    let anyMatch = false;
    root.querySelectorAll("[data-mei-use-key]").forEach((el) => {
      const key = String(el.getAttribute("data-mei-use-key") || "").trim();
      if (key && keySet.has(key)) {
        anyMatch = true;
      }
    });
    if (!anyMatch) {
      syncBuildPreviewScopedChrome(root);
      return;
    }
    root.querySelectorAll("[data-mei-use-key]").forEach((el) => {
      const key = String(el.getAttribute("data-mei-use-key") || "").trim();
      if (key && !keySet.has(key)) {
        el.classList.add("build-preview-scoped-dim");
      }
    });
    syncBuildPreviewScopedChrome(root);
  }

  function boardSlotIdFromNode(node) {
    const raw = String(node || "").trim();
    if (!raw.startsWith("board-slot:")) return "";
    const payload = raw.replace(/^board-slot:/i, "");
    const slash = payload.lastIndexOf("/");
    return slash >= 0 ? payload.slice(slash + 1) : "";
  }

  function readReachabilityTreeRoots() {
    const el = document.getElementById("mei-build-reachability-tree");
    if (!el) return [];
    try {
      const parsed = JSON.parse(el.textContent || "[]");
      return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
      return [];
    }
  }

  function findReachabilityNodeEntry(nodeId) {
    const target = String(nodeId || "").trim();
    if (!target) return null;
    let found = null;
    const walk = (nodes, parent) => {
      for (const node of nodes || []) {
        if (String(node?.node_id || "").trim() === target) {
          found = { node, parent };
          return true;
        }
        if (walk(node?.children, node)) return true;
      }
      return false;
    };
    for (const root of readReachabilityTreeRoots()) {
      if (walk(root?.children, root)) break;
    }
    return found;
  }

  function normalizePreviewScopePath(scope) {
    const segments = String(scope || "")
      .split("/")
      .map((part) => part.trim())
      .filter(Boolean);
    const out = [];
    for (const segment of segments) {
      if (out[out.length - 1] !== segment) out.push(segment);
    }
    return out.join("/");
  }

  function scopeAlignScore(uiScope, previewScope) {
    const scope = normalizePreviewScopePath(uiScope);
    const target = normalizePreviewScopePath(previewScope);
    if (!scope || !target) return 0;
    if (scope === target) return 10_000 + target.length;
    if (scope.endsWith(`/${target}`)) return 9_000 + target.length;
    const scopeParts = scope.split("/").filter(Boolean);
    const targetParts = target.split("/").filter(Boolean);
    if (!scopeParts.length || !targetParts.length) return 0;
    let panelIndex = 0;
    let matched = 0;
    for (const part of targetParts) {
      let found = false;
      while (panelIndex < scopeParts.length) {
        if (scopeParts[panelIndex] === part) {
          matched += 1;
          panelIndex += 1;
          found = true;
          break;
        }
        panelIndex += 1;
      }
      if (!found) return 0;
    }
    return 6_000 + matched * 100 + target.length;
  }

  function isInspectTargetVisible(el) {
    if (!(el instanceof HTMLElement)) return false;
    let node = el;
    while (node && node !== document.body) {
      const style = getComputedStyle(node);
      if (style.display === "none" || style.visibility === "hidden") return false;
      node = node.parentElement;
    }
    return true;
  }

  function pickBestInspectTarget(candidates, previewScope) {
    const pool = (Array.isArray(candidates) ? candidates : []).filter(
      (el) => el instanceof HTMLElement,
    );
    if (!pool.length) return null;
    if (pool.length === 1) return pool[0];
    const target = normalizePreviewScopePath(previewScope);
    let best = pool[0];
    let bestScore = -1;
    for (const el of pool) {
      let score = scopeAlignScore(
        el.getAttribute("data-mei-ui-scope") || el.getAttribute("data-preview-scope") || "",
        target,
      );
      if (isInspectTargetVisible(el)) score += 50;
      if (score > bestScore) {
        bestScore = score;
        best = el;
      }
    }
    return best;
  }

  function scopePathLength(el) {
    if (!(el instanceof HTMLElement)) return 0;
    const path = String(
      el.getAttribute("data-mei-ui-scope") || el.getAttribute("data-preview-scope") || "",
    ).trim();
    return path.length;
  }

  function contentUseKeyFromMeta(meta) {
    const badges = Array.isArray(meta?.badges) ? meta.badges : [];
    for (let i = badges.length - 1; i >= 0; i -= 1) {
      const badge = String(badges[i] || "").trim();
      if (!badge || badge === "content") continue;
      if (/^plane:/i.test(badge)) continue;
      if (/^(?:region|section|plane|scene|micro|slot|budget)$/i.test(badge)) continue;
      return badge;
    }
    return "";
  }

  function blockKeyCandidates(scope) {
    const keys = [];
    const last = scope.split("/").filter(Boolean).pop() || "";
    if (last) keys.push(last);
    if (last.includes("~")) {
      const stem = last.split("~")[0];
      if (stem) keys.push(stem);
    }
    return keys;
  }

  function resolveUiScopeHighlightTargets(root, node, meta) {
    const role = String(meta?.ui_role || "").trim().toLowerCase();
    const scope = String(meta?.preview_scope || "").trim();
    const nodeId = String(node || "").trim();
    if (!nodeId) return [];

    const byBuildNode = Array.from(
      root.querySelectorAll(`[data-build-node="${CSS.escape(nodeId)}"]`),
    ).filter((el) => el instanceof HTMLElement);
    if (byBuildNode.length === 1) return byBuildNode;
    if (byBuildNode.length > 1) {
      const picked = pickBestInspectTarget(byBuildNode, scope);
      return picked ? [picked] : [byBuildNode[0]];
    }

    if (scope) {
      const exactScope = root.querySelector(`[data-mei-ui-scope="${CSS.escape(scope)}"]`);
      if (exactScope instanceof HTMLElement) return [exactScope];
      const normalizedScope = normalizePreviewScopePath(scope);
      if (normalizedScope && normalizedScope !== scope) {
        const normalizedExact = root.querySelector(
          `[data-mei-ui-scope="${CSS.escape(normalizedScope)}"]`,
        );
        if (normalizedExact instanceof HTMLElement) return [normalizedExact];
      }
      const exactPreview = root.querySelector(`[data-preview-scope="${CSS.escape(scope)}"]`);
      if (exactPreview instanceof HTMLElement) return [exactPreview];

      const nested = Array.from(
        root.querySelectorAll(`[data-mei-ui-scope^="${CSS.escape(scope)}/"]`),
      ).filter((el) => el instanceof HTMLElement);
      if (nested.length) {
        nested.sort((a, b) => scopePathLength(b) - scopePathLength(a));
        return [nested[0]];
      }
    }

    if (role === "content") {
      const areaHint = scope.split("/").filter(Boolean).slice(-2, -1)[0] || "";
      for (const blockKey of blockKeyCandidates(scope)) {
        const byBlock = root.querySelector(`[data-mei-block-id="${CSS.escape(blockKey)}"]`);
        if (byBlock instanceof HTMLElement) return [byBlock];
      }
      const scopedBlocks = Array.from(
        root.querySelectorAll("[data-mei-ui-scope], [data-mei-block-id], [data-mei-panel-area]"),
      ).filter((el) => {
        if (!(el instanceof HTMLElement)) return false;
        const uiScope = String(el.getAttribute("data-mei-ui-scope") || "").trim();
        const blockId = String(el.getAttribute("data-mei-block-id") || "").trim();
        const panelArea = String(el.getAttribute("data-mei-panel-area") || "").trim();
        const areaMatches = !areaHint || !panelArea || panelArea === areaHint;
        return (
          areaMatches &&
          blockKeyCandidates(scope).some(
            (key) =>
              blockId === key ||
              uiScope === scope ||
              normalizePreviewScopePath(uiScope) === normalizePreviewScopePath(scope) ||
              (scope && uiScope.endsWith(`/${key}`)) ||
              (blockId && scope.endsWith(`/${blockId}`)),
          )
        );
      });
      if (scopedBlocks.length) {
        const picked = pickBestInspectTarget(scopedBlocks, scope);
        return picked ? [picked] : [scopedBlocks[0]];
      }
      const useKey = contentUseKeyFromMeta(meta);
      if (useKey) {
        const byUse = root.querySelector(`[data-mei-use-key="${CSS.escape(useKey)}"]`);
        if (byUse instanceof HTMLElement) return [byUse];
      }
    }

    return fallbackScenePanelFromUiScope(root, nodeId);
  }

  function fallbackScenePanelFromUiScope(root, nodeId) {
    const raw = String(nodeId || "").trim();
    if (!raw.toLowerCase().startsWith("ui-scope:")) return [];
    const payload = raw.includes(":") ? raw.split(":").slice(1).join(":") : raw;
    const segments = payload.split("/").filter(Boolean);
    if (segments.length < 2) return [];
    const scene = segments[0];
    const tail = segments.slice(2);
    const leaf = tail[tail.length - 1] || segments[segments.length - 1];
    const candidates = Array.from(
      root.querySelectorAll(`[data-build-node^="scene-panel:${CSS.escape(scene)}/"]`),
    ).filter((el) => {
      if (!(el instanceof HTMLElement)) return false;
      const id = String(el.getAttribute("data-build-node") || "");
      if (leaf && id.endsWith(leaf)) return true;
      return tail.length > 0 && tail.every((seg) => id.includes(seg));
    });
    if (!candidates.length) return [];
    candidates.sort((a, b) => {
      const al = String(a.getAttribute("data-build-node") || "").length;
      const bl = String(b.getAttribute("data-build-node") || "").length;
      return bl - al;
    });
    return [candidates[0]];
  }

  function readUiScopeMetaFromNode(nodeId) {
    const entry = findReachabilityNodeEntry(nodeId);
    if (!entry?.node) return null;
    return {
      ui_role: String(entry.node.ui_role || entry.node.badges?.[0] || "").trim(),
      preview_scope: String(entry.node.preview_scope || "").trim(),
      plane_tier: String(entry.node.plane_tier || "").trim(),
      badges: Array.isArray(entry.node.badges) ? entry.node.badges : [],
    };
  }

  function normalizePreviewTier(value) {
    const raw = String(value || "").trim().toLowerCase();
    if (!raw) return "";
    if (raw === "t0" || raw === "t1" || raw === "t2") return raw;
    if (raw === "p" || raw === "c" || raw === "h") return raw;
    return raw;
  }

  function boardSlotMetaFromReachabilityTree(node) {
    const entry = findReachabilityNodeEntry(node);
    if (!entry) return null;
    const treeNode = entry.node;
    const parent = entry.parent;
    const layoutZone = String(treeNode?.board_layout_zone || "").trim();
    const component = String(treeNode?.badges?.[0] || "").trim();
    let chartIndex = -1;
    if (component === "chart" && layoutZone && parent && Array.isArray(parent.children)) {
      const chartSiblings = parent.children.filter((child) => {
        return (
          String(child?.board_layout_zone || "").trim() === layoutZone &&
          String(child?.badges?.[0] || "").trim() === "chart"
        );
      });
      chartIndex = chartSiblings.findIndex(
        (child) => String(child?.node_id || "").trim() === String(node || "").trim(),
      );
    }
    return { layoutZone, component, chartIndex };
  }

  function readSceneDrilldownContext() {
    const el = document.getElementById("mei-scene-drilldown-context");
    if (!el) return null;
    try {
      const parsed = JSON.parse(el.textContent || "{}");
      return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null;
    } catch (_) {
      return null;
    }
  }

  function boardLayoutZoneFromTreeLink(node) {
    const raw = String(node || "").trim();
    if (!raw) return "";
    const link = document.querySelector(
      `.build-reachability-tree a[data-build-node="${CSS.escape(raw)}"]`,
    );
    return String(link?.getAttribute("data-board-layout-zone") || "").trim();
  }

  function projectionSlotsForBoardScene(sceneId) {
    const ctx = readSceneDrilldownContext();
    const assembly = ctx?.scene_projection_assembly_by_id?.[sceneId];
    const raw = assembly?.projection_slots;
    return Array.isArray(raw) ? raw : [];
  }

  function resolveBoardSlotMeta(node, slotId) {
    const fromTree = boardSlotMetaFromReachabilityTree(node);
    const layoutZoneFromTree =
      String(fromTree?.layoutZone || "").trim() ||
      boardLayoutZoneFromTreeLink(node);
    const sceneId = sceneExportIdFromBoardNode(node);
    const slots = projectionSlotsForBoardScene(sceneId);
    const matched = slots.find((entry) => {
      const id = String(entry?.id || entry?.slot_id || "").trim();
      return id && id === slotId;
    });
    const component = String(
      fromTree?.component ||
        matched?.component ||
        matched?.as ||
        (slotId === "filter" ? "filter" : ""),
    ).trim();
    const layoutZone =
      layoutZoneFromTree ||
      String(matched?.layout_zone || matched?.layoutZone || "").trim() ||
      (slotId === "filter" ? "filter" : slotId);
    const chartIndex =
      typeof fromTree?.chartIndex === "number" && fromTree.chartIndex >= 0
        ? fromTree.chartIndex
        : chartSlotIndexForMeta({ slotId, layoutZone, component, sceneId });
    return { slotId, layoutZone, component, sceneId, chartIndex };
  }

  function chartSlotIndexForMeta(meta) {
    if (typeof meta?.chartIndex === "number" && meta.chartIndex >= 0) {
      return meta.chartIndex;
    }
    if (meta.component !== "chart") return -1;
    const slots = projectionSlotsForBoardScene(meta.sceneId).filter((entry) => {
      const zone = String(entry?.layout_zone || entry?.layoutZone || "").trim();
      const component = String(entry?.component || entry?.as || "").trim();
      return zone === meta.layoutZone && component === "chart";
    });
    return slots.findIndex((entry) => {
      const id = String(entry?.id || entry?.slot_id || "").trim();
      return id === meta.slotId;
    });
  }

  function resolveBoardSlotHighlightTargets(root, meta) {
    if (!meta?.slotId) return [];
    const tagged = root.querySelector(`[data-build-board-slot="${CSS.escape(meta.slotId)}"]`);
    if (tagged instanceof HTMLElement) return [tagged];

    const panel = root.querySelector(
      `[data-mei-panel-id="${CSS.escape(meta.layoutZone)}"]`,
    );
    if (!(panel instanceof HTMLElement)) return [];

    const isChart =
      meta.component === "chart" ||
      (!meta.component && meta.layoutZone === "chart");
    if (isChart) {
      const chartIndex = chartSlotIndexForMeta(meta);
      if (chartIndex >= 0) {
        const chartSlot = panel.querySelector(
          `[data-chart-slot-index="${chartIndex}"]`,
        );
        if (chartSlot instanceof HTMLElement) return [chartSlot];
      }
      const chartSlots = panel.querySelectorAll("[data-chart-slot-index]");
      if (chartSlots.length === 1) return [chartSlots[0]];
    }
    const panelBody = panel.querySelector(
      "[data-mei-panel-body='true'], .preview-panel-body, .panel-body-cell",
    );
    return [panelBody instanceof HTMLElement ? panelBody : panel];
  }

  const BOARD_SLOT_COMPANION_ZONES = new Set(["filter"]);

  function applyBoardSlotScopedPreview(root, meta) {
    if (!meta?.layoutZone) return;
    const keepZones = new Set([meta.layoutZone]);
    BOARD_SLOT_COMPANION_ZONES.forEach((zoneId) => keepZones.add(zoneId));

    root.querySelectorAll("[data-mei-panel-id]").forEach((el) => {
      const panelId = String(el.getAttribute("data-mei-panel-id") || "").trim();
      if (panelId && !keepZones.has(panelId)) {
        el.classList.add("build-preview-scoped-dim");
      }


/* ===== build-inspect-highlight/p2.js ===== */
    });

    if (meta.component === "chart" || meta.layoutZone === "chart") {
      const panel = root.querySelector(
        `[data-mei-panel-id="${CSS.escape(meta.layoutZone)}"]`,
      );
      const chartIndex = chartSlotIndexForMeta(meta);
      if (panel instanceof HTMLElement && chartIndex >= 0) {
        panel.querySelectorAll("[data-chart-slot-index]").forEach((el) => {
          if (String(el.getAttribute("data-chart-slot-index") || "") !== String(chartIndex)) {
            el.classList.add("build-preview-scoped-dim");
          }
        });
      }
    }

    syncBuildPreviewScopedChrome(root);
  }

  function applyScopedPreview(root) {
    const node = activeBuildNode();
    root.querySelectorAll("[data-preview-scope], [data-mei-panel-id], [data-chart-slot-index], [data-build-board-slot], [data-mei-use-key], [data-mei-tier], [data-mei-ui-scope]").forEach((el) => {
      el.classList.remove("build-preview-scoped-dim");
    });
    const boardSlot = boardSlotIdFromNode(node);
    if (boardSlot) {
      applyBoardSlotScopedPreview(root, resolveBoardSlotMeta(node, boardSlot));
      return;
    }
    if (node.startsWith("board-file:")) {
      syncBuildPreviewScopedChrome(root);
      return;
    }
    const templateUseKeys = templateUseKeysFromTree(node);
    if (templateUseKeys.length > 0 && !isTemplateAuthoringPreview()) {
      applyTemplateScopedPreview(root, templateUseKeys);
      return;
    }
    if (templateKeyFromNode(node) && isTemplateAuthoringPreview()) {
      syncBuildPreviewScopedChrome(root);
      return;
    }
    if (
      !node.startsWith("scene-panel:") &&
      !node.startsWith("scene-block:") &&
      !node.startsWith("ui-scope:")
    ) {
      syncBuildPreviewScopedChrome(root);
      return;
    }
    if (node.startsWith("ui-scope:")) {
      syncBuildPreviewScopedChrome(root);
      return;
    }
    const encoded = node.replace(/^scene-panel:/, "").replace(/^scene-block:/, "");
    const slash = encoded.indexOf("/");
    const scopePath = slash >= 0 ? encoded.slice(slash + 1) : "";
    if (!scopePath) return;
    const focusedScopeSelector = `[data-preview-scope="${CSS.escape(scopePath)}"], [data-preview-scope^="${CSS.escape(scopePath)}/"]`;
    root.querySelectorAll("[data-preview-scope]").forEach((el) => {
      const elScope = String(el.getAttribute("data-preview-scope") || "");
      if (elScope === scopePath || elScope.startsWith(`${scopePath}/`)) {
        return;
      }
      if (scopePath.startsWith(`${elScope}/`)) {
        return;
      }
      if (el.matches?.(focusedScopeSelector) || el.querySelector?.(focusedScopeSelector)) {
        return;
      }
      el.classList.add("build-preview-scoped-dim");
    });
    syncBuildPreviewScopedChrome(root);
  }

  function scrollIntoViewIfOne(matches, scrollRoot) {
    if (matches.length !== 1) return;
    const el = matches[0];
    const container =
      scrollRoot instanceof HTMLElement
        ? scrollRoot
        : el?.closest?.(".preview-pane-scroll");
    if (!(container instanceof HTMLElement) || !(el instanceof HTMLElement)) return;
    const elRect = el.getBoundingClientRect();
    const boxRect = container.getBoundingClientRect();
    const margin = 8;
    if (elRect.top < boxRect.top + margin) {
      container.scrollTop -= boxRect.top + margin - elRect.top;
    } else if (elRect.bottom > boxRect.bottom - margin) {
      container.scrollTop += elRect.bottom - boxRect.bottom + margin;
    }
  }

  function schedulePreviewRuntimeWake() {
    if (!isBuildRoute()) return;
    const tab = currentManageTab() || "overview";
    if (tab !== "preview") return;
    requestAnimationFrame(() => {
      try {
        global.dispatchEvent(
          new CustomEvent("meilang:preview-updated", {
            detail: { scope: "build-inspect" },
          }),
        );
      } catch (_) {}
    });
  }

  function applyHighlight(root) {
    try {
    const node = activeBuildNode();
    const focus = activeBuildFocus();
    clearHighlights(root);
    if (!node || !node.startsWith("ui-scope:")) {
      clearInspectModeAttributes(root);
      applyScopedPreview(root);
    }

    let focusEl = null;
    if (focus && focus.startsWith("scene-block:")) {
      const focusMatches = root.querySelectorAll(`[data-build-focus="${CSS.escape(focus)}"]`);
      focusMatches.forEach((el) => el.classList.add("build-inspect-focus-selected"));
      scrollIntoViewIfOne(focusMatches, root);
      focusEl = focusMatches[0] || null;
    }

    if (node.startsWith("ui-scope:")) {
      const meta = readUiScopeMetaFromNode(node);
      const role = String(meta?.ui_role || "").trim().toLowerCase();
      let selected = [];
      if (role === "plane" && meta?.plane_tier) {
        const tier = normalizePreviewTier(meta.plane_tier);
        selected = Array.from(root.querySelectorAll("[data-mei-tier]")).filter(
          (el) => normalizePreviewTier(el.getAttribute("data-mei-tier")) === tier,
        );
        if (selected.length === 0) {
          const stage = root.querySelector(
            ".preview-stage, .preview-surface, .preview-stage-shell, [class*='map-host'], [class*='cockpit-map']",
          );
          if (stage instanceof HTMLElement) selected = [stage];
        }
      } else if (role !== "scene") {
        selected = resolveUiScopeHighlightTargets(root, node, meta);
      }
      if (selected.length > 1) {
        selected = [selected[0]];
      }
      selected.forEach((el) => el.classList.add("build-inspect-selected"));
      applyInspectFocusChrome(root, meta, node);
      if (!focusEl) {
        scrollIntoViewIfOne(selected, root);
      }
      updateInspectBar(node, focus, focusEl || selected[0] || null);
      return;
    }

    if (node && (node.startsWith("scene-panel:") || node.startsWith("scene-block:"))) {
      const matches = root.querySelectorAll(`[data-build-node="${CSS.escape(node)}"]`);
      let selected = Array.from(matches);
      if (focus && focus.startsWith("scene-block:")) {
        const focusScoped = selected.filter(
          (el) => String(el.getAttribute("data-build-focus") || "").trim() === focus,
        );
        if (focusScoped.length > 0) {
          selected = focusScoped;
        }
      }
      if (selected.length > 1) {
        selected = [selected[0]];
      }
      selected.forEach((el) => el.classList.add("build-inspect-selected"));
      if (!focusEl) {
        scrollIntoViewIfOne(selected, root);
      }
      updateInspectBar(node, focus, focusEl || selected[0] || null);
      return;
    }

    if (node.startsWith("board-slot:")) {
      const slotId = boardSlotIdFromNode(node);
      const meta = resolveBoardSlotMeta(node, slotId);
      const selected = resolveBoardSlotHighlightTargets(root, meta);
      selected.forEach((el) => el.classList.add("build-inspect-selected"));
      scrollIntoViewIfOne(selected, root);
      updateInspectBar(node, focus, selected[0] || null);
      return;
    }

    if (node.startsWith("board-file:")) {
      updateInspectBar(node, focus, null);
      return;
    }

    if (node.startsWith("template:")) {
      if (isTemplateAuthoringPreview()) {
        updateInspectBar(
          node,
          focus,
          null,
          "模板独立预览：展示内置示例场景与 props，非应用内使用处高亮。",
        );
        return;
      }
      const selected = [];
      for (const useKey of templateUseKeysFromTree(node)) {
        if (!useKey) continue;
        root
          .querySelectorAll(`[data-mei-use-key="${CSS.escape(useKey)}"]`)
          .forEach((el) => selected.push(el));
      }
      const uniqueSelected = Array.from(new Set(selected));
      uniqueSelected.forEach((el) => el.classList.add("build-inspect-selected"));
      scrollIntoViewIfOne(uniqueSelected, root);
      updateInspectBar(node, focus, uniqueSelected[0] || null);
      return;
    }

    updateInspectBar(node, focus, focusEl);
    } finally {
      const node = activeBuildNode();
      const prevUrl = String(global.__meiBuildNavPrevUrl || "").trim();
      const skipWake =
        (node && node.startsWith("ui-scope:")) ||
        (prevUrl &&
          typeof global.MeiBuildNavigation?.shouldSkipPreviewRuntimeWake === "function" &&
          global.MeiBuildNavigation.shouldSkipPreviewRuntimeWake(prevUrl, global.location.href));
      if (!skipWake) {
        schedulePreviewRuntimeWake();
      }
      global.__meiBuildNavPrevUrl = "";
    }
  }

  function currentManageTab() {
    try {
      return String(new URL(global.location.href).searchParams.get("tab") || "").trim().toLowerCase();
    } catch (_) {
      return "";
    }
  }

  function pushBuildUrl(mutator) {
    if (!isBuildRoute()) return;
    const shell = activeShell();
    const appPath = shell?.getAttribute("data-app-path") || "";
    if (!appPath) return;
    const url = new URL(global.location.href);
    mutator(url);
    const tab = currentManageTab() || String(shell?.getAttribute("data-build-tab") || "").trim().toLowerCase();
    if (tab) {
      url.searchParams.set("tab", tab);
    } else if (url.searchParams.get("tab") === "" || !url.searchParams.get("tab")) {
      url.searchParams.set("tab", "preview");
    }
    if (url.href === global.location.href) {
      applyHighlight(previewRoot() || document);
      return;
    }
    const prevUrl = global.location.href;
    if (typeof global.MeiBuildNavigation?.tryNavigateBuild === "function") {
      void global.MeiBuildNavigation.tryNavigateBuild(prevUrl, url.href, { replaceHistory: false });
      return;
    }
    global.history.pushState({}, "", url.href);
    global.dispatchEvent(new PopStateEvent("popstate"));
  }

  function readFocusFromUrl() {
    try {
      return String(new URL(global.location.href).searchParams.get("focus") || "").trim();
    } catch (_) {
      return "";
    }
  }

  function syncShellFocus(focus) {
    const shell = activeShell();
    if (!shell) return;
    shell.setAttribute("data-build-focus", focus || "");
  }

  function navigateToBuildNode(node) {
    if (!node) return;
    pushBuildUrl((url) => {
      url.searchParams.set("node", node);
      url.searchParams.delete("focus");
    });
    syncShellFocus("");
  }

  function navigateToBuildFocus(focus) {
    if (!focus) return;
    pushBuildUrl((url) => {
      url.searchParams.set("focus", focus);
      url.searchParams.set("tab", "preview");
    });
    syncShellFocus(focus);
  }

  function bindPreviewInspect(root) {
    if (!root || root.__buildInspectBound) return;
    root.__buildInspectBound = true;

    root.addEventListener(
      "click",
      (event) => {
        if (!isBuildRoute()) return;
        if (event.target.closest("[data-preview-zoom-bar]")) {
          return;
        }
        const blockTarget = event.target.closest(BLOCK_SELECTOR);
        if (blockTarget) {
          const focus = String(blockTarget.getAttribute("data-build-focus") || "").trim();
          if (focus) {
            event.preventDefault();
            event.stopPropagation();
            navigateToBuildFocus(focus);
          }
          return;
        }
        const panelTarget = event.target.closest(PANEL_SELECTOR);
        if (panelTarget) {
          const node = String(panelTarget.getAttribute("data-build-node") || "").trim();
          if (node) {
            event.preventDefault();
            event.stopPropagation();
            navigateToBuildNode(node);
          }
          return;
        }
        if (
          event.target.closest("a[href^='/apps/']") ||
          event.target.closest("[data-popup]") ||
          event.target.closest(".metric-card")?.closest("[role='button']")
        ) {
          event.preventDefault();
          event.stopPropagation();
        }
      },
      true,
    );
  }

  function boardMountKeyForSurface(surface) {
    if (!(surface instanceof HTMLElement)) return "";
    try {
      const url = new URL(global.location.href);
      const fromNode = String(url.searchParams.get("node") || "");
      const sceneId =
        sceneExportIdFromBoardNode(fromNode) ||
        String(surface.dataset.sceneId || "").trim() ||
        String(url.searchParams.get("scene") || "").trim();
      const target = String(
        surface.dataset.targetFile || surface.dataset.sourcePath || "",
      ).trim();
      return sceneId && target ? `${sceneId}::${target}` : "";
    } catch (_) {
      return "";
    }
  }

  function sceneExportIdFromBoardNode(nodeParam) {
    const node = String(nodeParam || "").trim();
    if (!/^board-(?:file|slot):/i.test(node)) return "";
    const payload = node.replace(/^board-(?:file|slot):/i, "");
    const slash = payload.indexOf("/");
    const boardKey = slash >= 0 ? payload.slice(0, slash) : payload;
    const hashAt = boardKey.indexOf("#");
    return hashAt >= 0 ? boardKey.slice(hashAt + 1).trim() : "";
  }

  function clearScopedPreviewDim(root) {
    if (!(root instanceof HTMLElement)) return;
    root.querySelectorAll(
      "[data-preview-scope].build-preview-scoped-dim, [data-mei-panel-id].build-preview-scoped-dim, [data-chart-slot-index].build-preview-scoped-dim, [data-build-board-slot].build-preview-scoped-dim",
    ).forEach((el) => {
      el.classList.remove("build-preview-scoped-dim");
    });
    document.body.classList.remove("build-preview-scoped-active");
  }

  function clearStaleBoardMount(root) {
    if (!(root instanceof HTMLElement)) return false;
    let cleared = false;
    root.querySelectorAll(".preview-surface, .preview-stage").forEach((surface) => {
      if (!(surface instanceof HTMLElement)) return;
      const mounted = surface.dataset.meiPreviewBoardMounted;
      if (!mounted) return;
      const expected = boardMountKeyForSurface(surface);
      if (expected && mounted === expected) return;
      delete surface.dataset.meiPreviewBoardMounted;
      surface.classList.remove("preview-board-mounted");
      cleared = true;
    });
    return cleared;
  }
  function refresh(event) {
    if (!isBuildRoute()) return;
    const eventScope = String(event?.detail?.scope || event?.scope || "").trim();
    if (eventScope === "build-inspect") {
      const root = previewRoot();
      if (!root) return;
      syncShellFocus(readFocusFromUrl());
      applyHighlight(root);
      return;
    }
    document.body.classList.remove("access-drilldown-open", "access-scene-board-open");
    const root = previewRoot();
    if (!root) return;
    clearScopedPreviewDim(root);
    const scope = String(event?.detail?.scope || "").trim();
    if (scope !== "manage-board-preview") {
      clearStaleBoardMount(root);
    }
    syncShellFocus(readFocusFromUrl());
    bindPreviewInspect(root);
    applyHighlight(root);
  }

  function bind() {
    if (!isBuildRoute()) return;
    refresh(null);
    global.addEventListener("mei:manage-tab-change", refresh);
    global.addEventListener("meilang:preview-updated", refresh);
    global.addEventListener("popstate", refresh);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", bind);
  } else {
    bind();
  }

  global.MeiBuildInspectHighlight = { refresh, navigateToBuildNode, navigateToBuildFocus };
})(window);


/* ===== build-exec-panel.js ===== */
/**
 * Build view exec REPL panel (metric/query smoke).
 */
(function (global) {
  "use strict";

  function storageKey(appPath, node) {
    return "mei.build.exec." + appPath + "." + node;
  }

  function initBuildExecPanel() {
    const panel = document.getElementById("build-exec-panel");
    if (!panel || panel.__bound) return;
    panel.__bound = true;
    const appPath = panel.getAttribute("data-app-path");
    const node = panel.getAttribute("data-node");
    const output = document.getElementById("build-exec-output");
    const runBtn = document.getElementById("build-exec-run");
    let scope = "warmup";

    panel.querySelectorAll(".build-exec-scope").forEach((btn) => {
      btn.addEventListener("click", () => {
        scope = btn.getAttribute("data-scope") || "warmup";
        panel.querySelectorAll(".build-exec-scope").forEach((b) => b.classList.remove("is-active"));
        btn.classList.add("is-active");
      });
    });

    if (runBtn) {
      runBtn.addEventListener("click", async () => {
        if (!output) return;
        output.textContent = "running…";
        try {
          const res = await fetch(
            "/api/build/context/export?" +
              new URLSearchParams({
                app_id: appPath,
                node,
                tab: "exec",
                intent: "debug_eval",
                scope,
              }).toString()
          );
          const text = await res.text();
          output.textContent = text;
          try {
            sessionStorage.setItem(
              storageKey(appPath, node),
              JSON.stringify({ scope, text, at: Date.now() })
            );
          } catch (_) {}
        } catch (err) {
          output.textContent = String(err);
        }
      });
    }
  }

  global.__meiBuildExecPanelInit = initBuildExecPanel;
})(typeof window !== "undefined" ? window : globalThis);


/* ===== manage-diagnostics.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.manageDiagnosticsMounted) return;
  boot.manageDiagnosticsMounted = true;
  const LAYOUT_AUDIT_EVENT = "mei:layout-audit";

  function root() {
    return document.getElementById("mei-manage-diagnostics-root");
  }

  function filterModeFromUrl() {
    try {
      const url = new URL(window.location.href);
      return url.searchParams.get("diag_filter") === "all" ? "all" : "current";
    } catch (_) {
      return "current";
    }
  }

  function syncFilterLinks() {
    const node = root();
    if (!node) return;
    const mode = filterModeFromUrl();
    node.setAttribute("data-mei-diag-filter", mode);
    document.querySelectorAll("[data-mei-diag-filter-link]").forEach((link) => {
      const value = String(link.getAttribute("data-mei-diag-filter-link") || "");
      const active = value === mode;
      link.classList.toggle("is-active", active);
      if (active) {
        link.setAttribute("aria-current", "true");
      } else {
        link.removeAttribute("aria-current");
      }
    });
  }

  function layoutAuditRoot() {
    return document.getElementById("mei-runtime-layout-audit");
  }

  function currentLayoutAuditSource() {
    try {
      const url = new URL(window.location.href);
      return String(url.searchParams.get("file") || "main.mei").trim() || "main.mei";
    } catch (_) {
      return "main.mei";
    }
  }

  function layoutAuditStorageKey(sourcePath) {
    const pathname = String(window.location.pathname || "").trim();
    const source = String(sourcePath || currentLayoutAuditSource()).trim() || "main.mei";
    return `mei:layout-audit:${pathname}:${source}`;
  }

  function isCurrentLayoutAudit(detail) {
    if (!detail || typeof detail !== "object") return false;
    return String(detail.sourcePath || "").trim() === currentLayoutAuditSource();
  }

  function readCachedLayoutAudit() {
    try {
      const raw = sessionStorage.getItem(layoutAuditStorageKey());
      if (!raw) return null;
      const detail = JSON.parse(raw);
      return detail && typeof detail === "object" ? detail : null;
    } catch (_) {
      return null;
    }
  }

  function currentLayoutAuditDetail() {
    const live = isCurrentLayoutAudit(window.__meiLastLayoutEval) ? window.__meiLastLayoutEval : null;
    return live || readCachedLayoutAudit();
  }

  function escapeHtml(input) {
    return String(input ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  }

  function severityClass(severity) {
    const value = String(severity || "").trim().toLowerCase();
    if (value === "error") return "text-red-300 border-red-400/35 bg-red-950/25";
    if (value === "warning")
      return "text-amber-200 border-amber-300/35 bg-amber-950/20";
    return "text-cyan-200 border-cyan-300/30 bg-cyan-950/20";
  }

  function layoutEvalStatus(detail) {
    if (detail?.blocking) return "阻塞";
    if (Array.isArray(detail?.diagnostics) && detail.diagnostics.length) return "警告";
    return "通过";
  }

  function renderLayoutAudit(detail) {
    const node = layoutAuditRoot();
    if (!node) return;
    const diagnostics = Array.isArray(detail?.diagnostics) ? detail.diagnostics : [];
    const emptyText =
      String(node.getAttribute("data-empty-text") || "").trim() ||
      "尚未发现布局几何问题。";
    const metrics = detail?.metrics && typeof detail.metrics === "object" ? detail.metrics : {};
    const worstPanels = Array.isArray(detail?.worstPanels) ? detail.worstPanels : [];
    if (!diagnostics.length) {
      node.textContent = emptyText;
      return;
    }
    const summary = `
      <div class="rounded-lg border border-slate-700/70 bg-slate-950/40 px-2.5 py-2">
        <div class="flex flex-wrap items-center gap-2 text-[11px]">
          <strong class="text-slate-50">状态：${escapeHtml(layoutEvalStatus(detail))}</strong>
          <span class="text-slate-300">score=${escapeHtml(detail?.score ?? 0)}</span>
          <span class="text-slate-400">error ${escapeHtml(metrics.errors ?? 0)} / warning ${escapeHtml(metrics.warnings ?? 0)} / info ${escapeHtml(metrics.infos ?? 0)}</span>
        </div>
        ${
          worstPanels.length
            ? `<div class="mt-1 text-[10px] text-slate-400">worstPanels: ${worstPanels
                .map((panel) => `${escapeHtml(panel.panelId || "unknown")}(${escapeHtml(panel.score || 0)})`)
                .join("、")}</div>`
            : ""
        }
      </div>
    `;
    const items = diagnostics
      .map((diag) => {
        const code = escapeHtml(diag?.code || "layout_eval_runtime");
        const message = escapeHtml(diag?.message || "检测到布局问题");
        const source = escapeHtml(
          diag?.target_file || diag?.source_path || detail?.targetFile || detail?.sourcePath || "当前预览"
        );
        const sceneId = escapeHtml(diag?.scene_id || detail?.sceneId || "");
        const severity = severityClass(diag?.severity || "warning");
        const panelId = escapeHtml(diag?.panelId || "");
        const panelLabel = escapeHtml(diag?.panelLabel || "");
        const componentLabel = escapeHtml(diag?.component_label || "");
        return `
          <div class="mt-2 grid gap-1 rounded-lg border px-2.5 py-2 ${severity}">
            <strong class="text-[11px] font-semibold">${code}</strong>
            <span class="text-[11px] leading-5 text-slate-100">${message}</span>
            ${
              panelId
                ? `<span class="text-[10px] font-mono text-slate-300">panel：${panelId}${panelLabel ? ` · ${panelLabel}` : ""}</span>`
                : ""
            }
            ${
              componentLabel
                ? `<span class="text-[10px] font-mono text-slate-300">component：${componentLabel}</span>`
                : ""
            }
            ${sceneId ? `<span class="text-[10px] font-mono text-slate-400">scene：${sceneId}</span>` : ""}
            <span class="text-[10px] font-mono text-slate-400">来源：${source}</span>
          </div>
        `;
      })
      .join("");
    node.innerHTML = summary + items;
  }

  syncFilterLinks();
  renderLayoutAudit(currentLayoutAuditDetail());
  document.addEventListener("mei:manage-context-change", () => {
    syncFilterLinks();
    renderLayoutAudit(currentLayoutAuditDetail());
  });
  document.addEventListener("mei:manage-tab-change", () => {
    syncFilterLinks();
    renderLayoutAudit(currentLayoutAuditDetail());
  });
  document.addEventListener(LAYOUT_AUDIT_EVENT, (event) => {
    if (!isCurrentLayoutAudit(event?.detail || null)) return;
    renderLayoutAudit(event?.detail || null);
  });
  window.addEventListener("message", (event) => {
    if (event.origin !== window.location.origin) return;
    if (event.data?.type !== LAYOUT_AUDIT_EVENT) return;
    if (!isCurrentLayoutAudit(event.data?.detail || null)) return;
    renderLayoutAudit(event.data?.detail || null);
  });
})();


/* ===== statusbar.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.statusBarMounted) return;
  boot.statusBarMounted = true;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function els() {
    return {
      compliance: document.getElementById("mei-status-compliance"),
      hostVersion: document.getElementById("mei-status-host-version"),
    };
  }

  function setChip(node, text, tone, title) {
    if (!node) return;
    node.textContent = text;
    node.title = title || text;
    node.dataset.tone = tone || "neutral";
  }

  function applyComplianceChip() {
    const nodes = els();
    if (!nodes.compliance) return;
    const parts = [
      readMeta("mei-host-icp-record"),
      readMeta("mei-host-psb-record"),
      readMeta("mei-host-copyright"),
    ].filter(Boolean);
    if (!parts.length) {
      nodes.compliance.hidden = true;
      nodes.compliance.textContent = "";
      return;
    }
    nodes.compliance.hidden = false;
    const text = parts.join(" · ");
    setChip(nodes.compliance, text, "neutral", text);
  }

  function applyHostVersionChip() {
    const nodes = els();
    const label = readMeta("mei-host-version-label");
    const version = readMeta("mei-host-version");
    const text = label || (version ? "Mei " + version : "");
    if (!text) return;
    setChip(nodes.hostVersion, text, "neutral", text);
  }

  function start() {
    applyComplianceChip();
    applyHostVersionChip();
  }

  boot.disposeStatusBar = function () {
    boot.statusBarMounted = false;
  };
  start();
})();


